if (!class_exists('Ptero_AI_OpenAI_Compat')) {
    class Ptero_AI_OpenAI_Compat {
        const DEFAULT_MODE = 'full';

        public static function supported_modes() {
            return array('fast', 'complex', 'quick', 'full', 'agent');
        }

        private static function normalize_mode($requested) {
            $mode = sanitize_key((string) $requested);
            if ('' === $mode) {
                return self::DEFAULT_MODE;
            }
            if (!in_array($mode, self::supported_modes(), true)) {
                return new WP_Error(
                    'invalid_mode',
                    'Invalid mode. Supported modes: fast, complex, quick, full, agent.',
                    array(
                        'status' => 400,
                        'supported_modes' => self::supported_modes(),
                    )
                );
            }
            return $mode;
        }

        private static function agent_prompt($request, $body, $task) {
            $workspace = '';
            if (isset($body['project_id']) && function_exists('ptero_ai_chat_agent_workspace_context')) {
                $workspace = ptero_ai_chat_agent_workspace_context(
                    $request,
                    sanitize_text_field((string) $body['project_id'])
                );
            }
            $directive = 'AGENT MODE: Act as a senior autonomous software agent. First understand the user objective and constraints, then make a concise plan. Investigate the supplied files, conversation context, repository context, and available web/GitHub tools before deciding. Work in explicit stages: PLAN, READ, EDIT, and CHECK. For large code, preserve existing behavior, make complete coherent changes, and never replace unseen code with placeholders. Use available tools when they materially improve accuracy. Validate the result mentally and check edge cases, security, compatibility, and likely runtime failures before responding. Ask a question only when a missing decision blocks progress; otherwise make a sensible assumption and continue. Finish with a concise implementation summary, verification notes, and any remaining limitation. Do not claim to have edited or executed files unless the available tools or supplied files support that claim. IMPORTANT: Do not stop after a PLAN, READ, EDIT, or CHECK status line. Continue working through the task and return the complete final answer in this same response. The user must receive the requested result, not only a progress update. Return the final answer as ordinary text and code blocks without status-line prefixes.';
            $safe_workspace = $workspace ? $workspace . "\n\n" : '';
            return $directive . "\n\n" . $safe_workspace . 'USER TASK:' . "\n" . $task;
        }

        public static function boot() {
            add_action('rest_api_init', array(__CLASS__, 'register_routes'));
            add_filter('do_shortcode_tag', array(__CLASS__, 'append_api_documentation'), 20, 4);
        }

        public static function register_routes() {
            foreach (array(
                '/chat/completions' => 'chat_completions',
                '/responses' => 'responses',
                '/models' => 'models',
            ) as $route => $callback) {
                register_rest_route('mlp/v1', $route, array(
                    'methods' => '/models' === $route ? WP_REST_Server::READABLE : WP_REST_Server::CREATABLE,
                    'callback' => array(__CLASS__, $callback),
                    'permission_callback' => array(__CLASS__, 'permission_check'),
                ));
            }
        }

        public static function permission_check($request) {
            if ('1' === (string) get_option('mlp_ai_chat_disabled', '0')) {
                return new WP_Error(
                    'api_maintenance',
                    'The AI API is temporarily disabled for maintenance.',
                    array('status' => 503)
                );
            }
            /*
             * Keep the existing Bearer-token API-key path active, while also
             * accepting the X-API-Key spelling documented by this plugin.
             */
            if (!$request->get_header('authorization') && $request->get_header('x-api-key')) {
                $request->set_header('authorization', 'Bearer ' . trim((string) $request->get_header('x-api-key')));
            }
            return MLP_AI_Chat::instance()->permission_check($request);
        }

