        private static function text($value) {
            if (is_string($value) || is_numeric($value)) {
                return (string) $value;
            }
            if (!is_array($value)) {
                return '';
            }
            $parts = array();
            foreach ($value as $part) {
                if (is_string($part) || is_numeric($part)) {
                    $parts[] = (string) $part;
                } elseif (is_array($part) && isset($part['text'])) {
                    $parts[] = self::text($part['text']);
                } elseif (is_array($part) && isset($part['content'])) {
                    $parts[] = self::text($part['content']);
                } elseif (is_array($part) && !empty($part['type']) && false !== strpos((string) $part['type'], 'image')) {
                    $parts[] = '[Image input]';
                }
            }
            return implode("\n", $parts);
        }

        private static function model($requested) {
            $requested = sanitize_text_field((string) $requested);
            $aliases = array(
            );
            if (isset($aliases[$requested])) {
                return $aliases[$requested];
            }
            $raw = defined('MLP_AI_CHAT_MODELS') ? @unserialize(MLP_AI_CHAT_MODELS, array('allowed_classes' => false)) : array();
            if (!is_array($raw) || isset($raw[$requested])) {
                return $requested;
            }
            foreach ($raw as $id => $config) {
                if (is_array($config) && isset($config['api_model']) && $requested === (string) $config['api_model']) {
                    return (string) $id;
                }
            }
            return $requested;
        }

        private static function messages($body, $responses_mode) {
            $messages = array();
            if ($responses_mode) {
                if (isset($body['instructions']) && '' !== self::text($body['instructions'])) {
                    $messages[] = array('role' => 'system', 'content' => $body['instructions']);
                }
                $input = isset($body['input']) ? $body['input'] : '';
                if (is_string($input)) {
                    $messages[] = array('role' => 'user', 'content' => $input);
                } elseif (is_array($input)) {
                    foreach ($input as $item) {
                        if (is_string($item)) {
                            $messages[] = array('role' => 'user', 'content' => $item);
                        } elseif (is_array($item)) {
                            if (isset($item['role'])) {
                                $messages[] = array(
                                    'role' => sanitize_key((string) $item['role']),
                                    'content' => isset($item['content']) ? $item['content'] : '',
                                );
                            } elseif ('message' === (isset($item['type']) ? $item['type'] : '')) {
                                $messages[] = array(
                                    'role' => isset($item['role']) ? $item['role'] : 'user',
                                    'content' => isset($item['content']) ? $item['content'] : '',
                                );
                            } elseif (isset($item['text'])) {
                                $role = !empty($item['type']) && false !== strpos((string) $item['type'], 'output_') ? 'assistant' : 'user';
                                $messages[] = array('role' => $role, 'content' => $item['text']);
                            } elseif (!empty($item['type']) && false !== strpos((string) $item['type'], 'image')) {
                                $messages[] = array('role' => 'user', 'content' => '[Image input]');
                            }
                        }
                    }
                }
            } else {
                $messages = isset($body['messages']) ? $body['messages'] : array();
            }
            if (!is_array($messages) || empty($messages)) {
                return new WP_Error('invalid_request', 'messages/input must contain at least one message.', array('status' => 400));
            }
            $system = array();
            $turns = array();
            foreach ($messages as $item) {
                if (!is_array($item)) {
                    continue;
                }
                $role = strtolower(isset($item['role']) ? (string) $item['role'] : 'user');
                $content = self::text(isset($item['content']) ? $item['content'] : '');
                if ('system' === $role || 'developer' === $role) {
                    if ($content !== '') {
                        $system[] = $content;
                    }
                    continue;
                }
                if ('tool' === $role) {
                    $content = "Tool result:\n" . $content;
                    $role = 'user';
                }
                if (!empty($item['tool_calls']) && is_array($item['tool_calls'])) {
                    $calls = array();
                    foreach ($item['tool_calls'] as $call) {
                        if (is_array($call)) {
                            $name = isset($call['function']['name']) ? $call['function']['name'] : 'tool';
                            $calls[] = (string) $name;
                        }
                    }
                    if ($calls) {
                        $content .= ($content ? "\n" : '') . 'Requested tool calls: ' . implode(', ', $calls);
                    }
                }
                $turns[] = array('role' => 'assistant' === $role ? 'assistant' : 'user', 'text' => $content);
            }
            if (empty($turns)) {
                return new WP_Error('invalid_request', 'At least one user message is required.', array('status' => 400));
            }
            $current = array_pop($turns);
            $message = isset($current['text']) ? (string) $current['text'] : '';
            if ($system) {
                $message = "Client system instructions:\n" . implode("\n\n", $system) . "\n\n" . $message;
            }
            $mode = self::normalize_mode(isset($body['mode']) ? $body['mode'] : '');
            if (is_wp_error($mode)) {
                return $mode;
            }
            return array(
                'model' => self::model(isset($body['model']) ? $body['model'] : ''),
                'message' => $message,
                'history' => $turns,
                'mode' => $mode,
                'project_id' => isset($body['project_id']) ? sanitize_text_field((string) $body['project_id']) : '',
            );
        }

        private static function count_tokens($value) {
            $length = strlen(trim((string) $value));
            return $length ? max(1, (int) ceil($length / 4)) : 0;
        }

        private static function inner($response) {
            if (is_wp_error($response)) {
                return $response;
            }
            return is_object($response) && method_exists($response, 'get_data') ? $response->get_data() : $response;
        }

        private static function completion($request, $body, $responses_mode) {
            $normalized = self::messages($body, $responses_mode);
            if (is_wp_error($normalized)) {
                return $normalized;
            }
            $provider_body = $normalized;
            if ('agent' === $normalized['mode']) {
                $provider_body['message'] = self::agent_prompt($request, $body, $normalized['message']);
                /*
                 * The core chat handler currently accepts the four UI modes
                 * below. Agent mode is implemented here as an orchestration
                 * directive while retaining the full-output budget.
                 */
                $provider_body['mode'] = 'full';
            }
            $request->set_body(wp_json_encode($provider_body));
            $request->set_header('content-type', 'application/json');
            $result = self::inner(MLP_AI_Chat::instance()->rest_chat($request));
            if (is_wp_error($result)) {
                return $result;
            }
            $text = isset($result['reply']) ? (string) $result['reply'] : '';
            $id = 'chatcmpl-' . str_replace('-', '', function_exists('wp_generate_uuid4') ? wp_generate_uuid4() : uniqid('', true));
            $prompt_tokens = self::count_tokens(wp_json_encode(isset($body['messages']) ? $body['messages'] : (isset($body['input']) ? $body['input'] : '')));
            $completion_tokens = self::count_tokens($text);
            return array(
                'id' => $id,
                'object' => 'chat.completion',
                'created' => time(),
                'model' => isset($result['model_used']) ? $result['model_used'] : $normalized['model'],
                'mode' => $normalized['mode'],
                'choices' => array(array(
                    'index' => 0,
                    'message' => array('role' => 'assistant', 'content' => $text),
                    'finish_reason' => 'stop',
                )),
                'usage' => array(
                    'prompt_tokens' => $prompt_tokens,
                    'completion_tokens' => $completion_tokens,
                    'total_tokens' => $prompt_tokens + $completion_tokens,
                ),
            );
        }

        private static function stream($payload) {
            $response = new WP_REST_Response(null, 200);
            $response->header('Content-Type', 'text/event-stream');
            $response->header('Cache-Control', 'no-cache');
            $response->header('Connection', 'keep-alive');
            $response->header('X-Accel-Buffering', 'no');
            add_filter('rest_pre_serve_request', function ($served, $result) use ($response, $payload) {
                if ($result !== $response) {
                    return $served;
                }
                $choice = $payload['choices'][0];
                $base = array(
                    'id' => $payload['id'],
                    'object' => 'chat.completion.chunk',
                    'created' => $payload['created'],
                    'model' => $payload['model'],
                    'mode' => isset($payload['mode']) ? $payload['mode'] : self::DEFAULT_MODE,
                );
                $base['choices'] = array(array(
                    'index' => 0,
                    'delta' => array('role' => 'assistant'),
                    'finish_reason' => null,
                ));
                echo 'data: ' . wp_json_encode($base) . "\n\n";
                $content = (string) $choice['message']['content'];
                foreach (str_split($content, 800) as $chunk) {
                    if ('' === $chunk) {
                        continue;
                    }
                    $base['choices'][0]['delta'] = array('content' => $chunk);
                    echo 'data: ' . wp_json_encode($base) . "\n\n";
                    if (function_exists('flush')) {
                        flush();
                    }
                }
                $base['choices'][0]['delta'] = array();
                $base['choices'][0]['finish_reason'] = 'stop';
                if (!empty($payload['usage'])) {
                    $base['usage'] = $payload['usage'];
                }
                echo 'data: ' . wp_json_encode($base) . "\n\n";
                echo "data: [DONE]\n\n";
                return true;
            }, 10, 2);
            return $response;
        }

        public static function chat_completions($request) {
            $body = $request->get_json_params();
            if (!is_array($body)) {
                return new WP_Error('invalid_request', 'Request body must be JSON.', array('status' => 400));
            }
            $result = self::completion($request, $body, false);
            if (is_wp_error($result)) {
                return $result;
            }
            return !empty($body['stream']) ? self::stream($result) : rest_ensure_response($result);
        }

        public static function responses($request) {
            $body = $request->get_json_params();
            if (!is_array($body)) {
                return new WP_Error('invalid_request', 'Request body must be JSON.', array('status' => 400));
            }
            $result = self::completion($request, $body, true);
            if (is_wp_error($result)) {
                return $result;
            }
            $text = $result['choices'][0]['message']['content'];
            $suffix = str_replace('-', '', substr($result['id'], 9));
            return rest_ensure_response(array(
                'id' => 'resp_' . $suffix,
                'object' => 'response',
                'created_at' => $result['created'],
                'status' => 'completed',
                'model' => $result['model'],
                'mode' => isset($result['mode']) ? $result['mode'] : self::DEFAULT_MODE,
                'output' => array(array(
                    'id' => 'msg_' . $suffix,
                    'type' => 'message',
                    'status' => 'completed',
                    'role' => 'assistant',
                    'content' => array(array('type' => 'output_text', 'text' => $text, 'annotations' => array())),
                )),
                'output_text' => $text,
                'usage' => array(
                    'input_tokens' => $result['usage']['prompt_tokens'],
                    'output_tokens' => $result['usage']['completion_tokens'],
                    'total_tokens' => $result['usage']['total_tokens'],
                ),
            ));
        }

        public static function models() {
            $raw = defined('MLP_AI_CHAT_MODELS') ? @unserialize(MLP_AI_CHAT_MODELS, array('allowed_classes' => false)) : array();
            $items = array();
            $seen = array();
            if (is_array($raw)) {
                foreach ($raw as $id => $config) {
                    $seen[(string) $id] = true;
                    $items[] = array(
                        'id' => (string) $id,
                        'object' => 'model',
                        'created' => time(),
                        'owned_by' => is_array($config) && isset($config['provider']) ? (string) $config['provider'] : 'ptero',
                    );
                }
            }

            return rest_ensure_response(array(
                'object' => 'list',
                'data' => $items,
                'supported_modes' => self::supported_modes(),
                'default_mode' => self::DEFAULT_MODE,
            ));
        }
    }
    if (function_exists('add_action')) {
        Ptero_AI_OpenAI_Compat::boot();
    }
