import requests
import json

API_KEY = "your_api_key_here"
BASE_URL = "https://api.example.com/v1"

def chat_completion(message, model="mercury-2"):
    headers = {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json"
    }
    
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": message}],
        "temperature": 0.7,
        "max_tokens": 500
    }
    
    response = requests.post(
        f"{BASE_URL}/chat/completions",
        headers=headers,
        json=payload
    )
    
    if response.status_code == 200:
        data = response.json()
        return data['choices'][0]['message']['content']
    else:
        print(f"Error: {response.json()}")
        return None

# Usage
result = chat_completion("What is the capital of France?")
print(result)
CODE),'php'=>array('language'=>'php','code'=><<<'CODE'
<?php

$apiKey = "your_api_key_here";
$baseUrl = "https://api.example.com/v1";

function chatCompletion($message, $model = "mercury-2") {
    global $apiKey, $baseUrl;
    
    $headers = [
        "Authorization: Bearer " . $apiKey,
        "Content-Type: application/json"
    ];
    
    $payload = json_encode([
        "model" => $model,
        "messages" => [["role" => "user", "content" => $message]],
        "temperature" => 0.7,
        "max_tokens" => 500
    ]);
    
    $ch = curl_init($baseUrl . "/chat/completions");
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    
    $response = curl_exec($ch);
    curl_close($ch);
    
    $data = json_decode($response, true);
    return $data['choices'][0]['message']['content'] ?? null;
}

echo chatCompletion("What is the capital of France?");
?>
