SUM(requests) AS requests,
SUM(tokens) AS tokens,
SUM(failures) AS failures,
SUM(latency_ms_total) AS latency_ms_total,
SUM(latency_samples) AS latency_samples
FROM $usage_table
WHERE bucket_start >= %s
