[$id]:array();$cooldown_left=$this->model_unavailable_seconds_left($id);$message=isset($row['message'])?$row['message']:'';if($is_disabled){$state='disabled';$message='Disabled by admin';}elseif(!$has_key){$state='offline';$message='API key not configured';}elseif($cooldown_left>0){$state='cooldown';$message=trim(($message?$message.' — ':'').'retrying automatically in '.ceil($cooldown_left/60).' min');}$models_out[]=array('id'=>$id,'label'=>$cfg['label'],'configured'=>$has_key,'disabled'=>$is_disabled,'state'=>$state,'state_label'=>isset($state_labels[$state])?$state_labels[$state]:ucfirst($state),'message'=>$message,'last_checked'=>isset($row['last_checked'])?$row['last_checked']:'','cooldown_left'=>$cooldown_left,'likes'=>isset($fb['likes'])?(int)$fb['likes']:0,'dislikes'=>isset($fb['dislikes'])?(int)$fb['dislikes']:0,'requests'=>isset($usage_by_model[$id]['requests'])?(int)$usage_by_model[$id]['requests']:0,'tokens'=>isset($usage_by_model[$id]['tokens'])?(int)$usage_by_model[$id]['tokens']:0,'failures'=>isset($usage_by_model[$id]['failures'])?(int)$usage_by_model[$id]['failures']:0,'avg_latency_ms'=>isset($usage_by_model[$id]['avg_latency_ms'])?(int)$usage_by_model[$id]['avg_latency_ms']:0,);}$result=array('disabled'=>$this->is_ai_disabled(),'total_requests'=>(int)get_option('mlp_ai_chat_total_requests',0),'new_today'=>$new_today,'all_users'=>$all_users,'usage'=>$usage_summary,'models'=>$models_out,);set_transient($cache_key,$result,MLP_AI_CHAT_DASHBOARD_CACHE_SECONDS);return $result;}private function invalidate_admin_dashboard_cache(){delete_transient('mlp_ai_chat_dashboard_data');}public function register_routes(){register_rest_route('mlp/v1','/chat',array(array('methods'=>'POST','callback'=>array($this,'rest_chat'),'permission_callback'=>array($this,'permission_check'),),));register_rest_route('mlp/v1','/chat-stream',array(array('methods'=>'POST','callback'=>array($this,'rest_chat_stream'),'permission_callback'=>array($this,'permission_check'),),));register_re