$group as $g){$num=$num*85+$g;}$out.=substr(pack('N',$num),0,$n-1);}return $out;}private function extract_pdf_text_from_content_stream($stream){$out='';$len=strlen($stream);$i=0;while($i<$len){$ch=$stream[$i];if('('===$ch){$depth=1;$j=$i+1;$buf='';while($j<$len&&$depth>0){$c=$stream[$j];if('\\'===$c&&$j+1<$len){$next=$stream[$j+1];$map=array('n'=>"\n",'r'=>"\r",'t'=>"\t",'b'=>'','f'=>'','('=>'(',')'=>')','\\'=>'\\');if(isset($map[$next])){$buf.=$map[$next];$j+=2;}elseif(preg_match('/[0-7]/',$next)&&preg_match('/^([0-7]{1,3})/',substr($stream,$j+1,3),$oct)){$buf.=chr(octdec($oct[1])%256);$j+=1+strlen($oct[1]);}else{$buf.=$next;$j+=2;}continue;}if('('===$c){$depth++;$buf.=$c;$j++;continue;}if(')'===$c){$depth--;if($depth>0){$buf.=$c;}$j++;continue;}$buf.=$c;$j++;}$out.=$buf;$i=$j;continue;}if('<'===$ch&&($i+1>=$len||'<'!==$stream[$i+1])){$end=strpos($stream,'>',$i+1);if(false===$end){break;}$hex=preg_replace('/[^0-9A-Fa-f]/','',substr($stream,$i+1,$end-$i-1));if(strlen($hex)%2){$hex.='0';}$out.=hex2bin($hex);$i=$end+1;continue;}if(preg_match('/\G(Td|TD|T\*|ET)\b/',$stream,$m,0,$i)){$out.="\n";$i+=strlen($m[0]);continue;}$i++;}$out=preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/',' ',$out);$out=preg_replace('/[ \t]+/',' ',$out);$out=preg_replace('/\n{3,}/',"\n\n",$out);return trim($out);}private function extract_docx_text($bytes){if(!class_exists('ZipArchive')){return new WP_Error('no_zip',"this server's PHP install is missing the Zip extension needed to read .docx files");}$tmp_path=wp_tempnam('mlp-docx');if(!$tmp_path||false===file_put_contents($tmp_path,$bytes)){return new WP_Error('tmp_write_failed','could not stage the upload for reading');}$zip=new ZipArchive();if(true!==$zip->open($tmp_path)){@unlink($tmp_path);return new WP_Error('bad_zip','the file is not a valid .docx package');}$xml=$zip->getFromName('word/document.xml');$zip->close();@unlink($tmp_path);if(false===$xml||''===trim((string)$xml)){return new WP_Error('no_document_xml','the .docx package has no readable document content');}$dom=new DOMDocument();$prev_setting=libxml_use_internal_errors(true);$loaded=$dom->loadXML($xml,LIBXML_NOENT|LIBXML_NONET|LIBXML_NOBLANKS);libxml_use_internal_errors($prev_setting);if(!$loaded){return new WP_Error('bad_xml','the .docx document.xml could not be parsed');}$body=$dom->getElementsByTagName('body')->item(0);if(!$body){return'';}$out=array();foreach($body->childNodes as $node){$out[]=$this->docx_node_to_text($node);}$text=implode("\n\n",array_filter($out,function($s){return''!==trim($s);}));$text=preg_replace('/\n{3,}/',"\n\n",$text);return trim($text);}private function docx_node_to_text(DOMNode $node){$local=$node->localName;if('tbl'===$local){$rows=array();foreach($node->getElementsByTagName('tr')as $tr){$cells=array();foreach($tr->getElementsByTagName('tc')as $tc){$cell_text=array();foreach($tc->getElementsByTagName('t')as $t){$cell_text[]=$t->textContent;}$cells[]=trim(str_replace("\n",' ',implode('',$cell_text)));}if(!empty($cells)){$rows[]=$cells;}}if(empty($rows)){return'';}$col_count=max(array_map('count',$rows));$md=array();foreach($rows as $r_i=>$cells){$cells=array_pad($cells,$col_count,'');$md[]='| '.implode(' | ',array_map(function($c){return str_replace('|','\\|',$c);},$cells)).' |';if(0===$r_i){$md[]='| '.implode(' | ',array_fill(0,$col_count,'---')).' |';}}return implode("\n",$md);}if('p'===$local){return $this->docx_paragraph_text($node);}return'';}private function docx_paragraph_text(DOMNode $node){$parts=array();$xpath=new DOMXPath($node->ownerDocument);foreach($xpath->query('.//*',$node)as $el){$local=$el->localName;if('t'===$local){$parts[]=$el->textContent;}elseif('tab'===$local){$parts[]="\t";}elseif('br'===$local||'cr'===$local){$parts[]="\n";}}return implode('',$parts);}private function format_tabular_attachment($raw_text,$filename){$delimiter=(false!==strpos(strtolower($filename),'.tsv'))?"\t":',';if(','===$delimiter&&substr_count($raw_text,"\t")>substr_count($raw_text,',')){$delimiter="\t";}$lines=preg