);if(!($post instanceof WP_Post)||!has_shortcode($post->post_content,'mlp_ai_chat')){return;}$title=get_the_title($post);if(''===$title){$title=get_bloginfo('name');}$description=get_the_excerpt($post);if(''===$description){$description=wp_trim_words(wp_strip_all_tags($post->post_content),30);}if(''===trim($description)){$description=get_bloginfo('description');}?>
