						</label>
<script>
(function () {
  function removeThinkingEllipsis(root) {
    var selector = '.chat-code-status-text';
    var labels = [];
    if (root.matches && root.matches(selector)) labels.push(root);
    Array.prototype.push.apply(labels, root.querySelectorAll(selector));
    Array.prototype.forEach.call(labels, function (label) {
      var text = label.textContent || '';
      var cleaned = text.replace(/(?:\.{3}|…)\s*$/, '');
      if (cleaned !== text) label.textContent = cleaned;
    });
  }
  function watchThinkingLabels() {
    removeThinkingEllipsis(document);
    if (!window.MutationObserver) return;
    var observer = new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        if (mutation.type === 'characterData' && mutation.target.parentNode) {
          removeThinkingEllipsis(mutation.target.parentNode);
        } else if (mutation.target && mutation.target.querySelectorAll) {
          removeThinkingEllipsis(mutation.target);
        }
      });
    });
    observer.observe(document.documentElement, { childList: true, subtree: true, characterData: true });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', watchThinkingLabels);
  } else {
    watchThinkingLabels();
  }
  window.setInterval(function () {
    removeThinkingEllipsis(document);
  }, 50);
})();
</script>
