<script>
(function () {
  var nativeFetch = window.fetch;
  if (!nativeFetch || window.__pteroAgentModeFetchWrapped) return;
  window.__pteroAgentModeFetchWrapped = true;
  function activeAgentProjectId() {
    try {
      var activeId = window.localStorage.getItem("mlp_ai_chat_active_conversation");
      var conversations = JSON.parse(window.localStorage.getItem("mlp_ai_chat_conversations_v2") || "[]");
      if (!Array.isArray(conversations)) return "";
      for (var i = 0; i < conversations.length; i++) {
        if (conversations[i] && conversations[i].id === activeId && conversations[i].project_id) {
          return String(conversations[i].project_id);
        }
      }
    } catch (e) {}
    return "";
  }
  window.fetch = function (input, init) {
    try {
      var url = typeof input === "string" ? input : (input && input.url) || "";
      var modeSelect = document.getElementById("chat-mode-select");
      if (modeSelect && modeSelect.value === "agent" && init && typeof init.body === "string" &&
          (url.indexOf("/chat-stream") !== -1 || url.indexOf("/chat") !== -1)) {
        var payload = JSON.parse(init.body);
        if (payload && typeof payload === "object") {
          payload.mode = "agent";
          var projectId = activeAgentProjectId();
          if (projectId) payload.project_id = projectId;
          init = Object.assign({}, init, { body: JSON.stringify(payload) });
        }
      }
    } catch (e) {}
    return nativeFetch.apply(this, arguments);
  };
}());
</script>
