				<script>
				(function () {
					function identity() {
						try { return JSON.parse(localStorage.getItem('mlp_ai_chat_identity') || 'null') || {}; }
						catch (e) { return {}; }
					}
					var githubAuthorizeEndpoint = <?php echo wp_json_encode(rest_url('mlp/v1/github/authorize')); ?>;
function referralText(key) {
return window.pteroAiReferralT ? window.pteroAiReferralT(key) : key;
}
function referralLocale() {
try { return localStorage.getItem('mlp_ai_chat_lang') || 'en'; } catch (e) { return 'en'; }
}
function escapeReferralText(value) {
return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}
					function showGithubLoginPrompt(content, me) {
						content.removeAttribute('data-loaded');
content.innerHTML = '<div style="padding:18px;border:1px solid #d9dce3;border-radius:10px;background:#f8fafc;"><strong data-referral-i18n="connectTitle" style="display:block;margin-bottom:6px;">' + escapeReferralText(referralText('connectTitle')) + '</strong><p data-referral-i18n="account" style="margin:0 0 14px;opacity:.7;font-size:13px;line-height:1.5;">' + escapeReferralText(referralText('account')) + '</p><button class="chat-referrals-github-login" data-referral-i18n="continue" type="button" style="border:0;border-radius:8px;background:#24292f;color:#fff;font-weight:700;padding:10px 13px;cursor:pointer;">' + escapeReferralText(referralText('continue')) + '</button></div>';
						var button = content.querySelector('.chat-referrals-github-login');
						if (!button) return;
						button.addEventListener('click', function () {
							button.disabled = true;
button.setAttribute('data-referral-i18n', 'waiting');
button.textContent = referralText('waiting');
							var url = githubAuthorizeEndpoint + '?purpose=api&guest=' + encodeURIComponent(me.token || '');
							var popup = window.open(url, 'ptero_referral_github', 'width=640,height=720');
							var finished = false;
							function done() {
								if (finished) return;
								finished = true;
								window.removeEventListener('message', onMessage);
								if (popup && !popup.closed) popup.close();
							}
							function onMessage(event) {
								var data = event && event.data;
								if (!data || (data.source !== 'ptero-referral-github' && data.source !== 'mlp-github')) return;
								done();
								if (data.success || data.mlpGithubVerified) {
									showReferralView();
								} else {
									button.disabled = false;
button.setAttribute('data-referral-i18n', 'continue');
button.textContent = referralText('continue');
								}
							}
							window.addEventListener('message', onMessage);
							var poll = setInterval(function () {
								if (popup && popup.closed) {
									clearInterval(poll);
									done();
									button.disabled = false;
button.setAttribute('data-referral-i18n', 'continue');
button.textContent = referralText('continue');
								}
							}, 700);
							if (!popup) {
								clearInterval(poll);
								done();
								button.disabled = false;
button.setAttribute('data-referral-i18n', 'popup');
button.textContent = referralText('popup');
							}
						});
					}
					function showReferralView() {
						var chat = document.getElementById('chat-chat-view');
						var referral = document.getElementById('chat-referrals-view');
						if (!referral) return;
						if (chat) chat.style.display = 'none';
						['chat-media-view', 'chat-prompt-view', 'chat-sponsors-view', 'chat-api-view', 'chat-admin-view', 'chat-project-view', 'chat-referrals-view'].forEach(function (id) {
							var view = document.getElementById(id);
							if (view) view.setAttribute('data-hidden', id === 'chat-referrals-view' ? '0' : '1');
						});
						var menu = document.getElementById('chat-profile-menu');
						var trigger = document.getElementById('chat-profile-trigger');
						if (menu) menu.hidden = true;
						if (trigger) trigger.setAttribute('aria-expanded', 'false');
						var content = document.getElementById('chat-referrals-content');
						if (!content || content.dataset.loaded) return;
						content.dataset.loaded = '1';
						var item = document.getElementById('chat-profile-menu-referrals');
						var me = identity();
						fetch(item ? item.dataset.referralEndpoint : '', {
							credentials: 'same-origin',
							headers: {
								'X-WP-Nonce': item ? item.dataset.referralNonce : '',
								'X-MLP-Guest-Token': me.token || '',
								'X-MLP-Guest-Username': me.username || ''
							},
							cache: 'no-store'
						}).then(function (res) {
							return res.json().then(function (data) {
								if (!res.ok) {
									var error = new Error(referralText('loadError'));
									error.code = data.code || '';
									throw error;
								}
								return data;
							});
						}).then(function (data) {
							content.innerHTML = '<div style="display:flex;gap:8px;margin-bottom:20px;"><input id="chat-referrals-link" type="text" readonly style="min-width:0;flex:1;padding:11px;border:1px solid #d9dce3;border-radius:8px;font:12px monospace;" value="' + escapeReferralText(data.link || '') + '"><button id="chat-referrals-copy" data-referral-i18n="copy" type="button" style="border:0;border-radius:8px;background:#10a37f;color:#fff;font-weight:700;padding:9px 13px;cursor:pointer;">' + escapeReferralText(referralText('copy')) + '</button></div>' +
								'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;"><div style="border:1px solid #e5e7eb;border-radius:10px;padding:12px;"><strong style="display:block;font-size:19px;">' + Number(data.referrals || 0).toLocaleString(referralLocale()) + '</strong><span data-referral-i18n="completed" style="font-size:11px;opacity:.65;">' + escapeReferralText(referralText('completed')) + '</span></div><div style="border:1px solid #e5e7eb;border-radius:10px;padding:12px;"><strong style="display:block;font-size:19px;">' + Number(data.earned_tokens || 0).toLocaleString(referralLocale()) + '</strong><span data-referral-i18n="tracked" style="font-size:11px;opacity:.65;">' + escapeReferralText(referralText('tracked')) + '</span></div><div style="border:1px solid #e5e7eb;border-radius:10px;padding:12px;"><strong style="display:block;font-size:19px;">+' + Number(data.bonus_tokens || 0).toLocaleString(referralLocale()) + '</strong><span data-referral-i18n="separate" style="font-size:11px;opacity:.65;">' + escapeReferralText(referralText('separate')) + '</span></div></div>' +
								'<p data-referral-i18n="platformNote" style="margin:18px 0 0;opacity:.7;font-size:12px;line-height:1.5;">' + escapeReferralText(referralText('platformNote')) + '</p>';
							var copy = document.getElementById('chat-referrals-copy');
							if (copy) copy.addEventListener('click', function () {
								var input = document.getElementById('chat-referrals-link');
								if (input) { input.select(); try { navigator.clipboard.writeText(input.value); } catch (e) { document.execCommand('copy'); } }
								copy.setAttribute('data-referral-i18n', 'copied');
								copy.textContent = referralText('copied');
								setTimeout(function () {
									copy.setAttribute('data-referral-i18n', 'copy');
									copy.textContent = referralText('copy');
								}, 1400);
							});
							if (window.pteroAiRefreshTranslations) window.pteroAiRefreshTranslations();
						}).catch(function (error) {
							if (error && error.code === 'github_login_required') {
								showGithubLoginPrompt(content, me);
								return;
							}
content.innerHTML = '<p data-referral-i18n="loadError" style="padding:12px;border:1px solid #fecdca;border-radius:8px;background:#fff5f4;color:#b42318;font-size:13px;">' + escapeReferralText(referralText('loadError')) + '</p>';
						});
					}
					function closeReferralView() {
						var referral = document.getElementById('chat-referrals-view');
						var chat = document.getElementById('chat-chat-view');
						if (referral) referral.setAttribute('data-hidden', '1');
						if (chat) chat.style.display = '';
					}
					function attachReferralView() {
						var item = document.getElementById('chat-profile-menu-referrals');
						var close = document.getElementById('chat-referrals-menu-btn');
						if (item && !item.dataset.referralViewBound) {
							item.dataset.referralViewBound = '1';
							item.onclick = null;
							item.addEventListener('click', function (event) {
								event.preventDefault();
								event.stopImmediatePropagation();
								showReferralView();
							});
						}
						if (close && !close.dataset.referralViewBound) {
							close.dataset.referralViewBound = '1';
							close.addEventListener('click', closeReferralView);
						}
					}
					attachReferralView();
					if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', attachReferralView);
				}());
				</script>
