 			.chat-sources-list { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 8px; }
			.chat-sources-list[hidden] { display: none !important; }
			.chat-source-card { display: flex; align-items: center; gap: 7px; min-width: 150px; max-width: 260px; padding: 7px 9px; color: #303940; background: rgba(127,127,127,.07); border: 1px solid rgba(127,127,127,.18); border-radius: 8px; text-decoration: none !important; transition: border-color .15s ease, background .15s ease; }
			.chat-source-card:hover { background: rgba(16,163,127,.08); border-color: rgba(16,163,127,.45); }
			.chat-source-card img { width: 16px; height: 16px; flex: 0 0 16px; border-radius: 3px; }
			.chat-source-card-copy { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
			.chat-source-card-title-row { display: flex; align-items: center; gap: 5px; min-width: 0; }
			.chat-source-card-title { overflow: hidden; color: inherit; font-size: 12px; font-weight: 600; line-height: 1.25; text-overflow: ellipsis; white-space: nowrap; }
			.chat-source-card-site { overflow: hidden; color: #7b858d; font-size: 10.5px; line-height: 1.2; text-overflow: ellipsis; white-space: nowrap; }
			.chat-source-card-arrow { margin-left: auto; color: #83909a; font-size: 13px; }
			.chat-table-wrap { overflow-x: auto; margin: 4px 0; max-width: 100%; }
			table.chat-md-table { border-collapse: collapse; width: 100%; font-size: 0.92em; }
			table.chat-md-table th, table.chat-md-table td { border: 1px solid rgba(127,127,127,0.35); padding: 6px 10px; text-align: left; vertical-align: top; }
			table.chat-md-table th { font-weight: 600; background: rgba(127,127,127,0.08); }
			table.chat-md-table tr:nth-child(even) td { background: rgba(127,127,127,0.04); }
			.chat-stepper { margin: 4px 0; }
			.chat-stepper-header { display: none !important; }
			.chat-stepper-badge { font-size: 0.78em; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; opacity: 0.65; }
			.chat-stepper-title { font-weight: 600; margin-bottom: 4px; }
			.chat-stepper .chat-stepper-panel,
			.chat-stepper .chat-stepper-panel[hidden] { display: block !important; line-height: 1.45; margin: 0 0 8px; }
			.chat-stepper-body { line-height: 1.45; }
			.chat-stepper-dots { display: none !important; }
			.chat-stepper-dot { width: 7px; height: 7px; border-radius: 50%; background: rgba(127,127,127,0.35); cursor: pointer; padding: 0; border: none; }
			.chat-stepper-dot.active { background: currentColor; opacity: 0.85; }
			.chat-stepper-nav { display: none !important; }
			.chat-stepper-btn { flex: 0 0 auto; padding: 6px 14px; border-radius: 999px; border: 1px solid #dcdce0; background: #fff; color: #383941; cursor: pointer; font-size: 0.9em; font-weight: 600; -webkit-appearance: none; appearance: none; }
			.chat-stepper-btn:hover:not(:disabled) { background: #eafaf4; border-color: #10a37f; color: #10a37f; }
			.chat-stepper-btn:disabled { opacity: 0.35; cursor: default; }
			.chat-stepper-btn.chat-stepper-primary { margin-left: auto; background: #10a37f; border-color: #10a37f; color: #fff; }
			.chat-stepper-btn.chat-stepper-primary:hover:not(:disabled) { background: #0e8f6f; border-color: #0e8f6f; color: #fff; }

			.chat-thinking { margin-bottom: 6px; border: 1px solid #e0e0e0; border-radius: 8px; overflow: hidden; font-size: 12px; background: #fafafa; }
			.chat-thinking summary { cursor: pointer; padding: 6px 10px; color: #888; user-select: none; list-style: none; display: flex; align-items: center; gap: 6px; }
			.chat-thinking summary::-webkit-details-marker { display: none; }
			.chat-thinking summary::before { content: '+'; font-size: 15px; font-weight: 400; width: 14px; color: #888; transition: transform 0.15s; display: inline-flex; align-items: center; justify-content: center; }
			.chat-thinking[open] summary::before { content: '−'; transform: none; }
			.chat-thinking-body { display: none; padding: 8px 12px; border-top: 1px solid #e8e8e8; color: #777; line-height: 1.5; white-space: pre-wrap; word-wrap: break-word; max-height: 260px; overflow-y: auto; }
.chat-activity-list { position: relative; display: flex; flex-direction: column; gap: 0; padding: 8px 10px; border-top: 1px solid #e8e8e8; background: #f7f7f8; overflow: hidden; }
.chat-activity-list::before { content: ''; position: absolute; z-index: 0; left: 26px; top: 17px; bottom: 17px; width: 1px; background: #d8d8dc; }
.chat-activity-meta { padding: 5px 10px 8px 38px; color: #8b8b92; font-size: 11px; line-height: 1.35; border-top: 1px solid #e8e8e8; }

.chat-input-wrap {
position: relative;
border-top: 0;
background: #f8f8f9;
padding: 14px 20px 18px;
}
.chat-ai-chat-fullpage,
.chat-ai-chat-app,
.chat-main,
.chat-messages,
.chat-chat-header {
background: #f8f8f9;
}
.chat-chat-header {
border-bottom-color: #ececef;
}
.chat-input-area {
position: relative;
width: min(100%, 860px);
min-height: 92px;
margin: 0 auto;
display: block;
box-sizing: border-box;
padding: 7px;
background: #fff;
border: 1px solid #e5e5e9;
border-radius: 18px;
box-shadow: 0 6px 20px rgba(27, 27, 43, 0.06), 0 1px 2px rgba(27, 27, 43, 0.03);
transition: border-color 0.18s ease, box-shadow 0.18s ease;
}
.chat-input-area:focus-within {
border-color: #a8a8ba;
box-shadow: 0 10px 28px rgba(27, 27, 43, 0.11), 0 0 0 3px rgba(16, 163, 127, 0.09);
}
.chat-input {
display: block;
width: 100%;
min-height: 76px;
box-sizing: border-box;
border: 0;
border-radius: 13px;
padding: 9px 12px 40px;
background: transparent;
color: #252532;
line-height: 1.45;
transition: background 0.18s ease, box-shadow 0.18s ease;
}
.chat-input::placeholder { color: #9999a8; }
.chat-input:focus {
border-color: transparent;
background: transparent;
box-shadow: none;
}
.chat-attach-wrap {
position: absolute;
left: 10px;
bottom: 9px;
z-index: 2;
}
.chat-attach-btn {
width: 36px;
height: 36px;
border: 0;
border-radius: 50%;
background: #fafafd;
color: #686878;
padding: 0;
position: relative;
box-shadow: 0 1px 3px rgba(27, 27, 43, 0.08);
}
.chat-attach-btn:hover,
.chat-attach-btn[aria-expanded="true"] {
background: #f0f0f5;
border-color: transparent;
color: #252532;
}
.chat-attach-btn:active { transform: scale(0.95); }
.chat-send-btn {
position: absolute;
right: 9px;
bottom: 9px;
width: 38px;
height: 36px;
border-radius: 13px;
background: #252532;
transition: background 0.18s ease, transform 0.12s ease;
}
.chat-send-btn:hover:not(:disabled) { background: #10a37f; transform: translateY(-1px); }
.chat-send-btn:active:not(:disabled) { transform: translateY(0) scale(0.96); }
.chat-send-btn:disabled { background: #d8d8df; }
.chat-model-picker {
position: absolute;
left: 48px;
bottom: 10px;
z-index: 3;
}
.chat-model-picker-panel {
top: auto;
right: auto;
bottom: calc(100% + 8px);
left: 0;
}
.chat-model-picker-trigger {
background: transparent;
border-color: transparent;
border-radius: 9px;
padding: 2px 6px 2px 3px;
gap: 5px;
max-width: 180px;
}
.chat-model-picker-trigger:hover,
.chat-model-picker-trigger[aria-expanded="true"] {
background: #f0f0f5;
border-color: transparent;
box-shadow: none;
}
.chat-model-picker-trigger-icon,
.chat-model-picker-trigger-icon img {
width: 22px;
height: 22px;
}
.chat-model-picker-trigger-label {
font-size: 12px;
font-weight: 500;
}
.chat-model-picker-chevron {
width: 11px;
height: 11px;
}
.chat-mic-btn {
position: absolute;
right: 55px;
bottom: 9px;
z-index: 2;
display: flex !important;
width: 36px;
height: 36px;
border-radius: 50%;
background: transparent;
color: #686878;
}
.chat-mic-btn:hover:not(:disabled),
.chat-mic-btn.is-listening {
background: #f0f0f5;
color: #252532;
}
.chat-mic-btn.is-listening {
background: #eafaf4;
color: #10a37f;
}
.chat-voice-mode-btn {
position: absolute;
right: 104px;
bottom: 9px;
z-index: 2;
display: flex !important;
width: 36px;
height: 36px;
border-radius: 50%;
background: transparent;
color: #686878;
}
.chat-voice-mode-btn:hover:not(:disabled),
.chat-voice-mode-btn.is-active,
.chat-voice-mode-btn.is-speaking {
background: #f0f0f5;
color: #252532;
}
#chat-voice-mode-btn {
display: flex !important;
visibility: visible !important;
opacity: 1 !important;
position: absolute !important;
right: 104px !important;
bottom: 9px !important;
width: 36px !important;
height: 36px !important;
align-items: center !important;
justify-content: center !important;
}
#chat-voice-mode-btn .chat-voice-icon {
display: block !important;
visibility: visible !important;
opacity: 1 !important;
}
.chat-voice-btn {
width: 36px;
height: 36px;
border: 0;
border-radius: 11px;
background: transparent;
color: #686878;
padding: 0;
display: flex;
align-items: center;
justify-content: center;
flex: 0 0 auto;
cursor: pointer;
transition: background 0.18s ease, color 0.18s ease, transform 0.12s ease;
}
.chat-voice-btn:hover:not(:disabled) { background: #f0f0f5; color: #252532; }
.chat-voice-btn:active:not(:disabled) { transform: scale(0.94); }
.chat-voice-btn:disabled { opacity: 0.42; cursor: not-allowed; }
.chat-voice-btn.is-active,
.chat-voice-btn.is-listening,
.chat-voice-btn.is-speaking {
background: #eafaf4;
color: #10a37f;
}
.chat-voice-btn.is-listening {
animation: mlpVoicePulse 1.25s ease-in-out infinite;
}
@keyframes mlpVoicePulse {
0%, 100% { box-shadow: 0 0 0 0 rgba(16,163,127,0.18); }
50% { box-shadow: 0 0 0 5px rgba(16,163,127,0.08); }
}
.chat-feedback-btn.speak.is-speaking { color: #10a37f; background: rgba(16,163,127,0.12); }
.chat-attach-preview {
width: min(100%, 860px);
margin: 0 auto;
padding-left: 0;
padding-right: 0;
}
.chat-attach-preview:not(:empty) { padding-bottom: 8px; }
.chat-attach-chip {
background: #fff;
border-color: #dedee6;
border-radius: 11px;
}
.chat-attach-chip-icon { background: #252532; }
.chat-attach-menu {
bottom: calc(100% + 10px);
border-color: #dedee6;
border-radius: 13px;
box-shadow: 0 12px 28px rgba(27, 27, 43, 0.14);
}
.chat-attach-btn .chat-icon-plus {
position: absolute;
left: 50%;
top: 50%;
transform: translate(-50%, -50%);
}
.chat-task-mode-toggle {
 display: flex !important;
 align-items: center;
 justify-content: center;
 gap: 2px;
 width: fit-content;
 margin: 7px auto 0;
 color: #777783;
 cursor: pointer;
 }
.chat-task-mode-toggle select {
 appearance: none;
 -webkit-appearance: none;
 border: 0;
 outline: 0;
 background: transparent;
 color: inherit;
 font: inherit;
 font-size: 12px;
 line-height: 20px;
 padding: 0;
 cursor: pointer;
 }
.chat-task-mode-toggle select:hover,
.chat-task-mode-toggle select:focus {
 background: transparent;
 color: #777783;
 }
.chat-task-mode-chevron {
 flex: 0 0 auto;
 pointer-events: none;
 }
.chat-task-mode-toggle:has(option:checked[value="agent"]) {
 color: #087f63;
 font-weight: 600;
 }
.chat-task-mode-toggle:has(option:checked[value="agent"]) select {
 color: #087f63;
 font-weight: 600;
 }

@media (max-width: 600px) {
.chat-input-wrap { padding: 10px 10px calc(12px + env(safe-area-inset-bottom)); }
.chat-input-area { border-radius: 16px; }
.chat-input { min-height: 76px; padding: 10px 12px 40px; }
.chat-mic-btn { right: 55px; }
.chat-voice-mode-btn { right: 104px; }
}
.chat-activity-row { position: relative; z-index: 1; display: block; padding: 3px 7px; border-radius: 6px; color: #666; cursor: pointer; transition: background .12s, color .12s, opacity .18s; animation: mlpChipIn .24s ease both; }
.chat-activity-row:hover, .chat-activity-row[open] { background: transparent; color: #222; }
.chat-activity-row.is-active { background: transparent; color: #333; }
.chat-activity-icon { width: 18px; height: 18px; margin-top: 1px; display: inline-flex; align-items: center; justify-content: center; color: #626268; background: #f7f7f8; border-radius: 50%; flex: 0 0 auto; position: relative; z-index: 2; }
			.chat-activity-icon svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.chat-activity-row[data-status="complete"] .chat-activity-icon { color: #6d6d73; opacity: .84; }
.chat-activity-row.is-active .chat-activity-icon { color: #4f4f55; }
.chat-activity-row.is-active .chat-activity-icon svg { animation: chatActivityActive 1.25s ease-in-out infinite; }
			.chat-activity-summary { display: flex; align-items: center; gap: 8px; }
			.chat-activity-summary { list-style: none; font-size: 12px; line-height: 1.4; }
			.chat-activity-summary::-webkit-details-marker { display: none; }
.chat-activity-detail { display: none; margin: 3px 0 0 15px; color: #888; font-size: 11px; line-height: 1.45; }
.chat-activity-state { display: none; margin-left: auto; color: #999; font-size: 11px; white-space: nowrap; }
.chat-activity-row.is-active .chat-activity-state { color: #68686e; }
.chat-activity-row[data-status="complete"] .chat-activity-state::before { content: '✓ '; color: #626268; }
			.chat-code-status-dots { display: inline-flex; align-items: center; gap: 3px; margin-left: 2px; height: 14px; }
			.chat-code-status-dots i { display: block; width: 3px; height: 3px; border-radius: 50%; background: currentColor; opacity: .35; animation: chatActivityDot 1.05s ease-in-out infinite; }
			.chat-code-status-dots i:nth-child(2) { animation-delay: .16s; }
			.chat-code-status-dots i:nth-child(3) { animation-delay: .32s; }
			@keyframes chatActivityDot {
				0%, 60%, 100% { opacity: .28; transform: translateY(0) scale(.82); }
				30% { opacity: 1; transform: translateY(-2px) scale(1.1); }
			}
			@keyframes chatActivityActive {
				0%, 100% { transform: translateY(0) scale(.92); opacity: .64; }
				50% { transform: translateY(-1px) scale(1.05); opacity: 1; }
			}

.chat-code-status {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 10px;
  margin: 2px 0 8px 2px;
  border-radius: 8px;
  background: transparent;
  width: fit-content;
  max-width: 100%;
  box-sizing: border-box;
  min-width: 220px;
  flex-wrap: nowrap;
  transition: opacity .18s ease, transform .18s ease;
  }
  .chat-code-status.chat-code-status-fading {
  opacity: 0;
  transform: translateY(-3px);
  }
			.chat-code-status-icon {
				flex-shrink: 0;
				color: #888;
				animation: chatCodeStatusSpin 1s linear infinite;
			}
.chat-loading-logo {
width: 18px;
height: 18px;
display: grid;
grid-template-columns: repeat(2, 7px);
grid-template-rows: repeat(2, 7px);
gap: 3px;
align-content: center;
justify-content: center;
color: #929299;
animation: none;
}
.chat-loading-logo-dot {
display: block;
width: 7px;
height: 7px;
border-radius: 1px;
background: currentColor;
opacity: .62;
animation: chatLoadingLogoPulse .72s cubic-bezier(.4,0,.2,1) infinite;
will-change: transform, opacity;
}
.chat-loading-logo-dot:nth-child(2) { animation-delay: .1s; }
.chat-loading-logo-dot:nth-child(3) {
grid-column: 1 / span 2;
justify-self: center;
animation-delay: .2s;
}
.chat-code-status-text {
min-width: 0;
overflow: hidden;
text-overflow: ellipsis;
white-space: nowrap;
}
.chat-code-status-subtext,
.chat-code-status-dots {
display: none;
}
@keyframes chatLoadingLogoPulse {
0%, 100% {
color: #85858c;
opacity: .48;
transform: translateY(0) scale(.78) rotate(0deg);
}
28% {
color: #626268;
opacity: 1;
transform: translateY(-1px) scale(1.08) rotate(6deg);
}
52% {
color: #626268;
opacity: .82;
transform: translateY(0) scale(1) rotate(0deg);
}
}
			@keyframes chatCodeStatusSpin {
				from { transform: rotate(0deg); }
				to { transform: rotate(360deg); }
			}
			.chat-code-status-text {
				font-size: 12.5px;
				font-weight: 500;
				background: linear-gradient(90deg, #b5b5b5 0%, #3a3a3a 45%, #b5b5b5 90%);
				background-size: 200% 100%;
				-webkit-background-clip: text;
				background-clip: text;
				color: transparent;
				animation: chatCodeStatusShimmer 1.6s linear infinite;
			}
.chat-code-status-subtext {
display: none;
}
.chat-code-status.is-complete .chat-code-status-icon {
animation: none;
 color: #626268;
}
.chat-code-status.is-complete .chat-code-status-text {
background: none;
color: #777;
animation: none;
}
 .chat-code-status.is-complete .chat-code-status-dots { display: none; }
@media (prefers-reduced-motion: reduce) {
  .chat-live-code-file,
  .chat-code-status-icon,
  .chat-code-status-text,
  .chat-code-status-dots,
  .chat-activity-icon svg {
    animation: none;
  }
  .chat-code-status-dots i { animation: none; opacity: .8; transform: none; }
  .chat-loading-logo-dot {
    animation: none;
    color: #929299;
    opacity: .8;
    transform: none;
  }
}
			@keyframes chatCodeStatusShimmer {
				0% { background-position: 200% 0; }
				100% { background-position: -200% 0; }
			}

			.chat-sidebar-divider { height: 1px; background: #3a3b3d; margin: 10px 0; flex-shrink: 0; }
			.chat-sidebar-disclaimer {
				margin: 14px 0 0 0 !important; padding-top: 12px; flex-shrink: 0;
				border-top: 1px solid #3a3b3d; font-size: 11px; line-height: 1.4; color: #8e8ea0;
			}
			.chat-sidebar-disclaimer a { color: #10a37f; text-decoration: none; }
			.chat-sidebar-disclaimer a:hover { text-decoration: underline; }
			.chat-sidebar-source-link {
				display: flex; align-items: center; gap: 8px; margin-top: 10px; flex-shrink: 0;
				font-size: 12px; color: #8e8ea0; text-decoration: none; transition: color 0.15s ease;
			}
