.chat-send-btn {
width: 38px;
height: 38px;
border-radius: 50%;
background: #10a37f;
transition: background 0.18s ease, transform 0.12s ease;
}
.chat-send-btn:hover:not(:disabled) {
background: #0d8a6a;
transform: translateY(-1px);
}
.chat-send-btn:active:not(:disabled) {
transform: translateY(0) scale(0.96);
}
.chat-send-btn:disabled {
background: #9ed8c7;
}
.chat-icon-send {
width: 15px;
height: 15px;
margin: 0;
border: 0;
background: currentColor;
clip-path: polygon(50% 0, 100% 42%, 70% 42%, 70% 100%, 30% 100%, 30% 42%, 0 42%);
}
.chat-send-btn:disabled .chat-icon-send {
border: 0;
background: rgba(255, 255, 255, 0.6);
}
.chat-send-btn.is-stop {
background: #d63638;
}
.chat-send-btn.is-stop:hover {
background: #b9282a;
}
.chat-send-btn.is-stop:disabled {
background: #eeb3b3;
}
