			<script>
			(function () {
				var app = document.getElementById("chat-ai-chat-app");
				if (!app) return;
				var newChatButtons = document.querySelectorAll("#chat-new-chat-btn, #chat-project-new-chat-btn");
				Array.prototype.forEach.call(newChatButtons, function (button) {
					button.addEventListener("click", function () {
						app.setAttribute("data-new-chat-empty", "1");
					});
				});
				document.addEventListener("click", function (event) {
					if (event.target.closest(".chat-conv-item")) {
						app.removeAttribute("data-new-chat-empty");
					}
				});
			})();
			</script>

