es";left.appendChild(metrics);row.appendChild(left);var status=document.createElement("div");status.className="chat-admin-model-status chat-status-"+m.state;status.innerHTML='<span class="chat-status-dot"></span><span></span>';status.querySelector("span:last-child").textContent=STATE_LABELS[m.state]||m.state;row.appendChild(status);var votes=document.createElement("div");votes.className="chat-admin-model-votes";votes.innerHTML='<span class="chat-admin-model-vote likes">'+likeSvg()+"<span></span></span>"+'<span class="chat-admin-model-vote dislikes">'+dislikeSvg()+"<span></span></span>";votes.querySelector(".likes span").textContent=m.likes||0;votes.querySelector(".dislikes span").textContent=m.dislikes||0;row.appendChild(votes);var toggleBtn=document.createElement("button");toggleBtn.type="button";toggleBtn.className="chat-admin-model-toggle"+(m.disabled?" is-disabled":"");toggleBtn.textContent=m.disabled?"Enable":"Disable";toggleBtn.addEventListener("click",function(){toggleModel(m.id)});row.appendChild(toggleBtn);var hiddenByError=!m.disabled&&["error","offline","blocked","rate_limited","cooldown"].indexOf(m.state)!==-1;if(hiddenByError){var reactivateBtn=document.createElement("button");reactivateBtn.type="button";reactivateBtn.className="chat-admin-model-reactivate";reactivateBtn.textContent="Reactivate";reactivateBtn.title="Clear the error/cooldown and make this model visible to users again";reactivateBtn.addEventListener("click",function(){reactivateModel(m.id)});row.appendChild(reactivateBtn)}elAdminModels.appendChild(row)})}function renderAdminUsage(data){if(!elAdminUsage)return;var usage=data.usage||{};var period=usage.period_days||0;var values=[{label:"Requests",value:usage.requests||0},{label:"Tokens",value:usage.tokens||0},{label:"Avg latency",value:(usage.avg_latency_ms||0)+" ms"},{label:"Model failures",value:usage.failures||0,warning:(usage.failures||0)>0}];elAdminUsage.innerHTML="";var head=document.createElement("div");head.className="chat-admin-usage-head";head.innerHTML='<span class="chat-admin-usage-title">Usage</span><span class="chat-admin-usage-period"></span>';head.querySelector(".chat-admin-usage-period").textContent=period?"Last "+period+" days":"";elAdminUsage.appendChild(head);var note=document.createElement("p");note.className="chat-admin-usage-note";note.textContent="Contentless operational metrics aggregated by model and hour.";elAdminUsage.appendChild(note);var grid=document.createElement("div");grid.className="chat-admin-usage-grid";values.forEach(function(item){var card=document.createElement("div");card.className="chat-admin-usage-item";card.innerHTML='<div class="chat-admin-usage-item-label"></div><div class="chat-admin-usage-item-value"></div>';card.querySelector(".chat-admin-usage-item-label").textContent=item.label;card.querySelector(".chat-admin-usage-item-value").textContent=item.value;if(item.warning)card.querySelector(".chat-admin-usage-item-value").classList.add("is-warning");grid.appendChild(card)});elAdminUsage.appendChild(grid)}function renderAdminData(data){renderAdminStats(data);renderAdminUsage(data);renderAdminModels(data);elAdminToggleGlobalBtn.textContent=data.disabled?"Re-enable AI Chat":"Disable AI Chat";elAdminToggleGlobalBtn.classList.toggle("is-disabled",!data.disabled);applyDisabledState(!!data.disabled);disabledModelIds=(data.models||[]).filter(function(m){return m.disabled}).map(function(m){return m.id});applyModelDisabledOptions()}function refreshAdminData(){apiFetch("/admin/status").then(renderAdminData).catch(function(){})}function toggleGlobal(){elAdminToggleGlobalBtn.disabled=true;apiFetch("/admin/toggle-global",{method:"POST"}).then(renderAdminData).finally(function(){elAdminToggleGlobalBtn.disabled=false})}function toggleModel(modelId){apiFetch("/admin/toggle-model",{method:"POST",body:JSON.stringify({model_id:modelId})}).then(renderAdminData)}function reactivateModel(modelId){apiFetch("/admin/reactivate-model",{method:"POST",body:JSON.stringify({model_id:modelId})}).then(renderAdminData)}if(elAdminRoomBtn){elAdminRoomBtn.addEventListener("click",function(){showAdminView();closeSidebar()});elAdminRefreshBtn.addEventListener("click",refreshAdminData);elAdminToggleGlobalBtn.addEventListener("click",toggleGlobal)}var MEDIA_STORAGE_KEY="mlpAiChatMediaLibrary";var MAX_MEDIA_FILE_BYTES=3*1024*1024;function loadMediaLibrary(){try{var raw=localStorage.getItem(MEDIA_STORAGE_KEY);var parsed=raw?JSON.parse(raw):[];return Array.isArray(parsed)?parsed:[]}catch(e){return[]}}function saveMediaLibrary(items){try{localStorage.setItem(MEDIA_STORAGE_KEY,JSON.stringify(items));return true}catch(e){alert("Could not save this media — your browser storage is full. Try removing some older items first.");return false}}function addMediaFiles(fileList){var files=Array.prototype.slice.call(fileList||[]);if(!files.length)return;var library=loadMediaLibrary();var remaining=files.length;var anyAdded=false;files.forEach(function(file){var isMediaFile=file.type.indexOf("image/")===0||file.type.indexOf("video/")===0;if(!isMediaFile){alert(file.name+" is not an image or video and was skipped.");remaining--;return}if(file.size>MAX_MEDIA_FILE_BYTES){alert(file.name+" is larger than 3MB and was skipped.");remaining--;return}readFileAsDataURL(file).then(function(dataUrl){library.push({id:"media_"+Date.now()+"_"+Math.random().toString(36).slice(2,8),name:file.name,type:file.type||"application/octet-stream",isImage:file.type.indexOf("image/")===0,isVideo:file.type.indexOf("video/")===0,dataUrl:dataUrl,addedAt:Date.now()});anyAdded=true}).catch(function(){}).finally(function(){remaining--;if(remaining<=0&&anyAdded){saveMediaLibrary(library);renderMediaGallery()}})})}function deleteMediaItem(id){var library=loadMediaLibrary().filter(function(item){return item.id!==id});saveMediaLibrary(library);renderMediaGallery()}function insertMediaIntoChat(item){if(item.isImage&&!currentImagesOk){alert(t("attach_images_unsupported"));return}if(pendingAttachments.length>=MAX_ATTACHMENTS){alert("You can attach up to "+MAX_ATTACHMENTS+" files per message.");return}pendingAttachments.push({id:"att_"+Date.now()+"_"+Math.random().toString(36).slice(2,8),name:item.name,type:item.type,size:null,dataUrl:item.dataUrl,isImage:!!item.isImage});renderAttachPreview();showChatView();closeSidebar();elInput.focus()}function renderMediaGallery(){if(!elMediaGallery)return;var library=loadMediaLibrary().slice().sort(function(a,b){return(b.addedAt||0)-(a.addedAt||0)});elMediaGallery.innerHTML="";library.forEach(function(item){var card=document.createElement("div");card.className="chat-media-item";if(item.isImage){var img=document.createElement("img");img.src=item.dataUrl;img.alt=item.name;card.appendChild(img)}else if(item.isVideo){var video=document.createElement("video");video.src=item.dataUrl;video.muted=true;card.appendChild(video)}else{var iconWrap=document.createElement("div");iconWrap.className="chat-media-item-file-icon";iconWrap.innerHTML=fileIconSvg();card.appendChild(iconWrap)}var nameLabel=document.createElement("div");nameLabel.className="chat-media-item-name";nameLabel.textContent=item.name;card.appendChild(nameLabel);var overlay=document.createElement("div");overlay.className="chat-media-item-overlay";var insertBtn=document.createElement("button");insertBtn.type="button";insertBtn.className="chat-media-item-insert-btn";insertBtn.textContent="Insert into chat";insertBtn.addEventListener("click",function(){insertMediaIntoChat(item)});overlay.appendChild(insertBtn);var deleteBtn=document.createElement("button");deleteBtn.type="button";deleteBtn.className="chat-media-item-delete-btn";deleteBtn.textContent="Delete";deleteBtn.addEventListener("click",function(){if(confirm('Remove "'+item.name+'" from your media?'))deleteMediaItem(item.id)});overlay.appendChild(deleteBtn);card.appendChild(overlay);elMediaGallery.appendChild(card)})}if(elMediaRoomBtn){elMediaRoomBtn.addEventListener("click",function(){showMediaView();closeSidebar()})}if(elMediaAddBtn&&elMediaFileInput){elMediaAddBtn.addEventListener("click",function(){elMediaFileInput.click()});elMediaFileInput.addEventListener("change",function(){addMediaFiles(this.files);this.value=""})}var DEFAULT_PROMPTS={coding:[{id:"code_review",name:"Code Review",prompt:"Please review this code for:\n- Performance issues\n- Security vulnerabilities\n- Best practices\n- Potential bugs\n\nProvide specific recommendations."},{id:"code_explain",name:"Explain Code",prompt:"Please explain this code in detail:\n- What does it do?\n- How does it work?\n- What are key patterns?\n- Explain complex parts"},{id:"code_debug",name:"Debug Help",prompt:"Help me debug this code:\n1. Identify the issue\n2. Explain what's going wrong\n3. Provide a fix\n4. Explain why it works"},{id:"code_optimize",name:"Optimize Code",prompt:"Please optimize this code for:\n- Performance\n- Readability\n- Maintainability\n- Best practices"}],translation:[{id:"trans_en",name:"Translate to English",prompt:"Please translate the following text to English, preserving meaning and tone:"},{id:"trans_es",name:"Translate to Spanish",prompt:"Por favor, traduce este texto al español, preservando significado y tono:"},{id:"trans_fr",name:"Translate to French",prompt:"Veuillez traduire ce texte en français, en préservant le sens et le ton:"},{id:"localize",name:"Localize Content",prompt:"Help me localize this content for [LANGUAGE]:\n- Adapt cultural references\n- Adjust idioms\n- Consider local conventions\n- Maintain brand voice"}],seo:[{id:"meta",name:"Meta Description",prompt:"Create SEO meta description (max 160 chars):\nKeywords: [ADD]\nTopic: [ADD]"},{id:"title",name:"Title Tag",prompt:"Create SEO title tag (max 60 chars):\nKeyword: [ADD]\nBrand: [ADD]\nTopic: [ADD]"},{id:"kw_research",name:"Keyword Research",prompt:"Help with keywords for: [TOPIC]\nProvide:\n- 10-15 relevant keywords\n- Search volume\n- Competition level\n- Long-tail variations\n- User intent"},{id:"seo_opt",name:"SEO Optimization",prompt:"Optimize for SEO:\n- Target keywords\n- Heading structure\n- Internal/external links\n- Readability\n- Schema markup"}],writing:[{id:"blog",name:"Blog Post",prompt:"Help write blog about [TOPIC]:\n- Create engaging title\n- Write introduction\n- Organize 5-7 sections\n- Include conclusion\n- Add CTA\nTone: [PROFESSIONAL/CASUAL]"},{id:"grammar",name:"Grammar & Style",prompt:"Edit for:\n- Grammar/punctuation\n- Clarity/conciseness\n- Tone consistency\n- Active voice\n- Redundancy\nMaintain meaning."},{id:"email",name:"Email Template",prompt:"Create email for: [PURPOSE]\nInclude:\n- Subject line\n- Greeting\n- Body paragraphs\n- CTA\n- Closing\nTone: [FORMAL/CASUAL]"},{id:"social",name:"Social Media",prompt:"Write posts for [PLATFORM]:\n- Engaging copy\n- Hashtags\n- CTA\n- Emojis\nSpecs: Twitter <280 chars, LinkedIn professional, Instagram visual"}],debugging:[{id:"error_an",name:"Error Analysis",prompt:"I got error: [ERROR]\nContext:\n- Language: [STACK]\n- Trying to: [DESC]\n- Code: [PASTE]\nExplain: error, cause, solution"},{id:"tests",name:"Test Cases",prompt:"Generate test cases for: [FUNCTION]\nInclude:\n- Happy path\n- Edge cases\n- Error handling\n- Performance"},{id:"trace",name:"Trace Issue",prompt:"Help trace issue:\nSymptoms: [DESC]\nWhen: [CONDITIONS]\nEnvironment: [SETUP]\nProvide: causes, steps, solution"}],custom:[]};function escapeHtml(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}function loadPrompts(){var s=localStorage.getItem("mlpPrompts");return s?JSON.parse(s):JSON.parse(JSON.stringify(DEFAULT_PROMPTS))}function savePrompts(p){localStorage.setItem("mlpPrompts",JSON.stringify(p))}function addPrompt(cat,name,prompt){var lib=loadPrompts(),id="c_"+Date.now();if(!lib[cat])lib[cat]=[];lib[cat].push({id:id,name:name,prompt:prompt,custom:1});savePrompts(lib)}function deletePrompt(cat,id){var lib=loadPrompts();if(lib[cat])lib[cat]=lib[cat].filter(function(t){return t.id!==id});savePrompts(lib)}function showPrompts(){document.getElementById("chat-chat-view").style.display="none";document.getElementById("chat-prompt-view").setAttribute("data-hidden","0");document.getElementById("chat-media-view").setAttribute("data-hidden","1");if(elSponsorsView)elSponsorsView.setAttribute("data-hidden","1");if(elApiView)elApiView.setAttribute("data-hidden","1");setTimeout(renderPrompts,50)}function showSponsorsView(){if(currentFileData&&currentFileData.isProjectFile)closeCodeSidebar();document.getElementById("chat-chat-view").style.display="none";if(elAdminView)elAdminView.setAttribute("data-hidden","1");if(elMediaView)elMediaView.setAttribute("data-hidden","1");if(elProjectView)elProjectView.setAttribute("data-hidden","1");document.getElementById("chat-prompt-view").setAttribute("data-hidden","1");if(elApiView)elApiView.setAttribute("data-hidden","1");if(elAdminRoomBtn)elAdminRoomBtn.classList.remove("active");if(elMediaRoomBtn)elMediaRoomBtn.classList.remove("active");document.getElementById("chat-prompt-btn").classList.remove("active");currentProjectViewId=null;if(elSponsorsView)elSponsorsView.setAttribute("data-hidden","0")}function renderPrompts(activeCat){var el=document.getElementById("chat-prompt-library");if(!el)return;var prevActive=document.querySelector(".prompt-tab.active");if(!activeCat)activeCat=prevActive?prevActive.dataset.cat:null;el.innerHTML="";var lib=loadPrompts(),cats=Object.keys(lib);if(!activeCat||cats.indexOf(activeCat)===-1)activeCat=cats[0];var html='<div class="prompt-tabs">';cats.forEach(function(c,i){html+='<button class="prompt-tab'+(c===activeCat?" active":"")+'" data-cat="'+c+'">'+c.charAt(0).toUpperCase()+c.slice(1)+"</button>"});html+="</div>";cats.forEach(function(c,i){html+='<div class="prompt-content'+(c===activeCat?" active":"")+'" data-cat="'+c+'">';var tpls=lib[c]||[];tpls.forEach(function(t){html+='<div class="prompt-card"><div class="prompt-card-name">'+escapeHtml(t.name)+'</div><div class="prompt-card-preview">'+escapeHtml(t.prompt.substring(0,50))+'...</div><div class="prompt-card-actions"><button class="prompt-btn prompt-use-btn" data-prompt="'+escapeHtml(t.prompt)+'">Use</button>';if(t.custom)html+='<button class="prompt-btn prompt-del-btn" data-cat="'+c+'" data-id="'+t.id+'">Delete</button>';html+="</div></div>"});html+='<div class="prompt-add-section"><input type="text" class="prompt-add-input prompt-add-name" placeholder="Name"><textarea class="prompt-add-input prompt-add-prompt" placeholder="Prompt" style="min-height:60px;"></textarea><button type="button" class="prompt-save-btn" data-cat="'+c+'">Save</button><div class="prompt-save-msg" style="font-size:11px;margin-top:6px;display:none;"></div></div></div>'});el.innerHTML=html;document.querySelectorAll(".prompt-tab").forEach(function(btn){btn.addEventListener("click",function(){document.querySelectorAll(".prompt-tab").forEach(function(b){b.classList.remove("active")});document.querySelectorAll(".prompt-content").forEach(function(c){c.classList.remove("active")});btn.classList.add("active");document.querySelector('.prompt-content[data-cat="'+btn.dataset.cat+'"]').classList.add("active")})});document.querySelectorAll(".prompt-use-btn").forEach(function(btn){btn.addEventListener("click",function(){elInput.value=btn.dataset.prompt;elInput.focus();showChatView();closeSidebar()})});document.querySelectorAll(".prompt-del-btn").forEach(function(btn){btn.addEventListener("click",function(){if(window.confirm("Delete?")){deletePrompt(btn.dataset.cat,btn.dataset.id);renderPrompts(btn.dataset.cat)}})});document.querySelectorAll(".prompt-save-btn").forEach(function(btn){btn.addEventListener("click",function(){try{var section=btn.parentElement;var msg=section.querySelector(".prompt-save-msg");var cat=btn.dataset.cat;var nameEl=section.querySelector(".prompt-add-name");var promptEl=section.querySelector(".prompt-add-prompt");var name=nameEl?nameEl.value.trim():"";var prompt=promptEl?promptEl.value.trim():"";if(name&&prompt){addPrompt(cat,name,prompt);renderPrompts(cat);var newMsg=document.querySelector('.prompt-content[data-cat="'+cat+'"] .prompt-save-msg');if(newMsg){newMsg.textContent="Saved!";newMsg.style.color="#10a37f";newMsg.style.display="block"}}else if(msg){msg.textContent="Please fill in both the name and prompt fields.";msg.style.color="#d63638";msg.style.display="block"}}catch(err){console.error("Prompt save failed:",err);var fallback=btn.parentElement.querySelector(".prompt-save-msg");if(fallback){var isQuota=err&&(err.name==="QuotaExceededError"||err.code===22||/quota/i.test(err.message||""));fallback.textContent=isQuota?"Your browser storage is full (usually from chat history/media). Delete some old conversations or items in the Media Room, then try saving again.":"Error: "+(err&&err.message?err.message:err);fallback.style.color="#d63638";fallback.style.display="block"}}})})}var elPromptBtn=document.getElementById("chat-prompt-btn");var elPromptMenuBtn=document.getElementById("chat-prompt-menu-btn");if(elPromptBtn)elPromptBtn.addEventListener("click",function(){showPrompts();closeSidebar()});if(elPromptMenuBtn)elPromptMenuBtn.addEventListener("click",function(){showChatView()});var elSponsorsBtn=document.getElementById("chat-sponsors-btn");var elSponsorsMenuBtn=document.getElementById("chat-sponsors-menu-btn");var elSponsorUsBtn=document.getElementById("chat-sponsor-us-btn");var elSponsorUsModal=document.getElementById("chat-sponsor-us-modal");var elSponsorUsClose=document.getElementById("chat-sponsor-us-close");if(elSponsorsBtn)elSponsorsBtn.addEventListener("click",function(){showSponsorsView();closeSidebar()});if(elSponsorsMenuBtn)elSponsorsMenuBtn.addEventListener("click",function(){showChatView()});if(elSponsorUsBtn)elSponsorUsBtn.addEventListener("click",function(){if(elSponsorUsModal)elSponsorUsModal.removeAttribute("data-hidden")});if(elSponsorUsClose)elSponsorUsClose.addEventListener("click",function(){if(elSponsorUsModal)elSponsorUsModal.setAttribute("data-hidden","1")});if(elSponsorUsModal)elSponsorUsModal.addEventListener("click",function(e){if(e.target===elSponsorUsModal)elSponsorUsModal.setAttribute("data-hidden","1")});var chatStarted=false;function initChatApp(){if(chatStarted)return;chatStarted=true;checkAiStatus();refreshGithubStatus();setInterval(checkAiStatus,3e4);updateModelUI();attachCopyListeners();pruneStaleConversations().then(function(){loadConversations();restoreActiveConversation()},function(){loadConversations();restoreActiveConversation()});renderProjectsList();pullCloudProjects();renderArchivedList();renderLabelFilterBar();maybeStartOnboardingTour();checkNewsUnread();setInterval(checkNewsUnread,3e4)}function startAppFlow(){<?php if($user_id):?>;initChatApp();<?php else:?>;if(identity&&identity.username){initChatApp()}else{showUsernameModal()}<?php endif;?>}requireLegalConsent(startAppFlow)})();</script>
<script>
(function () {
  var fileTypes = {
    js:["JS","#f7df1e","#111827"],mjs:["JS","#f7df1e","#111827"],cjs:["JS","#f7df1e","#111827"],
    ts:["TS","#3178c6","#fff"],jsx:["JSX","#61dafb","#102a43"],tsx:["TSX","#3178c6","#fff"],
    py:["PY","#3776ab","#fff"],php:["PHP","#777bb4","#fff"],html:["HTML","#e44d26","#fff"],
    htm:["HTML","#e44d26","#fff"],css:["CSS","#1572b6","#fff"],scss:["SCSS","#c6538c","#fff"],
    less:["LESS","#1d365d","#fff"],json:["JSON","#a88b00","#fff"],xml:["XML","#f16529","#fff"],
    vue:["VUE","#42b883","#fff"],svelte:["SV","#ff3e00","#fff"],java:["JAVA","#b07219","#fff"],
    c:["C","#5c6bc0","#fff"],h:["C","#5c6bc0","#fff"],cc:["C++","#00599c","#fff"],
    cpp:["C++","#00599c","#fff"],hpp:["C++","#00599c","#fff"],cs:["C#","#68217a","#fff"],
    go:["GO","#00add8","#fff"],rs:["RS","#ce422b","#fff"],rb:["RB","#cc342d","#fff"],
    swift:["SWIFT","#f05138","#fff"],kt:["KT","#7f52ff","#fff"],kts:["KT","#7f52ff","#fff"],
    sql:["SQL","#336791","#fff"],sh:["SH","#4eaa25","#fff"],bash:["SH","#4eaa25","#fff"],
    zsh:["SH","#4eaa25","#fff"],ps1:["PS","#2671be","#fff"],yml:["YML","#cb171e","#fff"],
    yaml:["YML","#cb171e","#fff"],md:["MD","#4183c4","#fff"],dart:["DART","#0175c2","#fff"],
    lua:["LUA","#000080","#fff"],r:["R","#276dc3","#fff"],graphql:["GQL","#e10098","#fff"],
    pdf:["PDF","#e53935","#fff"],doc:["DOC","#2b579a","#fff"],docx:["DOC","#2b579a","#fff"],
    odt:["ODT","#2b579a","#fff"],rtf:["RTF","#2b579a","#fff"],txt:["TXT","#64748b","#fff"],
    csv:["CSV","#188038","#fff"],tsv:["TSV","#188038","#fff"],xls:["XLS","#217346","#fff"],
    xlsx:["XLS","#217346","#fff"],ods:["ODS","#217346","#fff"],ppt:["PPT","#d24726","#fff"],
    pptx:["PPT","#d24726","#fff"],odp:["ODP","#d24726","#fff"],zip:["ZIP","#b7791f","#fff"],
    rar:["RAR","#b7791f","#fff"],"7z":["7Z","#b7791f","#fff"],tar:["TAR","#b7791f","#fff"],
    gz:["GZ","#b7791f","#fff"]
  };
  var specialTypes = {
    dockerfile:["DOCK","#2496ed","#fff"],makefile:["MAKE","#64748b","#fff"],
    gemfile:["RB","#cc342d","#fff"],license:["TXT","#64748b","#fff"]
  };
  function typeFor(filename) {
    var base = String(filename || "").trim().toLowerCase().split("/").pop().split("\\").pop();
    if (specialTypes[base]) return specialTypes[base];
    var dot = base.lastIndexOf(".");
    return fileTypes[dot > -1 ? base.slice(dot + 1) : ""] || ["FILE","#64748b","#fff"];
  }
  function iconFor(filename) {
    var type = typeFor(filename), label = type[0].slice(0, 4);
    var size = label.length > 3 ? 7.4 : label.length > 2 ? 9.2 : 11;
    return '<svg class="chat-filetype-icon" viewBox="0 0 32 32" width="32" height="32" shape-rendering="geometricPrecision" text-rendering="geometricPrecision" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">' +
      '<path d="M6 1.5h13.5L27 9v20.5a1.5 1.5 0 0 1-1.5 1.5h-19A1.5 1.5 0 0 1 5 29.5V3A1.5 1.5 0 0 1 6 1.5Z" fill="' + type[1] + '"/>' +
      '<path d="M19.5 1.5V9H27" fill="#fff" fill-opacity=".28"/>' +
      '<rect x="4.5" y="16.5" width="23" height="11.5" rx="2" fill="#101828" fill-opacity=".38"/>' +
      '<text x="16" y="25.1" text-anchor="middle" textLength="19" lengthAdjust="spacingAndGlyphs" font-family="Arial,Helvetica,sans-serif" font-size="' + size + '" font-weight="900" fill="#fff">' + label + "</text></svg>";
  }
  function refreshFileIcons() {
    document.querySelectorAll(
      ".chat-msg-file:not(.chat-msg-file-github),.chat-attach-chip,.chat-file-card," +
      ".chat-files-sidebar-item,.chat-project-file-item,.chat-media-item"
    ).forEach(function (root) {
      var name = root.querySelector(
        ".chat-msg-file-name,.chat-attach-chip-name,.chat-file-card-name," +
        ".chat-files-sidebar-item-name,.chat-project-file-name,.chat-media-item-name"
      );
      var host = root.querySelector(
        ".chat-media-item-file-icon,.chat-attach-chip-icon,.chat-file-card-icon," +
        ".chat-files-sidebar-item-icon,.chat-project-file-icon"
      );
      var messageIcon = null;
      if (!host && root.matches(".chat-msg-file")) {
        host = root;
        messageIcon = root.querySelector("svg");
      }
      if (!host || !name) return;
      var marker = name.textContent;
      if (host.getAttribute("data-file-icon-name") === marker) return;
      if (messageIcon) messageIcon.outerHTML = iconFor(marker);
      else host.innerHTML = iconFor(marker);
      host.setAttribute("data-file-icon-name", marker);
    });
  }
  function startFileIcons() {
    if (!document.getElementById("chat-filetype-icon-style")) {
      var style = document.createElement("style");
      style.id = "chat-filetype-icon-style";
      style.textContent =
        ".chat-attach-chip-icon,.chat-file-card-icon,.chat-files-sidebar-item-icon," +
        ".chat-project-file-icon,.chat-media-item-file-icon{" +
        "background:transparent!important;border:0!important;box-shadow:none!important;" +
        "padding:0!important;}" +
        ".chat-filetype-icon{display:block;width:32px;height:32px;max-width:none;max-height:none;}";
      (document.head || document.documentElement).appendChild(style);
    }
    refreshFileIcons();
    if (document.body && window.MutationObserver) {
      new MutationObserver(refreshFileIcons).observe(document.body, {childList:true,subtree:true});
    }
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", startFileIcons);
  else startFileIcons();
})();
</script>
<script>
(function () {
  var reviewLabels = {
    en: "Send a Review",
    ar: "إرسال مراجعة",
    zh: "发送评价",
    es: "Enviar una reseña",
    fr: "Envoyer un avis",
    de: "Bewertung abgeben",
    pt: "Enviar uma avaliação",
    ru: "Оставить отзыв",
    hi: "समीक्षा भेजें",
    ja: "レビューを送る",
    ko: "리뷰 보내기",
    tr: "İnceleme Gönder",
    it: "Invia una recensione",
