/*
 * New-chat titles are cosmetic. Queue that request until the first answer's
 * stream has finished, so title generation cannot delay or compete with it.
 * The queued request is still sent through the normal AI endpoint afterward,
 * which preserves better AI-generated titles.
 */
if (!function_exists('ptero_ai_chat_defer_title_requests')) {
    function ptero_ai_chat_defer_title_requests() {
        if (is_admin()) {
            return;
        }
        ?>
        <script>
        (function () {
            if (!window.fetch || window.__pteroDeferredTitleRequests) {
                return;
            }
            window.__pteroDeferredTitleRequests = true;
            var nativeFetch = window.fetch.bind(window);
            var queuedTitles = [];
            var titlesReleased = false;

            function releaseTitles() {
                if (titlesReleased) {
                    return;
                }
                titlesReleased = true;
                var requests = queuedTitles.splice(0);
                requests.forEach(function (request) {
                    nativeFetch(request.input, request.init).then(request.resolve, request.reject);
                });
            }

            function requestDetails(input, init) {
                var url = typeof input === "string" ? input : (input && input.url ? input.url : "");
                var body = init && init.body;
                return { url: String(url || ""), body: body };
            }

            function isTitleRequest(input, init) {
                var details = requestDetails(input, init);
                if (!/\/mlp\/v1\/chat(?:\?|$)/i.test(details.url) || !details.body) {
                    return false;
                }
                try {
                    var payload = typeof details.body === "string" ? JSON.parse(details.body) : details.body;
                    return !!(payload && typeof payload.message === "string" &&
                        /Create a concise title for this new chat\./i.test(payload.message));
                } catch (ignore) {
                    return false;
                }
            }

            function isChatStreamRequest(input) {
                var url = typeof input === "string" ? input : (input && input.url ? input.url : "");
                return /\/mlp\/v1\/chat-stream(?:\?|$)/i.test(String(url || ""));
            }

            function syncSidebarTitle() {
                var currentTitle = document.getElementById("chat-current-title");
                if (!currentTitle) {
                    return;
                }
                var title = currentTitle.textContent || "";
                document.querySelectorAll(".chat-conv-item.active .chat-conv-title").forEach(function (titleElement) {
                    if (titleElement.textContent !== title) {
                        titleElement.textContent = title;
                    }
                });
            }

            if (window.MutationObserver && document.documentElement) {
                new MutationObserver(syncSidebarTitle).observe(document.documentElement, {
                    subtree: true,
                    childList: true,
                    characterData: true
                });
                setTimeout(syncSidebarTitle, 100);
            }

            window.fetch = function (input, init) {
                if (isTitleRequest(input, init) && !titlesReleased) {
                    return new Promise(function (resolve, reject) {
                        queuedTitles.push({ input: input, init: init, resolve: resolve, reject: reject });
                    });
                }

                var responsePromise = nativeFetch(input, init);
                if (!isChatStreamRequest(input)) {
                    return responsePromise;
                }

                return responsePromise.then(function (response) {
                    if (!response || !response.body || typeof response.body.getReader !== "function" || !response.ok) {
                        setTimeout(releaseTitles, 250);
                        return response;
                    }

                    var originalGetReader = response.body.getReader.bind(response.body);
                    response.body.getReader = function () {
                        var reader = originalGetReader();
                        var originalRead = reader.read.bind(reader);
                        var released = false;
                        function releaseOnce() {
                            if (released) {
                                return;
                            }
                            released = true;
                            setTimeout(releaseTitles, 250);
                        }
                        reader.read = function () {
                            return originalRead().then(function (result) {
                                if (result && result.done) {
                                    releaseOnce();
                                }
                                return result;
                            }, function (error) {
                                releaseOnce();
                                throw error;
                            });
                        };
                        return reader;
                    };
                    return response;
                }, function (error) {
                    setTimeout(releaseTitles, 250);
                    throw error;
                });
            };
        }());
        </script>
        <?php
    }
    add_action('wp_head', 'ptero_ai_chat_defer_title_requests', 1);
}

if (!function_exists('ptero_ai_get_api_usage_admin_stats')) {
    /**
     * Return the API-key usage counters shown in administrator dashboards.
     *
     * API usage is stored in hourly UTC buckets and retained by the API usage
     * dashboard. Keep the counters aligned with that retention window rather
     * than presenting a misleading lifetime total.
     */
    function ptero_ai_get_api_usage_admin_stats() {
        global $wpdb;

        $retention_days = defined('MLP_AI_CHAT_USAGE_RETENTION_DAYS')
            ? max(1, (int) MLP_AI_CHAT_USAGE_RETENTION_DAYS)
            : 90;
        $stats = array(
            'api_calls_total' => 0,
            'api_calls_today' => 0,
            'api_failures_total' => 0,
            'api_tokens_total' => 0,
            'api_usage_period_days' => $retention_days,
        );
        $table = $wpdb->prefix . 'ptero_api_usage';

        if (!$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($table)))) {
            return $stats;
        }

        $since = gmdate('Y-m-d H:i:s', time() - ($retention_days * DAY_IN_SECONDS));
        $totals = $wpdb->get_row($wpdb->prepare(
            "SELECT COALESCE(SUM(requests), 0) AS api_calls_total,
                    COALESCE(SUM(failures), 0) AS api_failures_total,
                    COALESCE(SUM(tokens), 0) AS api_tokens_total
             FROM {$table}
             WHERE bucket_start >= %s",
            $since
        ), ARRAY_A);

        if (is_array($totals)) {
            $stats['api_calls_total'] = (int) $totals['api_calls_total'];
            $stats['api_failures_total'] = (int) $totals['api_failures_total'];
            $stats['api_tokens_total'] = (int) $totals['api_tokens_total'];
        }

        $stats['api_calls_today'] = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(requests), 0)
             FROM {$table}
             WHERE bucket_start >= %s",
            gmdate('Y-m-d 00:00:00')
        ));

        return $stats;
    }

    /**
     * Include API-key counters in the in-chat administrator dashboard response.
     */
    function ptero_ai_add_api_usage_to_admin_status($response, $server, $request) {
        if (!$request instanceof WP_REST_Request ||
            '/mlp/v1/admin/status' !== $request->get_route() ||
            is_wp_error($response) ||
            !is_object($response) ||
            !method_exists($response, 'get_data')) {
            return $response;
        }

        $data = $response->get_data();
        if (is_array($data)) {
            $response->set_data(array_merge($data, ptero_ai_get_api_usage_admin_stats()));
        }

        return $response;
    }

    add_filter('rest_post_dispatch', 'ptero_ai_add_api_usage_to_admin_status', 20, 3);

    /**
     * Add the same API counters to the Administration room inside the chat.
     *
     * The existing admin renderer owns the original cards, so this small
     * companion renderer appends the API-specific cards after each refresh
     * without replacing that UI.
     */
    function ptero_ai_render_chat_admin_api_stats() {
        if (is_admin()) {
            return;
        }
        ?>
        <script>
        (function () {
            if (!window.fetch || window.__pteroAdminApiStats) {
                return;
            }
            window.__pteroAdminApiStats = true;
            var nativeFetch = window.fetch.bind(window);

            function requestUrl(input) {
                return String(typeof input === 'string' ? input : (input && input.url) || '');
            }

            function render(data) {
                var stats = document.getElementById('chat-admin-stats');
                if (!stats || !data) {
                    return;
                }
                stats.querySelectorAll('.ptero-chat-admin-api-stat').forEach(function (card) {
                    card.remove();
                });

                var period = Number(data.api_usage_period_days || 90);
                var values = [
                    {label: 'API Calls (' + period + 'd)', value: data.api_calls_total || 0},
                    {label: 'API Calls Today', value: data.api_calls_today || 0},
                    {label: 'API Failures (' + period + 'd)', value: data.api_failures_total || 0},
                    {label: 'API Tokens (' + period + 'd)', value: data.api_tokens_total || 0}
                ];
                values.forEach(function (item) {
                    var card = document.createElement('div');
                    card.className = 'chat-admin-stat-card ptero-chat-admin-api-stat';
                    var label = document.createElement('div');
                    label.className = 'chat-admin-stat-label';
                    label.textContent = item.label;
                    var value = document.createElement('div');
                    value.className = 'chat-admin-stat-value';
                    value.textContent = Number(item.value || 0).toLocaleString();
                    card.appendChild(label);
                    card.appendChild(value);
                    stats.appendChild(card);
                });
            }

            window.fetch = function (input, init) {
                var response = nativeFetch(input, init);
                if (!/\/mlp\/v1\/admin\/status(?:\?|$)/i.test(requestUrl(input))) {
                    return response;
                }
                return response.then(function (res) {
                    if (res && res.ok && res.clone) {
                        res.clone().json().then(function (data) {
                            window.setTimeout(function () { render(data); }, 0);
                        }).catch(function () {});
                    }
                    return res;
                });
            };
        }());
        </script>
        <?php
    }
    add_action('wp_footer', 'ptero_ai_render_chat_admin_api_stats', 102);
}



/* Bundled API Usage Dashboard */
/**
 * Plugin Name: Ptero AI Chat - API Usage Dashboard
 * Description: Adds a per-user API usage dashboard, request history, chart, and explicit API limits to Ptero AI Chat.
 * Version: 1.0.0
 * Requires at least: 5.8
 * Requires PHP: 7.0
 * Text Domain: ptero-ai-chat
 */

if (!defined('ABSPATH')) {
    exit;
}

final class Ptero_AI_API_Usage_Dashboard {
    const VERSION = '1.0.0';
    const RETENTION_DAYS = 90;
    const REQUESTS_PER_MINUTE = 30;
    const TOKENS_PER_HOUR = 500000;
    const STARRED_TOKENS_PER_HOUR = 1000000;
    const MAX_OUTPUT_TOKENS = 128000;

    private static $table = '';
    private static $timers = array();

    public static function boot() {
        global $wpdb;

        self::$table = $wpdb->prefix . 'ptero_api_usage';
        self::ensure_table();

        add_action('rest_api_init', array(__CLASS__, 'register_routes'));
        add_filter('rest_pre_dispatch', array(__CLASS__, 'start_timer'), 10, 3);
        add_filter('rest_request_after_callbacks', array(__CLASS__, 'capture_request'), 10, 3);
        add_action('wp_footer', array(__CLASS__, 'render_assets'), 99);
        add_action('wp_footer', array(__CLASS__, 'render_api_tools'), 100);
    }

    private static function ensure_table() {
        global $wpdb;

        $charset = $wpdb->get_charset_collate();
        $table = self::$table;
        $sql = "CREATE TABLE {$table} (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            bucket_start DATETIME NOT NULL,
            api_key_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
            model_id VARCHAR(120) NOT NULL DEFAULT '',
            requests BIGINT UNSIGNED NOT NULL DEFAULT 0,
            tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            failures BIGINT UNSIGNED NOT NULL DEFAULT 0,
            latency_ms_total BIGINT UNSIGNED NOT NULL DEFAULT 0,
            latency_samples BIGINT UNSIGNED NOT NULL DEFAULT 0,
            PRIMARY KEY (id),
            UNIQUE KEY bucket_key_model (bucket_start, api_key_id, model_id),
            KEY bucket_start (bucket_start),
            KEY api_key_id (api_key_id)
        ) {$charset};";

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';
        dbDelta($sql);
    }

    public static function register_routes() {
        register_rest_route('mlp/v1', '/api-usage', array(
            'methods' => 'GET',
            'callback' => array(__CLASS__, 'get_usage'),
            'permission_callback' => '__return_true',
        ));
        register_rest_route('mlp/v1', '/api-models', array(
            'methods' => 'GET',
            'callback' => array(__CLASS__, 'get_models'),
            'permission_callback' => '__return_true',
        ));
    }

    private static function bearer_key() {
        $header = isset($_SERVER['HTTP_AUTHORIZATION'])
            ? sanitize_text_field(wp_unslash($_SERVER['HTTP_AUTHORIZATION']))
            : '';

        if (!preg_match('/^Bearer\s+([A-Za-z0-9_-]{20,120})$/i', $header, $matches)) {
            return false;
        }

        global $wpdb;
        $table = $wpdb->prefix . 'mlp_ai_api_keys';
        if (!$wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table))) {
            return false;
        }

        return $wpdb->get_row(
            $wpdb->prepare(
                "SELECT id, name, key_prefix, guest_token, github_login, last_used_at
                 FROM {$table} WHERE key_hash = %s AND revoked_at IS NULL LIMIT 1",
                hash('sha256', $matches[1])
            ),
            ARRAY_A
        );
    }

    private static function guest_token($request = null) {
        $raw = $request instanceof WP_REST_Request
            ? $request->get_header('x-mlp-guest-token')
            : '';

        if (!$raw && !empty($_COOKIE['mlp_ai_guest_token'])) {
            $raw = wp_unslash($_COOKIE['mlp_ai_guest_token']);
        }

        $token = substr(preg_replace('/[^a-zA-Z0-9]/', '', (string) $raw), 0, 64);
        if (!$token && get_current_user_id()) {
            $token = 'u' . get_current_user_id();
        }

        return $token;
    }

    private static function owned_key_ids($request) {
        global $wpdb;
        $table = $wpdb->prefix . 'mlp_ai_api_keys';
        $key = self::bearer_key();

        if ($key) {
            return array((int) $key['id']);
        }

        $guest = self::guest_token($request);
        if (!$guest || !$wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table))) {
            return array();
        }

        $ids = $wpdb->get_col($wpdb->prepare(
            "SELECT id FROM {$table} WHERE guest_token = %s AND revoked_at IS NULL",
            $guest
        ));

        return array_map('intval', $ids);
    }

    private static function request_key($request) {
        $key = self::bearer_key();
        if ($key) {
            return $key;
        }

        return false;
    }

    public static function get_usage(WP_REST_Request $request) {
        global $wpdb;

        $key_ids = self::owned_key_ids($request);
        $days = min(90, max(7, absint($request->get_param('days') ?: 30)));
        $from = gmdate('Y-m-d H:i:s', time() - ($days * DAY_IN_SECONDS));
        $summary = array(
            'requests' => 0,
            'tokens' => 0,
            'failures' => 0,
            'avg_latency_ms' => 0,
        );
        $rows = array();

        if ($key_ids) {
            $placeholders = implode(',', array_fill(0, count($key_ids), '%d'));
            $args = array_merge(array($from), $key_ids);
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT DATE(bucket_start) AS day,
                        SUM(requests) AS requests,
                        SUM(tokens) AS tokens,
                        SUM(failures) AS failures,
                        SUM(latency_ms_total) AS latency_ms_total,
                        SUM(latency_samples) AS latency_samples
                 FROM " . self::$table . "
                 WHERE bucket_start >= %s AND api_key_id IN ({$placeholders})
                 GROUP BY DATE(bucket_start)
                 ORDER BY day ASC",
                $args
            ), ARRAY_A);

            $totals = $wpdb->get_row($wpdb->prepare(
                "SELECT SUM(requests) AS requests,
                        SUM(tokens) AS tokens,
                        SUM(failures) AS failures,
                        SUM(latency_ms_total) AS latency_ms_total,
                        SUM(latency_samples) AS latency_samples
                 FROM " . self::$table . "
                 WHERE bucket_start >= %s AND api_key_id IN ({$placeholders})",
                $args
            ), ARRAY_A);

            if (is_array($totals)) {
                $summary['requests'] = (int) $totals['requests'];
                $summary['tokens'] = (int) $totals['tokens'];
                $summary['failures'] = (int) $totals['failures'];
                $samples = (int) $totals['latency_samples'];
                $summary['avg_latency_ms'] = $samples
                    ? (int) round(((int) $totals['latency_ms_total']) / $samples)
                    : 0;
            }
        }

        $by_day = array();
        foreach ($rows as $row) {
            $by_day[$row['day']] = array(
                'date' => $row['day'],
                'requests' => (int) $row['requests'],
                'tokens' => (int) $row['tokens'],
                'failures' => (int) $row['failures'],
            );
        }

        $series = array();
        for ($i = $days - 1; $i >= 0; $i--) {
            $day = gmdate('Y-m-d', time() - ($i * DAY_IN_SECONDS));
            $series[] = isset($by_day[$day])
                ? $by_day[$day]
                : array('date' => $day, 'requests' => 0, 'tokens' => 0, 'failures' => 0);
        }

        $keys = array();
        if ($key_ids) {
            $key_placeholders = implode(',', array_fill(0, count($key_ids), '%d'));
            $keys = $wpdb->get_results($wpdb->prepare(
                "SELECT id, name, key_prefix, created_at, last_used_at
                 FROM {$wpdb->prefix}mlp_ai_api_keys
                 WHERE id IN ({$key_placeholders})
                 ORDER BY id DESC",
                $key_ids
            ), ARRAY_A);
        }

        return rest_ensure_response(array(
            'period_days' => $days,
            'summary' => $summary,
            'series' => $series,
            'keys' => $keys,
            'limits' => array(
                'requests_per_minute' => self::REQUESTS_PER_MINUTE,
                'requests_per_day' => self::REQUESTS_PER_MINUTE * 60 * 24,
                'tokens_per_hour' => self::TOKENS_PER_HOUR,
                'starred_tokens_per_hour' => self::STARRED_TOKENS_PER_HOUR,
                'window_seconds' => HOUR_IN_SECONDS,
                'max_output_tokens' => self::MAX_OUTPUT_TOKENS,
                'retention_days' => self::RETENTION_DAYS,
            ),
            'has_api_keys' => !empty($key_ids),
        ));
    }

    public static function start_timer($result, $server, $request) {
        if (self::is_chat_request($request) && self::request_key($request)) {
            self::$timers[spl_object_hash($request)] = microtime(true);
        }

        return $result;
    }

    public static function capture_request($response, $handler, $request) {
        if (!self::is_chat_request($request)) {
            return $response;
        }

        $key = self::request_key($request);
        if (!$key) {
            return $response;
        }

        $timer_id = spl_object_hash($request);
        $latency = isset(self::$timers[$timer_id])
            ? max(0, (int) round((microtime(true) - self::$timers[$timer_id]) * 1000))
            : 0;
        unset(self::$timers[$timer_id]);

        $failed = is_wp_error($response);
        $data = $failed ? array() : (is_object($response) && method_exists($response, 'get_data')
            ? (array) $response->get_data()
            : array());
        $status = is_object($response) && method_exists($response, 'get_status')
            ? (int) $response->get_status()
            : 200;
        $failed = $failed || $status >= 400;
        $model = !empty($data['model_used']) ? sanitize_text_field($data['model_used']) : 'unknown';
        $tokens = !empty($data['usage_tokens'])
            ? absint($data['usage_tokens'])
            : (!empty($data['usage']['total_tokens']) ? absint($data['usage']['total_tokens']) : 0);

        if (!$tokens && !empty($data['reply'])) {
            $tokens = (int) ceil(strlen(wp_json_encode($request->get_json_params())) / 4);
            $tokens += (int) ceil(strlen((string) $data['reply']) / 4);
        }

        self::record($key['id'], $model, $tokens, $latency, $failed);
        return $response;
    }

    private static function is_chat_request($request) {
        if (!$request instanceof WP_REST_Request) {
            return false;
        }

        $route = $request->get_route();
        return (bool) preg_match('#^/mlp/v1/chat(?:-stream)?/?$#', $route);
    }

    private static function record($key_id, $model, $tokens, $latency, $failed) {
        global $wpdb;

        $bucket = gmdate('Y-m-d H:00:00');
        $requests = $failed ? 0 : 1;
        $failures = $failed ? 1 : 0;
        $wpdb->query($wpdb->prepare(
            "INSERT INTO " . self::$table . "
             (bucket_start, api_key_id, model_id, requests, tokens, failures, latency_ms_total, latency_samples)
             VALUES (%s, %d, %s, %d, %d, %d, %d, 1)
             ON DUPLICATE KEY UPDATE
               requests = requests + VALUES(requests),
               tokens = tokens + VALUES(tokens),
               failures = failures + VALUES(failures),
               latency_ms_total = latency_ms_total + VALUES(latency_ms_total),
               latency_samples = latency_samples + VALUES(latency_samples)",
            $bucket,
            (int) $key_id,
            substr($model, 0, 120),
            $requests,
            max(0, (int) $tokens),
            $failures,
            max(0, (int) $latency)
        ));

        $wpdb->query($wpdb->prepare(
            "DELETE FROM " . self::$table . " WHERE bucket_start < %s",
            gmdate('Y-m-d H:i:s', time() - (self::RETENTION_DAYS * DAY_IN_SECONDS))
        ));
    }

