            .ptero-usage-status { color:#6b7280; font-size:12px; margin:0; padding:16px 4px; text-align:center; }
            .ptero-usage-error { color:#b42318; background:#fff5f4; border:1px solid #fecdca; border-radius:8px; padding:10px; font-size:12px; }
            .ptero-usage-keys { color:#6b7280; font-size:11px; margin:0; }
            .ptero-usage-key { display:flex; justify-content:space-between; gap:12px; border-top:1px solid #f0f1f3; padding:9px 0 0; margin-top:9px; }
            .ptero-usage-key strong { color:#374151; font-size:11px; }
            @media (max-width: 620px) { .ptero-usage-cards { grid-template-columns:repeat(2,minmax(0,1fr)); } .ptero-usage-limits { grid-template-columns:1fr; } .ptero-usage-head { display:block; } .ptero-usage-refresh { margin-top:12px; } }
        </style>
        <script>
        (function () {
            var endpoint = <?php echo wp_json_encode($rest_url . '/api-usage?days=30'); ?>;
            var nonce = <?php echo wp_json_encode($nonce); ?>;
            var storageKey = 'mlp_ai_chat_identity';
            var loaded = false;

            function esc(value) {
                return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
                    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];
                });
            }
            function fmt(value) {
                var locale = 'en';
                try { locale = localStorage.getItem('mlp_ai_chat_lang') || 'en'; } catch (e) {}
                return Number(value || 0).toLocaleString(locale);
            }
            function identityToken() {
                try {
                    var data = JSON.parse(localStorage.getItem(storageKey) || 'null');
                    return data && data.token ? data.token : '';
                } catch (e) { return ''; }
            }
            function headers() {
                return {'X-WP-Nonce': nonce, 'X-MLP-Guest-Token': identityToken()};
            }
            function drawChart(series) {
                var width = 720, height = 205, pad = {top:14,right:12,bottom:30,left:38};
                var innerW = width - pad.left - pad.right, innerH = height - pad.top - pad.bottom;
                var max = Math.max.apply(null, series.map(function (d) { return Number(d.requests || 0); }).concat([1]));
                var points = series.map(function (d, i) {
                    var x = pad.left + (series.length <= 1 ? 0 : i * innerW / (series.length - 1));
                    var y = pad.top + innerH - (Number(d.requests || 0) / max * innerH);
                    return x.toFixed(1) + ',' + y.toFixed(1);
                }).join(' ');
                var grid = [0, .5, 1].map(function (ratio) {
                    var y = (pad.top + innerH - ratio * innerH).toFixed(1);
                    var label = Math.round(max * ratio);
                    return '<line x1="' + pad.left + '" x2="' + (width - pad.right) + '" y1="' + y + '" y2="' + y + '" stroke="#eef0f3"/><text x="4" y="' + (Number(y) + 4) + '" fill="#9ca3af" font-size="10">' + esc(label) + '</text>';
                }).join('');
                var labels = [0, Math.floor(series.length / 2), Math.max(0, series.length - 1)].map(function (i) {
                    var x = pad.left + (series.length <= 1 ? 0 : i * innerW / (series.length - 1));
                    return '<text x="' + x.toFixed(1) + '" y="' + (height - 7) + '" text-anchor="middle" fill="#9ca3af" font-size="10">' + esc((series[i] || {}).date || '') + '</text>';
                }).join('');
                return '<svg viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="API requests over the last 30 days">' +
                    grid + '<polyline fill="rgba(16,163,127,.10)" stroke="none" points="' + pad.left + ',' + (pad.top + innerH) + ' ' + points + ' ' + (width - pad.right) + ',' + (pad.top + innerH) + '"/>' +
                    '<polyline fill="none" stroke="#10a37f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="' + points + '"/>' + labels + '</svg>';
            }
            function render(data) {
                var root = document.getElementById('chat-api-tab-panel-usage');
                if (!root) return;
                var s = data.summary || {}, l = data.limits || {}, series = data.series || [];
                var keys = (data.keys || []).map(function (key) {
                    return '<div class="ptero-usage-key"><span><strong>' + esc(key.name || 'API key') + '</strong><br><code>' + esc(key.key_prefix || '') + '••••••</code></span><span>' + esc(key.last_used_at ? 'Last used ' + key.last_used_at : 'Not used yet') + '</span></div>';
                }).join('');
                root.innerHTML =
                    '<section id="ptero-api-usage-dashboard">' +
                    '<div class="ptero-usage-head"><div><p class="ptero-usage-eyebrow">Developer analytics</p><h3 class="ptero-usage-title">API usage</h3><p class="ptero-usage-subtitle">Requests and token consumption for your API keys over the last ' + esc(data.period_days || 30) + ' days.</p></div><button type="button" class="ptero-usage-refresh">Refresh</button></div>' +
                    '<div class="ptero-usage-cards">' +
                    '<div class="ptero-usage-card"><div class="ptero-usage-card-label">Requests</div><div class="ptero-usage-card-value">' + fmt(s.requests) + '</div><div class="ptero-usage-card-note">Successful API calls</div></div>' +
                    '<div class="ptero-usage-card"><div class="ptero-usage-card-label">Tokens</div><div class="ptero-usage-card-value">' + fmt(s.tokens) + '</div><div class="ptero-usage-card-note">Estimated when provider data is unavailable</div></div>' +
                    '<div class="ptero-usage-card"><div class="ptero-usage-card-label">Failed requests</div><div class="ptero-usage-card-value">' + fmt(s.failures) + '</div><div class="ptero-usage-card-note">HTTP errors and rejected calls</div></div>' +
                    '<div class="ptero-usage-card"><div class="ptero-usage-card-label">Average latency</div><div class="ptero-usage-card-value">' + fmt(s.avg_latency_ms) + ' ms</div><div class="ptero-usage-card-note">Across recorded requests</div></div>' +
                    '</div>' +
                    '<section class="ptero-usage-panel"><div class="ptero-usage-panel-head"><h4 class="ptero-usage-panel-title">Requests by day</h4><span class="ptero-usage-legend">Last ' + esc(data.period_days || 30) + ' days</span></div><div class="ptero-usage-chart">' + drawChart(series) + '</div></section>' +
                    '<section class="ptero-usage-panel"><div class="ptero-usage-panel-head"><h4 class="ptero-usage-panel-title">Exact API limits</h4><span class="ptero-usage-legend">Applied to each API key</span></div><dl class="ptero-usage-limits">' +
                    '<div class="ptero-usage-limit"><dt>Requests per minute</dt><dd>' + fmt(l.requests_per_minute) + '</dd></div>' +
                    '<div class="ptero-usage-limit"><dt>Maximum requests per day</dt><dd>' + fmt(l.requests_per_day) + '</dd></div>' +
                    '<div class="ptero-usage-limit"><dt>Tokens per hour</dt><dd>' + fmt(l.tokens_per_hour) + '</dd></div>' +
                    '<div class="ptero-usage-limit"><dt>GitHub-star token quota</dt><dd>' + fmt(l.starred_tokens_per_hour) + '</dd></div>' +
                    '<div class="ptero-usage-limit"><dt>Quota reset window</dt><dd>Every 1 hour</dd></div>' +
                    '<div class="ptero-usage-limit"><dt>Maximum output tokens</dt><dd>' + fmt(l.max_output_tokens) + '</dd></div>' +
                    '<div class="ptero-usage-limit"><dt>Usage history retained</dt><dd>' + fmt(l.retention_days) + ' days</dd></div>' +
                    '</dl></section>' +
                    '<section class="ptero-usage-panel"><div class="ptero-usage-panel-head"><h4 class="ptero-usage-panel-title">Tracked API keys</h4></div><p class="ptero-usage-keys">' + (keys || (data.has_api_keys ? 'No key activity recorded yet.' : 'Create an API key to start tracking usage.')) + '</p></section>' +
                    '</section>';
                root.querySelector('.ptero-usage-refresh').addEventListener('click', function () { load(true); });
            }
            function load(force) {
                var root = document.getElementById('chat-api-tab-panel-usage');
                if (!root || (loaded && !force)) return;
                loaded = true;
                root.innerHTML = '<p class="ptero-usage-status">Loading API usage…</p>';
                fetch(endpoint, {credentials:'same-origin', headers:headers(), cache:'no-store'}).then(function (res) {
                    if (!res.ok) throw new Error('Usage data could not be loaded.');
                    return res.json();
                }).then(render).catch(function (error) {
                    root.innerHTML = '<p class="ptero-usage-error">' + esc(error.message || 'Usage data could not be loaded.') + '</p>';
                    loaded = false;
                });
            }
            function replaceDepends() {
                var view = document.getElementById('chat-api-view');
                if (!view) return;
                var walker = document.createTreeWalker(view, NodeFilter.SHOW_TEXT);
                var node;
                while ((node = walker.nextNode())) {
                    node.nodeValue = node.nodeValue
                        .replace(/Depends on hourly token limit/g, '30 requests/minute; 500,000 tokens/hour')
                        .replace(/\bDepends\b/g, '30 requests/minute');
                }
            }
            function init() {
                var tab = document.querySelector('.chat-api-tab-btn[data-api-tab="usage"]');
                if (!tab) return setTimeout(init, 500);
                tab.addEventListener('click', function () { setTimeout(function () { replaceDepends(); load(false); }, 0); });
                replaceDepends();
                if (!document.getElementById('chat-api-tab-panel-usage').hidden) load(false);
            }
            if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
            else init();
        }());
        </script>
        <?php
    }

    public static function get_models() {
        $raw = defined('MLP_AI_CHAT_MODELS')
            ? @unserialize(MLP_AI_CHAT_MODELS, array('allowed_classes' => false))
            : array();
        $models = array();

        if (!is_array($raw)) {
            $raw = array();
        }

        foreach ($raw as $id => $config) {
            if (!is_array($config)) {
                continue;
            }

            $label = !empty($config['label']) ? (string) $config['label'] : (string) $id;
            $logo = !empty($config['logo']) ? esc_url_raw((string) $config['logo']) : '';
            if (!$logo) {
                $initials = strtoupper(substr(preg_replace('/[^a-z0-9]/i', '', $label), 0, 2));
                $svg = '<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 96 96"><rect width="96" height="96" rx="22" fill="#10a37f"/><text x="48" y="57" text-anchor="middle" font-family="Arial,sans-serif" font-size="30" font-weight="700" fill="#fff">' . esc_html($initials ?: 'AI') . '</text></svg>';
                $logo = 'data:image/svg+xml;base64,' . base64_encode($svg);
            }

            $models[] = array(
                'id' => sanitize_text_field((string) $id),
                'name' => sanitize_text_field($label),
                'provider' => sanitize_text_field(isset($config['provider']) ? (string) $config['provider'] : 'Ptero AI'),
                'provider_model' => sanitize_text_field(isset($config['api_model']) ? (string) $config['api_model'] : (string) $id),
                'logo' => $logo,
                'supports_images' => !empty($config['supports_images']),
                'is_free' => isset($config['is_paid']) ? !$config['is_paid'] : true,
            );
        }

        return rest_ensure_response(array(
            'models' => $models,
            'endpoint' => esc_url_raw(rest_url('mlp/v1/chat')),
        ));
    }

