            @media (max-width:620px) { .ptero-api-tools-head { display:block; } .ptero-api-tools-row, .ptero-api-model-grid { grid-template-columns:1fr; } .ptero-api-playground-toolbar, .ptero-api-playground-composer-bar { align-items:flex-start; flex-direction:column; gap:8px; } }
            /* Refined developer-console treatment */
            .ptero-api-tools { color:#1f3442; font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
            .ptero-api-tools-head { position:relative; overflow:hidden; margin-bottom:18px; padding:24px 26px; border:1px solid #dce7e6; border-radius:16px; background:linear-gradient(135deg,#f3fbf8 0%,#f7fafc 58%,#eef5f7 100%); }
            .ptero-api-tools-head:after { position:absolute; right:-44px; top:-66px; width:190px; height:190px; border:28px solid rgba(16,163,127,.08); border-radius:50%; content:""; }
            .ptero-api-tools-eyebrow { color:#07866b; letter-spacing:.13em; }
            .ptero-api-tools-title { color:#183342; font-size:24px; letter-spacing:-.035em; }
            .ptero-api-tools-subtitle { max-width:620px; color:#647783; font-size:13px; }
            .ptero-api-playground-shell { grid-template-columns:245px minmax(0,1fr); min-height:590px; border:1px solid #dce7e6; border-radius:16px; background:#fff; box-shadow:0 14px 35px rgba(31,52,66,.08); }
            .ptero-api-playground-sidebar { border-right:1px solid #e7eef0; background:#f7fafb; padding:20px; }
            .ptero-api-playground-sidebar .ptero-api-tools-label { color:#526975; font-size:10px; letter-spacing:.08em; text-transform:uppercase; }
            .ptero-api-tools-input, .ptero-api-tools-select, .ptero-api-tools-textarea { border-color:#d6e2e5; border-radius:9px; color:#1f3442; }
            .ptero-api-tools-input:focus, .ptero-api-tools-select:focus, .ptero-api-tools-textarea:focus { border-color:#0b9a78; box-shadow:0 0 0 3px rgba(11,154,120,.12); }
            .ptero-api-tools-note { color:#82939c; }
