            .ptero-api-tools-btn { border:1px solid #087f63; border-radius:9px; background:#087f63; padding:10px 13px; box-shadow:0 4px 10px rgba(8,127,99,.14); transition:background .18s ease,transform .18s ease,box-shadow .18s ease; }
            .ptero-api-tools-btn:hover { background:#066b54; box-shadow:0 6px 14px rgba(8,127,99,.2); transform:translateY(-1px); }
            .ptero-api-tools-btn-secondary { border-color:#d5e0e4; background:#fff; color:#526975; box-shadow:none; }
            .ptero-api-tools-btn-secondary:hover { background:#f4f8f9; color:#1f3442; }
            .ptero-api-playground-main { background:#fff; }
            .ptero-api-playground-toolbar { padding:16px 20px; background:#fff; }
            .ptero-api-playground-toolbar-title { color:#1f3442; font-size:14px; }
            .ptero-api-playground-toolbar-caption { color:#8a9aa2; font-size:11px; }
            .ptero-api-playground-log { gap:12px; padding:22px; background:linear-gradient(180deg,#fff 0%,#fbfcfc 100%); }
            .ptero-api-playground-empty { max-width:310px; margin:auto; min-height:190px; border:1px dashed #cfdee0; border-radius:14px; color:#8a9aa2; background:#f8fbfb; }
            .ptero-api-playground-message { position:relative; max-width:80%; border:1px solid #e2eaeb; border-radius:13px; padding:12px 14px; color:#304652; box-shadow:0 3px 10px rgba(31,52,66,.04); }
            .ptero-api-playground-message:before { display:block; margin-bottom:5px; color:#8a9aa2; font-size:9px; font-weight:800; letter-spacing:.11em; }
            .ptero-api-playground-message.user { border-color:#087f63; background:#087f63; color:#fff; box-shadow:0 5px 14px rgba(8,127,99,.16); }
            .ptero-api-playground-message.user:before { content:"YOU"; color:rgba(255,255,255,.7); }
            .ptero-api-playground-message.assistant { align-self:flex-start; background:#fff; color:#304652; }
            .ptero-api-playground-message.assistant:before { content:"MODEL"; color:#0b9a78; }
            .ptero-api-playground-composer { padding:15px 20px 18px; background:#fff; }
            .ptero-api-playground-composer .ptero-api-tools-textarea { min-height:86px; background:#fbfdfd; }
            .ptero-api-playground-shortcut { color:#9aa8ae; font-size:10px; }
            .ptero-api-tools-status { border-radius:9px; font-size:11px; }
            #ptero-api-playground-status.ptero-api-thinking-status { display:inline-flex; align-items:center; gap:9px; margin:0; padding:8px 10px; border-color:#b8eadc; background:#effbf7; color:#087f63; white-space:nowrap; }
            .ptero-api-thinking-cubes { position:relative; display:inline-block; width:30px; height:15px; vertical-align:middle; }
            .ptero-api-thinking-cubes i { position:absolute; top:50%; left:50%; display:block; width:7px; height:7px; border-radius:2px; background:#0b9a78; transform:translate(-50%,-50%) translate(0,-5px) rotate(45deg) scale(.65); transform-origin:center; animation:pteroApiCubeThink .72s cubic-bezier(.4,0,.2,1) infinite; will-change:transform,opacity; }
            .ptero-api-thinking-cubes i:nth-child(1) { --cube-x:-10px; animation-delay:0s; }
            .ptero-api-thinking-cubes i:nth-child(2) { --cube-x:0; animation-delay:.08s; }
            .ptero-api-thinking-cubes i:nth-child(3) { --cube-x:10px; animation-delay:.16s; }
            .ptero-api-thinking-label { font-weight:700; letter-spacing:.01em; }
            @keyframes pteroApiCubeThink { 0% { transform:translate(-50%,-50%) translate(0,-5px) rotate(45deg) scale(.65); opacity:.3; } 22% { transform:translate(-50%,-50%) translate(var(--cube-x),0) rotate(0deg) scale(1); opacity:1; } 55%, 76% { transform:translate(-50%,-50%) translate(var(--cube-x),0) rotate(0deg) scale(1); opacity:1; } 100% { transform:translate(-50%,-50%) translate(var(--cube-x),-3px) rotate(-45deg) scale(.72); opacity:.3; } }
            @media (prefers-reduced-motion: reduce) { .ptero-api-thinking-cubes i { animation:none; opacity:.7; } }
            .ptero-api-playground-thinking { align-items:center; align-self:flex-start; display:flex; gap:10px; margin:0 0 2px; padding:10px 13px; border:1px solid #dce9e7; border-radius:12px; background:#f4fbf9; color:#58717a; font-size:11px; box-shadow:0 3px 9px rgba(31,52,66,.04); }
            .ptero-api-thinking-dots { align-items:center; display:inline-flex; gap:4px; height:10px; }
            .ptero-api-thinking-dots i { width:6px; height:6px; border-radius:50%; background:#0b9a78; animation:pteroApiDotThink 1.1s ease-in-out infinite; }
            .ptero-api-thinking-dots i:nth-child(2) { animation-delay:.16s; }
            .ptero-api-thinking-dots i:nth-child(3) { animation-delay:.32s; }
            @keyframes pteroApiDotThink { 0%, 60%, 100% { opacity:.35; transform:translateY(0); } 30% { opacity:1; transform:translateY(-4px); } }
            .ptero-api-key-status { display:none; margin:12px 0 0; padding:9px 11px; border:1px solid transparent; border-radius:9px; font-size:11px; line-height:1.4; }
            .ptero-api-key-status.is-visible { display:block; }
            .ptero-api-key-status.is-success { border-color:#b8eadc; background:#effbf7; color:#087f63; }
            .ptero-api-key-status.is-error { border-color:#f3c7c7; background:#fff6f6; color:#bd3f3f; }
            @media (prefers-reduced-motion: reduce) { .ptero-api-thinking-dots i { animation:none; opacity:.7; } }
            @media (max-width:760px) {
                .ptero-api-playground-shell { grid-template-columns:1fr; }
                .ptero-api-playground-sidebar { border-right:0; border-bottom:1px solid #e7eef0; }
                .ptero-api-playground-sidebar .ptero-api-tools-actions { display:grid; grid-template-columns:1fr 1fr; }
            }
            @media (max-width:520px) {
                .ptero-api-tools-head { padding:20px; }
                .ptero-api-tools-title { font-size:21px; }
                .ptero-api-playground-log { padding:14px; }
                .ptero-api-playground-message { max-width:92%; }
                .ptero-api-playground-toolbar, .ptero-api-playground-composer { padding-left:14px; padding-right:14px; }
            }
        </style>
        <script>
        (function () {
            var apiRoot = <?php echo wp_json_encode($rest_url); ?>;
            var chatEndpoint = <?php echo wp_json_encode($rest_url . '/chat'); ?>;
            var modelsEndpoint = <?php echo wp_json_encode($rest_url . '/api-models'); ?>;
            var nonce = <?php echo wp_json_encode($nonce); ?>;
            var sessionKey = 'ptero_api_playground_key';
            var models = [];
            var history = [];
            var selectedModel = '';
            var initialized = false;
            var keyStatusTimer = null;

            function esc(value) {
                return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
                    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];
                });
            }
            function getKey() {
                try { return sessionStorage.getItem(sessionKey) || ''; } catch (e) { return ''; }
            }
            function setKey(value) {
                try { if (value) sessionStorage.setItem(sessionKey, value); else sessionStorage.removeItem(sessionKey); } catch (e) {}
            }
            function requestHeaders(key) {
                var headers = {'Content-Type':'application/json', 'X-WP-Nonce':nonce};
                if (key) headers.Authorization = 'Bearer ' + key;
                return headers;
            }
            function setStatus(message, error) {
                var el = document.getElementById('ptero-api-playground-status');
                if (!el) return;
                el.textContent = message || '';
                el.className = 'ptero-api-tools-status is-visible ' + (error ? 'is-error' : 'is-success');
            }
            function setThinkingStatus(message) {
                var el = document.getElementById('ptero-api-playground-status');
                if (!el) return;
                el.innerHTML = '<span class="ptero-api-thinking-cubes" aria-hidden="true"><i></i><i></i><i></i></span><span class="ptero-api-thinking-label"></span>';
                var label = el.querySelector('.ptero-api-thinking-label');
                if (label) label.textContent = message || 'Thinking…';
                el.className = 'ptero-api-tools-status is-visible is-success ptero-api-thinking-status';
            }
            function clearStatus() {
                var el = document.getElementById('ptero-api-playground-status');
                if (!el) return;
                el.textContent = '';
                el.className = 'ptero-api-tools-status';
            }
            function setKeyStatus(message, error) {
                var el = document.getElementById('ptero-api-playground-key-status');
                if (!el) return;
                if (keyStatusTimer) clearTimeout(keyStatusTimer);
                el.textContent = message || '';
                el.className = 'ptero-api-key-status ' + (message ? 'is-visible ' : '') + (error ? 'is-error' : 'is-success');
                if (message) {
                    keyStatusTimer = setTimeout(function () {
                        el.textContent = '';
                        el.className = 'ptero-api-key-status';
                    }, 3000);
                }
            }
            function activateTab(tab) {
                var buttons = document.querySelectorAll('.chat-api-tab-btn');
                var panels = document.querySelectorAll('.chat-api-tab-panel');
                buttons.forEach(function (button) {
                    var active = button.getAttribute('data-api-tab') === tab;
                    button.classList.toggle('active', active);
                    button.setAttribute('aria-selected', active ? 'true' : 'false');
                });
                panels.forEach(function (panel) {
                    if (panel.getAttribute('data-api-panel') === tab) panel.removeAttribute('hidden');
                    else panel.setAttribute('hidden', '');
                });
                if (tab === 'playground') renderPlayground();
                if (tab === 'models') renderModels();
            }
            function addApiTabs() {
                var page = document.querySelector('.chat-api-page');
                var tabs = page && page.querySelector('.chat-api-tabs');
                if (!page || !tabs) return false;
                if (!document.getElementById('chat-api-tab-panel-playground')) {
                    ['playground', 'models'].forEach(function (tab) {
                        var button = document.createElement('button');
                        button.type = 'button';
                        button.className = 'chat-api-tab-btn';
                        button.setAttribute('data-api-tab', tab);
                        button.setAttribute('role', 'tab');
                        button.setAttribute('aria-selected', 'false');
                        button.textContent = tab === 'playground' ? 'Playground' : 'Models';
                        tabs.appendChild(button);
                    });
                    var playground = document.createElement('div');
                    playground.className = 'chat-api-tab-panel';
                    playground.id = 'chat-api-tab-panel-playground';
                    playground.setAttribute('data-api-panel', 'playground');
                    playground.hidden = true;
                    page.appendChild(playground);
                    var modelsPanel = document.createElement('div');
                    modelsPanel.className = 'chat-api-tab-panel';
                    modelsPanel.id = 'chat-api-tab-panel-models';
                    modelsPanel.setAttribute('data-api-panel', 'models');
                    modelsPanel.hidden = true;
                    page.appendChild(modelsPanel);
                }
                return true;
            }
            function renderPlayground() {
                var root = document.getElementById('chat-api-tab-panel-playground');
                if (!root) return;
                var currentKey = getKey();
                root.innerHTML =
                    '<section class="ptero-api-tools"><div class="ptero-api-tools-head"><div><p class="ptero-api-tools-eyebrow">Live API testing</p><h3 class="ptero-api-tools-title">API Playground</h3><p class="ptero-api-tools-subtitle">A private workspace for testing your key against the same endpoint your application will call.</p></div></div>' +
                    '<div class="ptero-api-playground-shell"><aside class="ptero-api-playground-sidebar"><label class="ptero-api-tools-label" for="ptero-api-playground-key">API key</label><input id="ptero-api-playground-key" class="ptero-api-tools-input" type="password" autocomplete="off" placeholder="mlp_..." value="' + esc(currentKey) + '"><div class="ptero-api-tools-actions"><button type="button" class="ptero-api-tools-btn" id="ptero-api-save-key">Save key</button><button type="button" class="ptero-api-tools-btn ptero-api-tools-btn-secondary" id="ptero-api-clear-key">Clear</button></div><label class="ptero-api-tools-label" for="ptero-api-playground-model">Model</label><select id="ptero-api-playground-model" class="ptero-api-tools-select">' + models.map(function (model) { return '<option value="' + esc(model.id) + '"' + (model.id === selectedModel ? ' selected' : '') + '>' + esc(model.name) + '</option>'; }).join('') + '</select><label class="ptero-api-tools-label">Endpoint</label><input class="ptero-api-tools-input" value="' + esc(chatEndpoint) + '" readonly><p class="ptero-api-tools-note">Your key stays in this browser session and is only sent to your own API endpoint.</p></aside><main class="ptero-api-playground-main"><div class="ptero-api-playground-toolbar"><div><p class="ptero-api-playground-toolbar-title">Test conversation</p><p class="ptero-api-playground-toolbar-caption">Model responses are counted in API usage.</p></div><button type="button" class="ptero-api-tools-btn ptero-api-tools-btn-secondary" id="ptero-api-playground-clear">New conversation</button></div><div id="ptero-api-playground-log" class="ptero-api-playground-log"><div class="ptero-api-playground-empty">Choose a model, add your API key, and send a message to begin.</div></div><div class="ptero-api-playground-composer"><textarea id="ptero-api-playground-prompt" class="ptero-api-tools-textarea" placeholder="Message your model…"></textarea><div class="ptero-api-playground-composer-bar"><span class="ptero-api-playground-shortcut">Ctrl / ⌘ + Enter to send</span><div class="ptero-api-tools-actions" style="margin-top:0;"><span id="ptero-api-playground-status" class="ptero-api-tools-status"></span><button type="button" class="ptero-api-tools-btn" id="ptero-api-playground-send">Send request</button></div></div></div></main></div></section>';
                var keyActions = root.querySelector('#ptero-api-save-key');
                var keyStatus = document.createElement('div');
                keyStatus.id = 'ptero-api-playground-key-status';
                keyStatus.className = 'ptero-api-key-status';
                keyStatus.setAttribute('role', 'status');
                keyStatus.setAttribute('aria-live', 'polite');
                if (keyActions && keyActions.parentNode && keyActions.parentNode.parentNode) keyActions.parentNode.parentNode.insertBefore(keyStatus, keyActions.parentNode);
                var modelSelect = document.getElementById('ptero-api-playground-model');
                if (modelSelect && !selectedModel && models.length) {
                    selectedModel = models[0].id;
                    modelSelect.value = selectedModel;
                }
                var keyInput = document.getElementById('ptero-api-playground-key');
                document.getElementById('ptero-api-save-key').addEventListener('click', function () {
                    var value = keyInput.value.trim();
                    if (!value) return setKeyStatus('Enter an API key first.', true);
                    setKey(value);
                    setKeyStatus('API key saved for this browser session.', false);
                });
                document.getElementById('ptero-api-clear-key').addEventListener('click', function () {
                    setKey('');
                    keyInput.value = '';
                    setKeyStatus('API key cleared from this browser session.', false);
                });
                modelSelect.addEventListener('change', function () { selectedModel = modelSelect.value; });
                document.getElementById('ptero-api-playground-send').addEventListener('click', sendPlaygroundRequest);
                document.getElementById('ptero-api-playground-clear').addEventListener('click', function () {
                    history = [];
                    document.getElementById('ptero-api-playground-log').innerHTML = '';
                    setStatus('', false);
                });
                document.getElementById('ptero-api-playground-prompt').addEventListener('keydown', function (event) {
                    if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') sendPlaygroundRequest();
                });
            }
            function appendMessage(role, text) {
                var log = document.getElementById('ptero-api-playground-log');
                if (!log) return;
                var empty = log.querySelector('.ptero-api-playground-empty');
                if (empty) empty.remove();
                var item = document.createElement('div');
                item.className = 'ptero-api-playground-message ' + role;
                item.textContent = text;
                log.appendChild(item);
                log.scrollTop = log.scrollHeight;
            }
            function appendThinkingMessage() {
                var log = document.getElementById('ptero-api-playground-log');
                if (!log) return null;
                var item = document.createElement('div');
                item.className = 'ptero-api-playground-thinking';
                item.setAttribute('role', 'status');
                item.setAttribute('aria-live', 'polite');
                item.innerHTML = '<span class="ptero-api-thinking-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>Thinking…</span>';
                log.appendChild(item);
                log.scrollTop = log.scrollHeight;
                return item;
            }
            function removeThinkingMessage(item) {
                if (item && item.parentNode) item.parentNode.removeChild(item);
            }
            function sendPlaygroundRequest() {
                var keyInput = document.getElementById('ptero-api-playground-key');
                var promptInput = document.getElementById('ptero-api-playground-prompt');
                var modelInput = document.getElementById('ptero-api-playground-model');
                var sendButton = document.getElementById('ptero-api-playground-send');
                var key = (keyInput && keyInput.value.trim()) || getKey();
                var message = promptInput && promptInput.value.trim();
                if (!key) return setStatus('Enter an API key before sending a request.', true);
                if (!message) return setStatus('Enter a message before sending a request.', true);
                setKey(key);
                appendMessage('user', message);
                var thinkingMessage = appendThinkingMessage();
                history.push({role:'user', text:message});
                promptInput.value = '';
                sendButton.disabled = true;
                clearStatus();
                fetch(chatEndpoint, {
                    method:'POST',
                    credentials:'same-origin',
                    headers:requestHeaders(key),
                    body:JSON.stringify({model:modelInput.value, message:message, history:history})
                }).then(function (response) {
                    return response.json().then(function (data) {
                        if (!response.ok) throw new Error(data.message || data.code || 'The API request failed.');
                        return data;
                    });
                }).then(function (data) {
                    removeThinkingMessage(thinkingMessage);
                    var reply = data.reply || data.text || 'The API returned an empty response.';
                    appendMessage('assistant', reply);
                    history.push({role:'assistant', text:reply});
                    setStatus('Request completed with ' + (data.model_used || modelInput.value) + '.', false);
                }).catch(function (error) {
                    removeThinkingMessage(thinkingMessage);
                    appendMessage('assistant', 'Error: ' + (error.message || 'Request failed.'));
                    history.pop();
                    setStatus(error.message || 'The API request failed.', true);
                }).finally(function () { sendButton.disabled = false; });
            }
            function codeExamples(modelId) {
                var payload = JSON.stringify({model:modelId, message:'Hello from my app', history:[]}, null, 2);
                var endpoint = chatEndpoint;
                return {
                    curl: 'curl -X POST "' + endpoint + '" \\\n  -H "Authorization: Bearer YOUR_API_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d ' + String.fromCharCode(39) + payload.replace(/\\n/g, '\\n  ') + String.fromCharCode(39),
                    python: 'import requests\\n\\nresponse = requests.post(\\n    "' + endpoint + '",\\n    headers={"Authorization": "Bearer YOUR_API_KEY"},\\n    json=' + payload.replace(/^/gm, '    ') + '\\n)\\nprint(response.json()["reply"])',
                    javascript: 'const response = await fetch("' + endpoint + '", {\\n  method: "POST",\\n  headers: {\\n    "Authorization": "Bearer " + process.env.MLP_API_KEY,\\n    "Content-Type": "application/json"\\n  },\\n  body: JSON.stringify(' + payload + ')\\n});\\nconsole.log((await response.json()).reply);'
                };
            }
            function renderModelDetail(model) {
                var detail = document.getElementById('ptero-api-model-detail');
                if (!detail || !model) return;
                var examples = codeExamples(model.id);
                detail.innerHTML =
                    '<div class="ptero-api-model-detail-title"><img src="' + esc(model.logo) + '" alt=""><div><h4>' + esc(model.name) + '</h4><p>API model ID: <code>' + esc(model.id) + '</code> · Provider model: <code>' + esc(model.provider_model) + '</code></p></div></div>' +
                    '<div class="ptero-api-code-wrap"><button type="button" class="ptero-api-tools-btn ptero-api-tools-btn-secondary ptero-api-copy" data-copy-code="ptero-api-curl">Copy</button><strong style="display:block;font-size:11px;margin-top:12px;">cURL</strong><pre id="ptero-api-curl" class="ptero-api-code">' + esc(examples.curl) + '</pre></div>' +
                    '<div class="ptero-api-code-wrap"><button type="button" class="ptero-api-tools-btn ptero-api-tools-btn-secondary ptero-api-copy" data-copy-code="ptero-api-python">Copy</button><strong style="display:block;font-size:11px;margin-top:12px;">Python</strong><pre id="ptero-api-python" class="ptero-api-code">' + esc(examples.python) + '</pre></div>' +
                    '<div class="ptero-api-code-wrap"><button type="button" class="ptero-api-tools-btn ptero-api-tools-btn-secondary ptero-api-copy" data-copy-code="ptero-api-javascript">Copy</button><strong style="display:block;font-size:11px;margin-top:12px;">JavaScript</strong><pre id="ptero-api-javascript" class="ptero-api-code">' + esc(examples.javascript) + '</pre></div>';
                detail.querySelectorAll('[data-copy-code]').forEach(function (button) {
                    button.addEventListener('click', function () {
                        var code = document.getElementById(button.getAttribute('data-copy-code'));
                        navigator.clipboard.writeText(code.textContent).then(function () {
                            button.textContent = 'Copied';
                            setTimeout(function () { button.textContent = 'Copy'; }, 1200);
                        });
                    });
                });
            }
            function renderModels() {
                var root = document.getElementById('chat-api-tab-panel-models');
                if (!root) return;
                root.innerHTML = '<section class="ptero-api-tools"><div class="ptero-api-tools-head"><div><p class="ptero-api-tools-eyebrow">Model directory</p><h3 class="ptero-api-tools-title">Available models</h3><p class="ptero-api-tools-subtitle">Choose a model to open its details in the left sidebar and copy-ready integration examples.</p></div></div><div class="ptero-api-model-layout"><aside id="ptero-api-model-detail" class="ptero-api-tools-card"><p class="ptero-api-model-empty">Select a model to open its details here.</p></aside><div class="ptero-api-model-list"><div class="ptero-api-model-grid">' + (models.length ? models.map(function (model) {
                    return '<button type="button" class="ptero-api-model-card" data-model-id="' + esc(model.id) + '"><img class="ptero-api-model-logo" src="' + esc(model.logo) + '" alt=""><span class="ptero-api-model-info"><span class="ptero-api-model-name">' + esc(model.name) + '</span><span class="ptero-api-model-id">' + esc(model.id) + '</span><span class="ptero-api-model-meta">' + esc(model.provider) + (model.supports_images ? ' · Vision' : '') + '</span></span></button>';
                }).join('') : '<p class="ptero-api-model-empty">No models are configured on this site.</p>') + '</div></div></div></section>';
                root.querySelectorAll('[data-model-id]').forEach(function (card) {
                    card.addEventListener('click', function () {
                        root.querySelectorAll('[data-model-id]').forEach(function (item) { item.classList.remove('is-selected'); });
                        card.classList.add('is-selected');
                        var model = models.find(function (item) { return item.id === card.getAttribute('data-model-id'); });
                        selectedModel = model ? model.id : selectedModel;
                        renderModelDetail(model);
                    });
                });
            }
            function loadModels() {
                return fetch(modelsEndpoint, {credentials:'same-origin', headers:{'X-WP-Nonce':nonce}, cache:'no-store'}).then(function (response) {
                    if (!response.ok) throw new Error('Models could not be loaded.');
                    return response.json();
                }).then(function (data) {
                    models = Array.isArray(data.models) ? data.models : [];
                    selectedModel = selectedModel || (models[0] && models[0].id) || '';
                    return models;
                });
            }
            function init() {
                if (initialized) return;
                if (!addApiTabs()) return setTimeout(init, 500);
                initialized = true;
                document.addEventListener('click', function (event) {
                    var button = event.target.closest && event.target.closest('.chat-api-tab-btn[data-api-tab]');
                    if (!button) return;
                    var tab = button.getAttribute('data-api-tab');
                    if (tab === 'playground' || tab === 'models') {
                        event.preventDefault();
                        event.stopPropagation();
                        activateTab(tab);
                     } else {
                         document.querySelectorAll('.chat-api-tab-btn[data-api-tab="playground"], .chat-api-tab-btn[data-api-tab="models"]').forEach(function (customButton) {
                             customButton.classList.remove('active');
                             customButton.setAttribute('aria-selected', 'false');
                         });
                         document.querySelectorAll('.chat-api-tab-panel[data-api-panel="playground"], .chat-api-tab-panel[data-api-panel="models"]').forEach(function (customPanel) {
                             customPanel.setAttribute('hidden', '');
                         });
                    }
                }, true);
                loadModels().then(function () {
                    var playground = document.getElementById('chat-api-tab-panel-playground');
                    if (playground && !playground.hidden) renderPlayground();
                }).catch(function () {
                    models = [];
                });
            }
            if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
            else init();
        }());
        </script>
        <?php
    }
}

add_action('plugins_loaded', array('Ptero_AI_API_Usage_Dashboard', 'boot'), 30);
if (!function_exists('ptero_ai_chat_agent_mode_request')) {
    function ptero_ai_chat_agent_workspace_context(WP_REST_Request $request, $project_id) {
        global $wpdb;
        $project_id = sanitize_text_field((string) $project_id);
        if (!$project_id || !preg_match('/^[A-Za-z0-9_-]{1,80}$/', $project_id)) {
            return '';
        }
        $identity_key = '';
        $user_id = get_current_user_id();
        if ($user_id) {
            $identity_key = 'wp_' . (int) $user_id;
        } else {
            $guest_token = (string) $request->get_header('x-mlp-guest-token');
            if ('' === $guest_token && !empty($_COOKIE['mlp_ai_guest_token'])) {
                $guest_token = wp_unslash($_COOKIE['mlp_ai_guest_token']);
            }
            $guest_token = substr(preg_replace('/[^a-zA-Z0-9]/', '', $guest_token), 0, 64);
            $verified = get_option('mlp_ai_github_verified', array());
            $login = is_array($verified) && $guest_token && !empty($verified[$guest_token]['login'])
                ? (string) $verified[$guest_token]['login'] : '';
            if ($login) {
                $slug = strtolower(preg_replace('/[^a-zA-Z0-9_-]/', '', $login));
                $identity_key = 'gh_' . substr($slug, 0, 64);
            }
        }
        if (!$identity_key) {
            return '';
        }
        $projects_table = $wpdb->prefix . 'mlp_ai_cloud_projects';
        $project_row = $wpdb->get_row($wpdb->prepare(
            "SELECT projects_json FROM $projects_table WHERE identity_key = %s LIMIT 1",
            $identity_key
        ), ARRAY_A);
        if (!$project_row || empty($project_row['projects_json'])) {
            return '';
        }
        $decoded = json_decode($project_row['projects_json'], true);
        $projects = is_array($decoded) && isset($decoded['projects']) && is_array($decoded['projects'])
            ? $decoded['projects'] : array();
        $owns_project = false;
        foreach ($projects as $project) {
            if (is_array($project) && isset($project['id']) && (string) $project['id'] === $project_id) {
                $owns_project = true;
                break;
            }
        }
        if (!$owns_project) {
            return '';
        }
        $files_table = $wpdb->prefix . 'mlp_ai_project_files';
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT filename, language, content FROM $files_table WHERE identity_key = %s AND project_id = %s ORDER BY filename ASC LIMIT 35",
            $identity_key,
            $project_id
        ), ARRAY_A);
        if (!$rows) {
            return "PROJECT WORKSPACE: The active project has no saved files yet. Work from the user's request and any attached files.";
        }
        $context = "PROJECT WORKSPACE: The following saved files belong to the authenticated active project. Treat them as the current workspace. Do not invent files that are not present, and clearly identify proposed new files.\n";
        $total_chars = 0;
        foreach ($rows as $row) {
            $filename = isset($row['filename']) ? (string) $row['filename'] : 'unnamed-file';
            $language = isset($row['language']) ? (string) $row['language'] : 'plaintext';
            $content = isset($row['content']) ? (string) $row['content'] : '';
            $remaining = 600000 - $total_chars;
            if ($remaining <= 0) {
                $context .= "\n[Additional project files omitted after the workspace context limit. Ask the user to open a specific file if needed.]\n";
                break;
            }
            $content = substr($content, 0, min(120000, $remaining));
            $context .= "\n--- PROJECT FILE: " . $filename . " (" . $language . ") ---\n" . $content . "\n--- END PROJECT FILE ---\n";
            $total_chars += strlen($content);
        }
        return $context;
    }
    function ptero_ai_chat_agent_mode_request($result, $server, $request) {
        if (!($request instanceof WP_REST_Request)) {
            return $result;
        }
        $route = $request->get_route();
        if (!in_array($route, array('/mlp/v1/chat', '/mlp/v1/chat-stream'), true)) {
            return $result;
        }
        $raw_body = $request->get_body();
        if ('' === $raw_body) {
            return $result;
        }
        $params = json_decode($raw_body, true);
        if (!is_array($params) || 'agent' !== (isset($params['mode']) ? sanitize_key((string) $params['mode']) : '')) {
            return $result;
        }
        $task = isset($params['message']) ? (string) $params['message'] : '';
        $workspace = isset($params['project_id'])
            ? ptero_ai_chat_agent_workspace_context($request, $params['project_id']) : '';
        $directive = "AGENT MODE: Act as a senior autonomous software agent. First understand the user's objective and constraints, then make a concise plan. Investigate the supplied files, conversation context, repository context, and available web/GitHub tools before deciding. Work in explicit stages: PLAN, READ, EDIT, and CHECK. When an agent stage starts, emit one concise machine-readable status line using exactly one of these prefixes: PLAN:, READ:, EDIT:, or CHECK:, followed by the stage detail. These stage lines are internal activity updates rendered separately by the client; do not repeat them in the final answer. For large code, preserve existing behavior, make complete coherent changes, and never replace unseen code with placeholders. Use available tools when they materially improve accuracy. Validate the result mentally and check edge cases, security, compatibility, and likely runtime failures before responding. Ask a question only when a missing decision blocks progress; otherwise make a sensible assumption and continue. Finish with a concise implementation summary, verification notes, and any remaining limitation. Do not claim to have edited or executed files unless the available tools or supplied files support that claim. IMPORTANT: stage status lines are never a substitute for the answer. Every turn must end with the complete final answer written as ordinary text (explanation and filename-labeled code blocks) with no PLAN:, READ:, EDIT:, or CHECK: prefix. If you are not ready to deliver, say briefly what you still need in plain prose instead of emitting more status lines.";
        $params['mode'] = 'full';
        $params['message'] = $directive . "\n\n" . ($workspace ? $workspace . "\n\n" : '') . "SAFE WORKSPACE RULE: Propose file changes as complete, filename-labeled code blocks. Never claim that a project file was saved until the user applies it through the project editor.\n\nUSER TASK:\n" . $task;
        $request->set_body(wp_json_encode($params));
        $request->set_param('mode', 'full');
        return $result;
    }
    add_filter('rest_pre_dispatch', 'ptero_ai_chat_agent_mode_request', 5, 3);
}

/*
 * Android build workflow: make APK generation discoverable without claiming
 * that a binary was compiled when this WordPress host has no Android toolchain.
 * The directive is injected only for Android/APK requests and stays in the
 * single plugin file so deployments do not need an extra prompt/config file.
 */
if (!function_exists('ptero_ai_chat_android_build_directive')) {
    function ptero_ai_chat_android_build_directive($result, $server, $request) {
        if (!($request instanceof WP_REST_Request)) {
            return $result;
        }
        $route = $request->get_route();
        if (!in_array($route, array('/mlp/v1/chat', '/mlp/v1/chat-stream'), true)) {
            return $result;
        }
        $raw_body = $request->get_body();
        if ('' === $raw_body) {
            return $result;
        }
        $params = json_decode($raw_body, true);
        if (!is_array($params)) {
            return $result;
        }
        $task = isset($params['message']) ? (string) $params['message'] : '';
        if ('' === $task || preg_match('/PTERO ANDROID APK WORKFLOW:/i', $task)) {
            return $result;
        }
        $has_android_request = preg_match(
            '/\b(?:android|apk|aab|gradle|kotlin|jetpack compose|flutter|react native)\b/i',
            $task
        );
        if (!$has_android_request) {
            return $result;
        }
        $directive = "PTERO ANDROID APK WORKFLOW:\n"
            . "Treat this as an Android app delivery task. Generate the complete buildable project, including the Gradle settings, module build file, manifest, resources, source files, and a clear package/application ID. Prefer Kotlin and modern Android practices unless the user specifies another stack. If a real Android SDK and Gradle toolchain are available to the application, run the appropriate build (normally ./gradlew assembleDebug) and report the exact APK path and build result. If the toolchain is unavailable, do not claim that an APK was compiled: return the complete project files and the exact command the user can run to compile it. Never invent a binary APK, build log, test result, or signing status.";
        if (isset($params['attachments']) && is_array($params['attachments'])) {
            $android_source_extensions = array('java', 'kt', 'kts', 'gradle', 'properties', 'pro', 'toml', 'xml');
            foreach ($params['attachments'] as $index => $attachment) {
                if (!is_array($attachment) || empty($attachment['name'])) {
                    continue;
                }
                $extension = strtolower(pathinfo((string) $attachment['name'], PATHINFO_EXTENSION));
                if (in_array($extension, $android_source_extensions, true)) {
                    // Preserve the filename while ensuring the existing text
                    // attachment pipeline reads Android source files as text.
                    $params['attachments'][$index]['type'] = 'text/plain';
                }
            }
        }
        $params['message'] = $directive . "\n\n" . $task;
        $request->set_body(wp_json_encode($params));
        return $result;
    }
    add_filter('rest_pre_dispatch', 'ptero_ai_chat_android_build_directive', 3, 3);
}

/*
 * Models occasionally stop after emitting the first PLAN line even though
 * the agent directive asks for a final answer. Add a short, explicit
 * completion guard before the main agent transformer runs. This keeps the
 * original task intact while making "plan only" responses much less likely.
 */
if (!function_exists('ptero_ai_chat_agent_completion_guard')) {
    function ptero_ai_chat_agent_completion_guard($result, $server, $request) {
        if (!($request instanceof WP_REST_Request)) {
            return $result;
        }
        $route = $request->get_route();
        if (!in_array($route, array('/mlp/v1/chat', '/mlp/v1/chat-stream'), true)) {
            return $result;
        }
        $raw_body = $request->get_body();
        if ('' === $raw_body) {
            return $result;
        }
        $params = json_decode($raw_body, true);
        if (!is_array($params) || 'agent' !== (isset($params['mode']) ? sanitize_key((string) $params['mode']) : '')) {
            return $result;
        }
        $task = isset($params['message']) ? (string) $params['message'] : '';
        $guard = "NON-NEGOTIABLE AGENT COMPLETION RULE: Do not stop after a PLAN, READ, EDIT, or CHECK status line. Continue working through the task and return the complete final answer in this same response. The user must receive the requested result, not only a progress update. If you can reasonably proceed, do not ask for confirmation; make the sensible assumption and deliver the implementation.";
        $params['message'] = $guard . "\n\n" . $task;
        $request->set_body(wp_json_encode($params));
        $request->set_param('mode', 'agent');
        return $result;
    }
    add_filter('rest_pre_dispatch', 'ptero_ai_chat_agent_completion_guard', 4, 3);
}

/*
 * Agent-mode stage messages are deliberately kept out of the assistant answer.
 * The chat UI already knows how to render SSE activity events, so translate the
 * model's concise PLAN/READ/EDIT/CHECK lines at the stream boundary.
 */
if (!function_exists('ptero_ai_chat_agent_activity_bridge')) {
    function ptero_ai_chat_agent_activity_bridge() {
        ?>
        <script>
        (function () {
            if (window.__pteroAiAgentActivityBridge || !window.fetch || !window.ReadableStream) {
                return;
            }
            window.__pteroAiAgentActivityBridge = true;

            var nativeFetch = window.fetch.bind(window);
            var markerPattern = /^\s*(PLAN|THINK|READ|EDIT|CHECK)\s*:\s*(.*?)\s*$/;

            function activityType(marker) {
                marker = String(marker || '').toUpperCase();
                if (marker === 'READ') return 'reading';
                if (marker === 'EDIT') return 'editing';
                if (marker === 'CHECK') return 'checking';
                return 'thinking';
            }

            function encodeEvent(payload) {
                return new TextEncoder().encode('data: ' + JSON.stringify(payload) + "\n\n");
            }

            function copyWithToken(payload, token) {
                var next = {};
                Object.keys(payload || {}).forEach(function (key) {
                    next[key] = payload[key];
                });
                next.token = token;
                return next;
            }

            function emitToken(controller, payload, token) {
                if (token) {
                    controller.enqueue(encodeEvent(copyWithToken(payload, token)));
                }
            }

            function emitActivity(controller, marker, label) {
                if (label) {
                    controller.enqueue(encodeEvent({
                        activity: {
                            type: activityType(marker),
                            label: label
                        }
                    }));
                }
            }

            function transformToken(controller, payload, state) {
                state.tokenBuffer += String(payload.token || '');
                var lines = state.tokenBuffer.split(/\r?\n/);
                state.tokenBuffer = lines.pop();
                var ordinary = '';

                lines.forEach(function (line) {
                    var match = null;
                    if (/^\s*```/.test(line)) {
                        state.inFence = !state.inFence;
                    } else if (!state.inFence) {
                        match = markerPattern.exec(line);
                    }
                    if (match && match[2]) {
                        emitToken(controller, payload, ordinary);
                        ordinary = '';
                        state.statusLines.push(line);
                        emitActivity(controller, match[1], match[2].trim());
                    } else {
                        ordinary += line + "\n";
                        if (line.trim()) state.sawOrdinary = true;
                    }
                });
                emitToken(controller, payload, ordinary);
            }

            function flushTrailingToken(controller, state) {
                if (!state.tokenBuffer) return;
                var match = state.inFence ? null : markerPattern.exec(state.tokenBuffer);
                if (match && match[2]) {
                    state.statusLines.push(state.tokenBuffer);
                    emitActivity(controller, match[1], match[2].trim());
                } else {
                    if (state.tokenBuffer.trim()) state.sawOrdinary = true;
                    emitToken(controller, { token: state.tokenBuffer }, state.tokenBuffer);
                }
                state.tokenBuffer = '';
            }

            function flushStatusFallback(controller, state) {
                if (state.fallbackDone) return;
                state.fallbackDone = true;
                if (!state.sawOrdinary && state.statusLines.length) {
                    var text = state.statusLines.join("\n") + "\n";
                    emitToken(controller, { token: text }, text);
                }
            }

            window.fetch = function (input, init) {
                var body = init && init.body;
                var params = null;
                try {
                    params = typeof body === 'string' ? JSON.parse(body) : null;
                } catch (ignore) {}

                if (!params || params.mode !== 'agent') {
                    return nativeFetch(input, init);
                }

                return nativeFetch(input, init).then(function (response) {
                    if (!response.body) return response;

                    var reader = response.body.getReader();
                    var decoder = new TextDecoder();
                    var encoder = new TextEncoder();
                    var buffer = '';
                    var state = { tokenBuffer: '', inFence: false, sawOrdinary: false, statusLines: [], fallbackDone: false };

                    function processEvent(event, controller) {
                        var raw = event.trim();
                        if (!raw) return;
                        if (raw.indexOf('data:') !== 0) {
                            controller.enqueue(encoder.encode(event + "\n\n"));
                            return;
                        }

                        var payload;
                        try {
                            payload = JSON.parse(raw.slice(5).trim());
                        } catch (ignore) {
                            controller.enqueue(encoder.encode(event + "\n\n"));
                            return;
                        }

                        if (!payload || typeof payload !== 'object' || typeof payload.token !== 'string') {
                            if (payload && payload.done) {
                                flushTrailingToken(controller, state);
                                flushStatusFallback(controller, state);
                            }
                            controller.enqueue(encodeEvent(payload));
                            return;
                        }

                        transformToken(controller, payload, state);
                    }

                    var stream = new ReadableStream({
                        start: function (controller) {
                            function pump() {
                                reader.read().then(function (result) {
                                    if (result.done) {
                                        buffer += decoder.decode();
                                        if (buffer) processEvent(buffer, controller);
                                        flushTrailingToken(controller, state);
                                        flushStatusFallback(controller, state);
                                        controller.close();
                                        return;
                                    }

                                    buffer += decoder.decode(result.value, { stream: true });
                                    var events = buffer.split(/\n\n/);
                                    buffer = events.pop();
                                    events.forEach(function (event) {
                                        processEvent(event, controller);
                                    });
                                    pump();
                                }).catch(function (error) {
                                    controller.error(error);
                                });
                            }
                            pump();
                        }
                    });

                    return new Response(stream, {
                        status: response.status,
                        statusText: response.statusText,
                        headers: response.headers
                    });
                });
            };
        }());
        </script>
        <?php
    }
    add_action('wp_footer', 'ptero_ai_chat_agent_activity_bridge', 99);
}

/*
 * A provider can still return a clean SSE "done" event after only emitting
 * agent progress markers. The activity bridge intentionally hides those
 * markers, so add one client-side recovery attempt before the chat UI is
 * allowed to finalize an empty answer.
 */
if (!function_exists('ptero_ai_chat_agent_completion_retry')) {
    function ptero_ai_chat_agent_completion_retry() {
        ?>
        <script>
        (function () {
            if (window.__pteroAiAgentCompletionRetry || !window.fetch || !window.ReadableStream) {
                return;
            }
            window.__pteroAiAgentCompletionRetry = true;

            var nativeFetch = window.fetch.bind(window);
            var statusLinePattern = /^\s*(PLAN|THINK|READ|EDIT|CHECK)\s*:[^\r\n]*(?:\r?\n|$)/gim;

            function requestParams(init) {
                if (!init || typeof init.body !== 'string') {
                    return null;
                }
                try {
                    var params = JSON.parse(init.body);
                    return params && typeof params === 'object' ? params : null;
                } catch (ignore) {
                    return null;
                }
            }

            function containsFinalText(token) {
                var text = String(token || '').replace(statusLinePattern, '').trim();
                return !!text;
            }

            function retryInit(init, params) {
                var next = Object.assign({}, init || {});
                var original = String(params.message || '');
                params.mode = 'agent';
                params._ptero_agent_completion_retry = 1;
                params.message =
                    "The previous attempt emitted progress updates but did not deliver the result. " +
                    "Continue the original task now. Do not write another plan or status-only response. " +
                    "Return the complete final answer and any requested code or implementation.\n\n" +
                    original;
                next.body = JSON.stringify(params);
                return next;
            }

            function shouldRetry(state) {
                if (state.sawFinalText || state.retryUsed) {
                    return false;
                }
                if (state.error) {
                    return /status updates|final answer|stopped before|did not deliver/i.test(state.error);
                }
                return !!state.done;
            }

            function consumeResponse(response, controller, input, init, state, allowRetry) {
                if (!response || !response.body || typeof response.body.getReader !== 'function') {
                    controller.error(new Error('Agent response did not contain a readable stream.'));
                    return;
                }

                var reader = response.body.getReader();
                var decoder = new TextDecoder();
                var encoder = new TextEncoder();
                var buffer = '';
                var closed = false;

                function emit(raw) {
                    if (!closed && raw) {
                        controller.enqueue(encoder.encode(raw + "\n\n"));
                    }
                }

                function retryOrFinish() {
                    if (closed) {
                        return;
                    }
                    if (allowRetry && shouldRetry(state)) {
                        state.retryUsed = true;
                        try {
                            reader.cancel();
                        } catch (ignore) {}
                        nativeFetch(input, retryInit(init, requestParams(init) || {})).then(function (nextResponse) {
                            if (!nextResponse || !nextResponse.ok) {
                                closed = true;
                                controller.close();
                                return;
                            }
                            consumeResponse(nextResponse, controller, input, retryInit(init, requestParams(init) || {}), state, false);
                        }).catch(function (error) {
                            closed = true;
                            controller.error(error);
                        });
                        return;
                    }
                    if (state.donePayload) {
                        controller.enqueue(encoder.encode('data: ' + JSON.stringify(state.donePayload) + "\n\n"));
                    }
                    closed = true;
                    controller.close();
                }

                function processEvent(event) {
                    var raw = event.trim();
                    if (!raw) {
                        return;
                    }
                    if (raw.indexOf('data:') !== 0) {
                        emit(event);
                        return;
                    }

                    var payload;
                    try {
                        payload = JSON.parse(raw.slice(5).trim());
                    } catch (ignore) {
                        emit(event);
                        return;
                    }

                    if (payload && typeof payload.token === 'string') {
                        if (containsFinalText(payload.token)) {
                            state.sawFinalText = true;
                        }
                        emit(event);
                        return;
                    }
                    if (payload && payload.error) {
                        state.error = String(payload.error);
                        if (!shouldRetry(state)) {
                            emit(event);
                        }
                        return;
                    }
                    if (payload && payload.done) {
                        state.done = true;
                        state.donePayload = payload;
                        return;
                    }
                    emit(event);
                }

                function pump() {
                    reader.read().then(function (result) {
                        if (result.done) {
                            buffer += decoder.decode();
                            if (buffer) {
                                buffer.split(/\n\n/).forEach(processEvent);
                            }
                            retryOrFinish();
                            return;
                        }
                        buffer += decoder.decode(result.value, { stream: true });
                        var events = buffer.split(/\n\n/);
                        buffer = events.pop();
                        events.forEach(processEvent);
                        pump();
                    }).catch(function (error) {
                        if (allowRetry && shouldRetry(state)) {
                            retryOrFinish();
                            return;
                        }
                        if (!closed) {
                            closed = true;
                            controller.error(error);
                        }
                    });
                }
                pump();
            }

            window.fetch = function (input, init) {
                var params = requestParams(init);
                if (!params || params.mode !== 'agent' || params._ptero_agent_completion_retry) {
                    return nativeFetch(input, init);
                }

                return nativeFetch(input, init).then(function (response) {
                    if (!response || !response.ok || !response.body) {
                        return response;
                    }

                    var stream = new ReadableStream({
                        start: function (controller) {
                            consumeResponse(response, controller, input, init, {
                                sawFinalText: false,
                                retryUsed: false,
                                done: false,
                                donePayload: null,
                                error: ''
                            }, true);
                        }
                    });

                    return new Response(stream, {
                        status: response.status,
                        statusText: response.statusText,
                        headers: response.headers
                    });
                });
            };
        }());
        </script>
        <?php
    }
    add_action('wp_footer', 'ptero_ai_chat_agent_completion_retry', 100);
}

/**
 * Referral rewards
 *
 * Referral identities are linked to the same GitHub identities used by the
 * chat experience. A successful first chat by an invited identity creates one
 * immutable referral record. Referral rewards are tracked separately and
 * never change API-key usage, API-key limits, or GitHub-star quota limits.
 */
final class Ptero_AI_Referral_System {
    const VERSION = '1.2.0';
    const CODE_COOKIE = 'mlp_ai_referral_code';
    const CODE_QUERY_ARG = 'mlp_ref';
    const COOKIE_DAYS = 30;
    const GITHUB_LOGIN_OPTION = 'ptero_ai_referral_github_logins';
    const GITHUB_STATE_PREFIX = 'ptero_ai_referral_github_state_';

    private static $codes_table = '';
    private static $referrals_table = '';
    public static function boot() {
        global $wpdb;

        self::$codes_table = $wpdb->prefix . 'mlp_ai_referral_codes';
        self::$referrals_table = $wpdb->prefix . 'mlp_ai_referrals';

        register_activation_hook(__FILE__, array(__CLASS__, 'activate'));
        add_action('plugins_loaded', array(__CLASS__, 'ensure_tables'), 32);
        add_action('init', array(__CLASS__, 'capture_referral_visit'), 1);
        add_action('rest_api_init', array(__CLASS__, 'register_routes'));
        add_filter('rest_request_after_callbacks', array(__CLASS__, 'complete_after_chat'), 99, 3);
        add_action('wp_head', array(__CLASS__, 'render_assets'), 101);
        add_action('wp_footer', array(__CLASS__, 'render_assets'), 101);
        add_action('admin_footer', array(__CLASS__, 'render_assets'), 101);
    }

    public static function activate() {
        self::ensure_tables();
    }

    public static function ensure_tables() {
        global $wpdb;

        $charset = $wpdb->get_charset_collate();
        require_once ABSPATH . 'wp-admin/includes/upgrade.php';

        $codes = $wpdb->prefix . 'mlp_ai_referral_codes';
        $referrals = $wpdb->prefix . 'mlp_ai_referrals';

        dbDelta("CREATE TABLE {$codes} (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            code VARCHAR(32) NOT NULL,
            referrer_identity VARCHAR(100) NOT NULL,
            referrer_label VARCHAR(100) NOT NULL DEFAULT '',
            created_at DATETIME NOT NULL,
            PRIMARY KEY (id),
            UNIQUE KEY code (code),
            UNIQUE KEY referrer_identity (referrer_identity)
        ) {$charset};");

        dbDelta("CREATE TABLE {$referrals} (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            referral_code VARCHAR(32) NOT NULL,
            referrer_identity VARCHAR(100) NOT NULL,
            referrer_label VARCHAR(100) NOT NULL DEFAULT '',
            referred_identity VARCHAR(100) NOT NULL,
            referred_label VARCHAR(100) NOT NULL DEFAULT '',
            referrer_reward BIGINT UNSIGNED NOT NULL DEFAULT 0,
            referred_reward BIGINT UNSIGNED NOT NULL DEFAULT 0,
            referrer_claimed_at DATETIME NULL DEFAULT NULL,
            referred_claimed_at DATETIME NULL DEFAULT NULL,
            status VARCHAR(20) NOT NULL DEFAULT 'completed',
            created_at DATETIME NOT NULL,
            completed_at DATETIME NOT NULL,
            PRIMARY KEY (id),
            UNIQUE KEY referred_identity (referred_identity),
            KEY referrer_identity (referrer_identity),
            KEY referral_code (referral_code),
            KEY completed_at (completed_at)
        ) {$charset};");

        /*
         * dbDelta can leave existing tables untouched when a site is upgraded
         * from an older referral schema. Add the claim columns explicitly so
         * the referral list and claim endpoint work on existing installs too.
         */
        $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM {$referrals}");
        if (is_array($existing_columns) && !in_array('referrer_claimed_at', $existing_columns, true)) {
            $wpdb->query("ALTER TABLE {$referrals} ADD COLUMN referrer_claimed_at DATETIME NULL DEFAULT NULL AFTER referred_reward");
            $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM {$referrals}");
        }
        if (is_array($existing_columns) && !in_array('referred_claimed_at', $existing_columns, true)) {
            $after = in_array('referrer_claimed_at', $existing_columns, true)
                ? 'referrer_claimed_at'
                : 'referred_reward';
            $wpdb->query("ALTER TABLE {$referrals} ADD COLUMN referred_claimed_at DATETIME NULL DEFAULT NULL AFTER {$after}");
        }

        update_option('ptero_ai_referrals_version', self::VERSION, false);
        self::$codes_table = $codes;
        self::$referrals_table = $referrals;
    }

    private static function table_exists($table) {
        global $wpdb;
        return (bool) $wpdb->get_var($wpdb->prepare(
            'SHOW TABLES LIKE %s',
            $wpdb->esc_like($table)
        ));
    }

    private static function referrer_reward() {
        return max(0, (int) apply_filters('ptero_ai_referrer_reward_tokens', 50000));
    }

    private static function referred_reward() {
        return max(0, (int) apply_filters('ptero_ai_referred_reward_tokens', 25000));
    }

    private static function identity_from_request($request) {
        global $wpdb;

        $github_login = self::github_login_from_request($request);
        if ($github_login) {
            return self::github_identity($github_login);
        }

        $user_id = get_current_user_id();
        if ($user_id) {
            return 'u:' . (int) $user_id;
        }

        $authorization = $request instanceof WP_REST_Request
            ? (string) $request->get_header('authorization')
            : '';
        if (preg_match('/^Bearer\s+([A-Za-z0-9_-]{20,120})$/i', $authorization, $matches)) {
            $table = $wpdb->prefix . 'mlp_ai_api_keys';
            if (self::table_exists($table)) {
                $key_id = $wpdb->get_var($wpdb->prepare(
                    "SELECT id FROM {$table} WHERE key_hash = %s AND revoked_at IS NULL LIMIT 1",
                    hash('sha256', $matches[1])
                ));
                if ($key_id) {
                    return 'k:' . (int) $key_id;
                }
            }
        }

        $raw = $request instanceof WP_REST_Request
            ? $request->get_header('x-mlp-guest-token')
            : '';
        if (empty($raw) && !empty($_COOKIE['mlp_ai_guest_token'])) {
            $raw = wp_unslash($_COOKIE['mlp_ai_guest_token']);
        }
        $token = substr(preg_replace('/[^a-zA-Z0-9]/', '', (string) $raw), 0, 64);
        return $token ? 'g:' . $token : '';
    }

    private static function label_from_request($request) {
        $user_id = get_current_user_id();
        if ($user_id) {
            $user = get_userdata($user_id);
            return $user ? mb_substr(sanitize_text_field($user->display_name), 0, 100) : 'WordPress user';
        }

        $label = $request instanceof WP_REST_Request
            ? $request->get_header('x-mlp-guest-username')
            : '';
        return mb_substr(sanitize_text_field((string) $label), 0, 100);
    }

    public static function capture_referral_visit() {
        if (empty($_GET[self::CODE_QUERY_ARG])) {
            return;
        }

        $code = sanitize_text_field(wp_unslash($_GET[self::CODE_QUERY_ARG]));
        if (!preg_match('/^[A-Za-z0-9]{8,32}$/', $code)) {
            return;
        }

        setcookie(
            self::CODE_COOKIE,
            $code,
            time() + (self::COOKIE_DAYS * DAY_IN_SECONDS),
            COOKIEPATH ? COOKIEPATH : '/',
            defined('COOKIE_DOMAIN') ? COOKIE_DOMAIN : '',
            is_ssl(),
            true
        );
        $_COOKIE[self::CODE_COOKIE] = $code;
    }

    private static function stored_code($identity) {
        global $wpdb;
        if (!$identity || !self::table_exists(self::$codes_table)) {
            return '';
        }
        return (string) $wpdb->get_var($wpdb->prepare(
            "SELECT code FROM " . self::$codes_table . " WHERE referrer_identity = %s LIMIT 1",
            $identity
        ));
    }

    private static function ensure_code($identity, $label) {
        global $wpdb;
        if (!$identity || !self::table_exists(self::$codes_table)) {
            return '';
        }

        $existing = self::stored_code($identity);
        if ($existing) {
            if ($label) {
                $wpdb->update(
                    self::$codes_table,
                    array('referrer_label' => $label),
                    array('referrer_identity' => $identity),
                    array('%s'),
                    array('%s')
                );
            }
            return $existing;
        }

        for ($attempt = 0; $attempt < 3; $attempt++) {
            $code = preg_replace('/[^A-Za-z0-9]/', '', wp_generate_password(12, false, false));
            if (strlen($code) < 8) {
                continue;
            }
            $inserted = $wpdb->insert(
                self::$codes_table,
                array(
                    'code' => $code,
                    'referrer_identity' => $identity,
                    'referrer_label' => $label,
                    'created_at' => current_time('mysql'),
                ),
                array('%s', '%s', '%s', '%s')
            );
            if ($inserted) {
                return $code;
            }
        }

        return self::stored_code($identity);
    }

    private static function complete_referral($identity, $label) {
        global $wpdb;
        if (!$identity || !self::table_exists(self::$codes_table) || !self::table_exists(self::$referrals_table)) {
            return false;
        }

        $code = !empty($_COOKIE[self::CODE_COOKIE])
            ? sanitize_text_field(wp_unslash($_COOKIE[self::CODE_COOKIE]))
            : '';
        if (!$code || !preg_match('/^[A-Za-z0-9]{8,32}$/', $code)) {
            return false;
        }

        $referrer = $wpdb->get_row($wpdb->prepare(
            "SELECT code, referrer_identity, referrer_label FROM " . self::$codes_table . " WHERE code = %s LIMIT 1",
            $code
        ), ARRAY_A);
        if (!$referrer || empty($referrer['referrer_identity']) || $referrer['referrer_identity'] === $identity) {
            return false;
        }

        $already_referred = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM " . self::$referrals_table . " WHERE referred_identity = %s LIMIT 1",
            $identity
        ));
        if ($already_referred) {
            self::clear_referral_cookie();
            return false;
        }

        $now = current_time('mysql');
        $inserted = $wpdb->insert(
            self::$referrals_table,
            array(
                'referral_code' => $referrer['code'],
                'referrer_identity' => $referrer['referrer_identity'],
                'referrer_label' => sanitize_text_field($referrer['referrer_label']),
                'referred_identity' => $identity,
                'referred_label' => $label,
                'referrer_reward' => self::referrer_reward(),
                'referred_reward' => self::referred_reward(),
                'status' => 'completed',
                'created_at' => $now,
                'completed_at' => $now,
            ),
            array('%s', '%s', '%s', '%s', '%s', '%d', '%d', '%s', '%s', '%s')
        );
        if ($inserted) {
            // Referral rewards are bookkeeping only. They must never be applied to
            // the chat quota option, API-key usage, or GitHub-star quota.
            self::clear_referral_cookie();
            return true;
        }

        return false;
    }

    private static function clear_referral_cookie() {
        setcookie(
            self::CODE_COOKIE,
            '',
            time() - HOUR_IN_SECONDS,
            COOKIEPATH ? COOKIEPATH : '/',
            defined('COOKIE_DOMAIN') ? COOKIE_DOMAIN : '',
            is_ssl(),
            true
        );
        unset($_COOKIE[self::CODE_COOKIE]);
    }

    public static function get_bonus_tokens($identity) {
        global $wpdb;
        if (!$identity || !self::table_exists(self::$referrals_table)) {
            return 0;
        }

        $bonus = $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(
                CASE
                    WHEN referrer_identity = %s THEN referrer_reward
                    WHEN referred_identity = %s THEN referred_reward
                    ELSE 0
                END
            ), 0)
            FROM " . self::$referrals_table . "
            WHERE referrer_identity = %s OR referred_identity = %s",
            $identity,
            $identity,
            $identity,
            $identity
        ));
        return max(0, (int) $bonus);
    }

    private static function summary($request) {
        global $wpdb;
        $identity = self::identity_from_request($request);
        if (!$identity || strpos($identity, 'gh:') !== 0) {
            return new WP_Error(
                'github_login_required',
                'Connect GitHub before using Invite & earn so your rewards stay linked to your account.',
                array('status' => 401)
            );
        }

        $label = self::label_from_request($request);
        $code = self::ensure_code($identity, $label);
        $count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . self::$referrals_table . " WHERE referrer_identity = %s AND status = 'completed'",
            $identity
        ));
        $earned = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(referrer_reward), 0) FROM " . self::$referrals_table . " WHERE referrer_identity = %s AND status = 'completed'",
            $identity
        ));
        $claimable = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(referrer_reward), 0) FROM " . self::$referrals_table . " WHERE referrer_identity = %s AND status = 'completed' AND referrer_claimed_at IS NULL",
            $identity
        ));
        $bonus = self::get_bonus_tokens($identity);
        $referral_users = $wpdb->get_results($wpdb->prepare(
            "SELECT id, referred_label, referrer_reward, referrer_claimed_at
             FROM " . self::$referrals_table . "
             WHERE referrer_identity = %s AND status = 'completed'
             ORDER BY completed_at DESC, id DESC",
            $identity
        ), ARRAY_A);
        $incoming_referrals = $wpdb->get_results($wpdb->prepare(
            "SELECT id, referrer_label, referred_reward, referred_claimed_at
             FROM " . self::$referrals_table . "
             WHERE referred_identity = %s AND status = 'completed'
             ORDER BY completed_at DESC, id DESC",
            $identity
        ), ARRAY_A);

        return rest_ensure_response(array(
            'code' => $code,
            'link' => add_query_arg(self::CODE_QUERY_ARG, $code, home_url('/')),
            'referrals' => $count,
            'earned_tokens' => $earned,
            'claimable_tokens' => $claimable,
            'bonus_tokens' => $bonus,
            'quota_updated' => false,
            'api_key_tokens_per_hour' => 500000,
            'github_star_tokens_per_hour' => 1000000,
            'quota_note' => 'Platform-only rewards: Invite & earn rewards are available inside this platform and are not for API. They never change API-key usage or quota limits.',
            'referrer_reward' => self::referrer_reward(),
            'referred_reward' => self::referred_reward(),
            'reward_unit' => 'tokens per hour',
            'referral_users' => array_map(function ($row) {
                return array(
                    'id' => (int) $row['id'],
                    'label' => $row['referred_label'] ? $row['referred_label'] : 'Referral user',
                    'reward' => (int) $row['referrer_reward'],
                    'claimed' => !empty($row['referrer_claimed_at']),
                );
            }, is_array($referral_users) ? $referral_users : array()),
            'incoming_referrals' => array_map(function ($row) {
                return array(
                    'id' => (int) $row['id'],
                    'label' => $row['referrer_label'] ? $row['referrer_label'] : 'Your inviter',
                    'reward' => (int) $row['referred_reward'],
                    'claimed' => !empty($row['referred_claimed_at']),
                );
            }, is_array($incoming_referrals) ? $incoming_referrals : array()),
        ));
    }

    public static function register_routes() {
        register_rest_route('mlp/v1', '/referrals/github/authorize', array(
            'methods' => 'GET',
            'callback' => array(__CLASS__, 'rest_github_authorize'),
            'permission_callback' => '__return_true',
        ));
        register_rest_route('mlp/v1', '/referrals/github/callback', array(
            'methods' => 'GET',
            'callback' => array(__CLASS__, 'rest_github_callback'),
            'permission_callback' => '__return_true',
        ));
        register_rest_route('mlp/v1', '/referrals', array(
            'methods' => 'GET',
            'callback' => array(__CLASS__, 'rest_summary'),
            'permission_callback' => '__return_true',
        ));
        register_rest_route('mlp/v1', '/referrals/(?P<id>\d+)/claim', array(
            'methods' => 'POST',
            'callback' => array(__CLASS__, 'rest_claim'),
            'permission_callback' => '__return_true',
            'args' => array(
                'id' => array(
                    'required' => true,
                    'validate_callback' => function ($value) {
                        return (int) $value > 0;
                    },
                ),
            ),
        ));
        register_rest_route('mlp/v1', '/referrals/claim-earned', array(
            'methods' => 'POST',
            'callback' => array(__CLASS__, 'rest_claim_earned'),
            'permission_callback' => '__return_true',
        ));
    }

    private static function github_is_configured() {
        return defined('MLP_GITHUB_CLIENT_ID')
            && MLP_GITHUB_CLIENT_ID
            && defined('MLP_GITHUB_CLIENT_SECRET')
            && MLP_GITHUB_CLIENT_SECRET;
    }

    private static function guest_token_from_request($request) {
        $raw = $request instanceof WP_REST_Request
            ? $request->get_header('x-mlp-guest-token')
            : '';
        if (empty($raw) && !empty($_COOKIE['mlp_ai_guest_token'])) {
            $raw = wp_unslash($_COOKIE['mlp_ai_guest_token']);
        }
        $token = substr(preg_replace('/[^a-zA-Z0-9]/', '', (string) $raw), 0, 64);
        if (!$token && get_current_user_id()) {
            $token = 'u' . (int) get_current_user_id();
        }
        return $token;
    }

    private static function github_login_map() {
        $map = get_option(self::GITHUB_LOGIN_OPTION, array());
        return is_array($map) ? $map : array();
    }

    private static function github_login_from_request($request) {
        $guest = self::guest_token_from_request($request);
        if (!$guest) {
            return '';
        }
        $maps = array(
            get_option('mlp_ai_github_verified', array()),
            self::github_login_map(),
        );
        foreach ($maps as $map) {
            $login = is_array($map) && isset($map[$guest]['login'])
                ? $map[$guest]['login']
                : '';
            if (preg_match('/^[A-Za-z0-9-]{1,39}$/', (string) $login)) {
                self::bind_guest_rewards($guest, $login);
                return (string) $login;
            }
        }
        return '';
    }

    private static function github_identity($login) {
        $login = strtolower(sanitize_text_field((string) $login));
        return preg_match('/^[a-z0-9-]{1,39}$/', $login) ? 'gh:' . $login : '';
    }

    private static function bind_guest_rewards($guest, $login) {
        global $wpdb;

        $github_identity = self::github_identity($login);
        if (!$guest || !$github_identity) {
            return;
        }

        $old_identity = get_current_user_id()
            ? 'u:' . (int) get_current_user_id()
            : 'g:' . $guest;
        if ($old_identity === $github_identity) {
            return;
        }

        if (self::table_exists(self::$referrals_table)) {
            $existing_referred = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM " . self::$referrals_table . " WHERE referred_identity = %s LIMIT 1",
                $github_identity
            ));
            if (!$existing_referred) {
                $wpdb->query($wpdb->prepare(
                    "UPDATE " . self::$referrals_table . " SET referred_identity = %s WHERE referred_identity = %s",
                    $github_identity,
                    $old_identity
                ));
            }
            $wpdb->query($wpdb->prepare(
                "UPDATE " . self::$referrals_table . " SET referrer_identity = %s WHERE referrer_identity = %s",
                $github_identity,
                $old_identity
            ));
        }

        if (self::table_exists(self::$codes_table)) {
            $existing_code = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM " . self::$codes_table . " WHERE referrer_identity = %s LIMIT 1",
                $github_identity
            ));
            if (!$existing_code) {
                $wpdb->query($wpdb->prepare(
                    "UPDATE " . self::$codes_table . " SET referrer_identity = %s WHERE referrer_identity = %s",
                    $github_identity,
                    $old_identity
                ));
            }
        }
    }

    private static function remember_github_login($guest, $login) {
        if (!$guest || !$login) {
            return;
        }
        $map = self::github_login_map();
        $map[$guest] = array(
            'login' => sanitize_text_field($login),
            'time' => current_time('mysql'),
        );
        update_option(self::GITHUB_LOGIN_OPTION, $map, false);
        self::bind_guest_rewards($guest, $login);
    }

    private static function github_popup_response($success, $login, $error) {
        $payload = wp_json_encode(array(
            'source' => 'ptero-referral-github',
            'success' => (bool) $success,
            'login' => (string) $login,
            'error' => (string) $error,
        ));
        $origin = home_url('/');
        $message = $success
            ? 'GitHub account @' . $login . ' connected. Your referral rewards are now linked to this account.'
            : ($error ? $error : 'GitHub sign-in failed.');
        $html = '<!doctype html><html><head><meta charset="utf-8"><title>GitHub sign-in</title>';
        $html .= '<meta name="viewport" content="width=device-width, initial-scale=1">';
        $html .= '<style>body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#0d1117;color:#e6edf3;display:flex;align-items:center;justify-content:center;min-height:100vh;text-align:center;padding:24px}.card{max-width:380px}.icon{font-size:40px;line-height:1;margin-bottom:14px}h1{font-size:17px;margin:0 0 8px}p{font-size:13px;color:#8b949e;margin:0;line-height:1.5}</style></head><body>';
        $html .= '<div class="card"><div class="icon">' . ($success ? '&#10003;' : '&#9888;&#65039;') . '</div>';
        $html .= '<h1>' . esc_html($success ? 'GitHub connected' : 'Sign-in failed') . '</h1>';
        $html .= '<p>' . esc_html($message) . '</p></div>';
        $html .= '<script>(function(){try{if(window.opener){window.opener.postMessage(' . $payload . ',' . wp_json_encode($origin) . ');}}catch(e){}setTimeout(function(){window.close();},' . ($success ? '900' : '2400') . ');})();</script></body></html>';
        while (ob_get_level()) {
            ob_end_clean();
        }
        header('Content-Type: text/html; charset=utf-8');
        echo $html;
        exit;
    }

    public static function rest_github_authorize(WP_REST_Request $request) {
        if (!self::github_is_configured()) {
            return self::github_popup_response(false, '', 'GitHub sign-in is not configured on this site yet.');
        }

        $guest = self::guest_token_from_request($request);
        if (!$guest) {
            return self::github_popup_response(false, '', 'Open Invite & earn from the chat so your account can be linked.');
        }

        $state = wp_generate_password(40, false, false);
        set_transient(
            self::GITHUB_STATE_PREFIX . hash('sha256', $state),
            array('guest' => $guest),
            10 * MINUTE_IN_SECONDS
        );
        $url = add_query_arg(array(
            'client_id' => MLP_GITHUB_CLIENT_ID,
            'redirect_uri' => rest_url('mlp/v1/referrals/github/callback'),
            'scope' => 'read:user',
            'state' => $state,
        ), 'https://github.com/login/oauth/authorize');
        wp_safe_redirect($url);
        exit;
    }

    public static function rest_github_callback(WP_REST_Request $request) {
        if (!self::github_is_configured()) {
            return self::github_popup_response(false, '', 'GitHub sign-in is not configured on this site yet.');
        }

        if ($request->get_param('error')) {
            return self::github_popup_response(false, '', 'GitHub sign-in was cancelled.');
        }

        $state = sanitize_text_field((string) $request->get_param('state'));
        $state_key = self::GITHUB_STATE_PREFIX . hash('sha256', $state);
        $state_data = get_transient($state_key);
        delete_transient($state_key);
        $guest = is_array($state_data) && !empty($state_data['guest'])
            ? (string) $state_data['guest']
            : '';
        $code = sanitize_text_field((string) $request->get_param('code'));
        if (!$guest || !$code) {
            return self::github_popup_response(false, '', 'Sign-in could not be verified. Please try again.');
        }

        $token_response = wp_remote_post('https://github.com/login/oauth/access_token', array(
            'timeout' => 15,
            'headers' => array('Accept' => 'application/json'),
            'body' => array(
                'client_id' => MLP_GITHUB_CLIENT_ID,
                'client_secret' => MLP_GITHUB_CLIENT_SECRET,
                'code' => $code,
                'redirect_uri' => rest_url('mlp/v1/referrals/github/callback'),
            ),
        ));
        if (is_wp_error($token_response)) {
            return self::github_popup_response(false, '', 'Could not reach GitHub. Please try again.');
        }
        $token_data = json_decode(wp_remote_retrieve_body($token_response), true);
        $access_token = is_array($token_data) && !empty($token_data['access_token'])
            ? (string) $token_data['access_token']
            : '';
        if (!$access_token) {
            return self::github_popup_response(false, '', 'GitHub did not return an access token.');
        }

        $user_response = wp_remote_get('https://api.github.com/user', array(
            'timeout' => 15,
            'headers' => array(
                'Authorization' => 'Bearer ' . $access_token,
                'Accept' => 'application/vnd.github+json',
                'User-Agent' => 'Ptero-AI-Chat',
            ),
        ));
        $user_data = is_wp_error($user_response)
            ? array()
            : json_decode(wp_remote_retrieve_body($user_response), true);
        $login = is_array($user_data) && !empty($user_data['login'])
            ? sanitize_text_field((string) $user_data['login'])
            : '';
        if (!preg_match('/^[A-Za-z0-9-]{1,39}$/', $login)) {
            return self::github_popup_response(false, '', 'GitHub did not return a valid account identity.');
        }

        self::remember_github_login($guest, $login);
        return self::github_popup_response(true, $login, '');
    }

    public static function rest_summary(WP_REST_Request $request) {
        return self::summary($request);
    }

    public static function rest_claim_earned(WP_REST_Request $request) {
        global $wpdb;

        $identity = self::identity_from_request($request);
        if (!$identity) {
            return new WP_Error(
                'referral_identity_required',
                'Start a chat before recording a referral reward.',
                array('status' => 400)
            );
        }

        /*
         * Lock the eligible rows before calculating the total. This keeps two
         * simultaneous clicks from crediting the same referral rewards twice.
         */
        $wpdb->query('START TRANSACTION');
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, referrer_reward
             FROM " . self::$referrals_table . "
             WHERE referrer_identity = %s
               AND status = 'completed'
               AND referrer_claimed_at IS NULL
             FOR UPDATE",
            $identity
        ), ARRAY_A);
        $rows = is_array($rows) ? $rows : array();
        $tokens = 0;
        foreach ($rows as $row) {
            $tokens += max(0, (int) $row['referrer_reward']);
        }

        if (!$tokens) {
            $wpdb->query('COMMIT');
            return new WP_Error(
                'referral_nothing_to_claim',
                'There are no unclaimed referral rewards.',
                array('status' => 409)
            );
        }

        $now = current_time('mysql');
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE " . self::$referrals_table . "
             SET referrer_claimed_at = %s
             WHERE referrer_identity = %s
               AND status = 'completed'
               AND referrer_claimed_at IS NULL",
            $now,
            $identity
        ));
        if ((int) $updated !== count($rows)) {
            $wpdb->query('ROLLBACK');
            return new WP_Error(
                    'referral_reward_update_failed',
                'Your referral reward could not be recorded. Please try again.',
                array('status' => 500)
            );
        }

        $wpdb->query('COMMIT');
        return rest_ensure_response(array(
            'claimed' => true,
            'tokens' => $tokens,
            'quota_updated' => false,
            'message' => sprintf(
                'Recorded %s referral reward tokens. Your API-key quota was not changed.',
                number_format_i18n($tokens)
            ),
        ));
    }

    public static function rest_claim(WP_REST_Request $request) {
        global $wpdb;

        $identity = self::identity_from_request($request);
        if (!$identity) {
            return new WP_Error(
                'referral_identity_required',
                'Start a chat before recording a referral reward.',
                array('status' => 400)
            );
        }

        $id = (int) $request->get_param('id');
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT id, referrer_identity, referred_identity, referrer_reward,
                    referred_reward, referrer_claimed_at, referred_claimed_at
             FROM " . self::$referrals_table . "
             WHERE id = %d AND status = 'completed'
             LIMIT 1",
            $id
        ), ARRAY_A);
        if (!$row) {
            return new WP_Error(
                'referral_not_found',
                'That referral could not be found.',
                array('status' => 404)
            );
        }

        if ($row['referrer_identity'] === $identity) {
            $role = 'referrer';
            $claimed_column = 'referrer_claimed_at';
            $reward = (int) $row['referrer_reward'];
        } elseif ($row['referred_identity'] === $identity) {
            $role = 'referred';
            $claimed_column = 'referred_claimed_at';
            $reward = (int) $row['referred_reward'];
        } else {
            return new WP_Error(
                'referral_forbidden',
                'You can only record a reward for your own referral.',
                array('status' => 403)
            );
        }

        if (!empty($row[$claimed_column])) {
            return new WP_Error(
                'referral_already_claimed',
                'The reward for this referral has already been recorded.',
                array('status' => 409)
            );
        }

        $now = current_time('mysql');
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE " . self::$referrals_table . "
             SET {$claimed_column} = %s
             WHERE id = %d AND status = 'completed'
               AND {$claimed_column} IS NULL",
            $now,
            $id
        ));
        if (1 !== (int) $updated) {
            return new WP_Error(
                'referral_already_claimed',
                'The reward for this referral has already been recorded.',
                array('status' => 409)
            );
        }

        return rest_ensure_response(array(
            'claimed' => true,
            'role' => $role,
            'tokens' => $reward,
            'quota_updated' => false,
            'message' => sprintf(
                'Recorded %s referral reward tokens. Your API-key quota was not changed.',
                number_format_i18n($reward)
            ),
        ));
    }

    public static function complete_after_chat($response, $handler, $request) {
        $route = $request instanceof WP_REST_Request ? $request->get_route() : '';
        if (!preg_match('#/mlp/v1/(?:chat|chat-stream)$#', (string) $route)) {
            return $response;
        }

        $status = is_object($response) && method_exists($response, 'get_status')
            ? (int) $response->get_status()
            : (is_wp_error($response) ? 500 : 200);
        $identity = self::identity_from_request($request);
        if ($status < 400 && $identity && strpos($identity, 'gh:') === 0) {
            self::complete_referral(
                $identity,
                self::label_from_request($request)
            );
        }
        return $response;
    }

