        ?>
        <script>
            window.PTERO_AI_REFERRAL_I18N = <?php echo wp_json_encode($referral_i18n); ?>;
            (function () {
                function text(key) {
                    var lang = 'en';
                    try { lang = String(localStorage.getItem('mlp_ai_chat_lang') || 'en').toLowerCase().split('-')[0]; } catch (e) {}
                    var translations = window.PTERO_AI_REFERRAL_I18N || {};
                    return (translations[lang] && translations[lang][key]) || (translations.en && translations.en[key]) || key;
                }
                window.pteroAiReferralT = text;
                function applyStaticTranslations() {
                    var launcher = document.getElementById('ptero-ai-referral-launcher');
                    if (launcher) launcher.textContent = text('button');
                    Array.prototype.forEach.call(document.querySelectorAll('[data-referral-i18n]'), function (element) {
                        element.textContent = text(element.getAttribute('data-referral-i18n'));
                    });
                    var closeButton = document.getElementById('chat-referrals-menu-btn');
                    if (closeButton) {
                        closeButton.setAttribute('aria-label', text('close'));
                        closeButton.setAttribute('title', text('close'));
                    }
                    Array.prototype.forEach.call(document.querySelectorAll('.ptero-ai-referral-close'), function (button) {
                        button.setAttribute('aria-label', text('close'));
                        button.setAttribute('title', text('close'));
                    });
                    var profileOutput = document.getElementById('chat-profile-inline-referrals-output');
                    if (profileOutput && profileOutput.dataset.inviteLink) {
                        profileOutput.textContent = text('yourLink') + ' ' + profileOutput.dataset.inviteLink;
                    }
                    var profileButton = document.getElementById('chat-profile-menu-referrals');
                    if (profileButton && !profileButton.dataset.referralI18nBound) {
                        profileButton.removeAttribute('onclick');
                        profileButton.dataset.referralI18nBound = '1';
                        profileButton.addEventListener('click', function (event) {
                            event.preventDefault();
                            event.stopPropagation();
                            var panel = document.getElementById('chat-profile-inline-referrals');
                            var output = document.getElementById('chat-profile-inline-referrals-output');
                            if (!panel || !output) return;
                            panel.hidden = false;
                            if (panel.dataset.loaded) return;
                            panel.dataset.loaded = '1';
                            output.textContent = text('loading');
                            var identity = {};
                            try { identity = JSON.parse(localStorage.getItem('mlp_ai_chat_identity') || 'null') || {}; } catch (e) {}
                            fetch(profileButton.dataset.referralEndpoint, {
                                credentials: 'same-origin',
                                headers: {
                                    'X-WP-Nonce': profileButton.dataset.referralNonce || '',
                                    'X-MLP-Guest-Token': identity.token || '',
                                    'X-MLP-Guest-Username': identity.username || ''
                                },
                                cache: 'no-store'
                            }).then(function (response) {
                                return response.json().then(function (data) {
                                    if (!response.ok) throw new Error(text('loadError'));
                                    return data;
                                });
                            }).then(function (data) {
                                profileOutput = document.getElementById('chat-profile-inline-referrals-output');
                                if (!profileOutput) return;
                                profileOutput.dataset.inviteLink = data.link || '';
                                profileOutput.textContent = text('yourLink') + ' ' + profileOutput.dataset.inviteLink;
                            }).catch(function () {
                                var currentOutput = document.getElementById('chat-profile-inline-referrals-output');
                                if (currentOutput) {
                                    currentOutput.setAttribute('data-referral-i18n', 'loadError');
                                    currentOutput.textContent = text('loadError');
                                }
                            });
                        });
                    }
                }
                window.pteroAiRefreshTranslations = applyStaticTranslations;
                function watchLanguagePicker() {
                    var label = document.querySelector('[data-language-current]');
                    if (label && window.MutationObserver && !label.dataset.referralI18nObserved) {
                        label.dataset.referralI18nObserved = '1';
                        new MutationObserver(applyStaticTranslations).observe(label, {
                            childList: true, characterData: true, subtree: true
                        });
                    }
                    applyStaticTranslations();
                }
                if (document.readyState === 'loading') {
                    document.addEventListener('DOMContentLoaded', watchLanguagePicker, { once: true });
                } else {
                    watchLanguagePicker();
                }
            }());
        </script>
        <style id="ptero-ai-referral-styles">
