             .ptero-ai-referral-link button, .ptero-ai-referral-reload { border:0; border-radius:8px; background:#10a37f; color:#fff; cursor:pointer; font-weight:700; padding:9px 12px; }
            .ptero-ai-referral-list { display:grid; gap:8px; margin-top:16px; }
