        <script>
        (function () {
            var endpoint = <?php echo wp_json_encode($endpoint); ?>;
            var githubAuthorizeEndpoint = <?php echo wp_json_encode($github_authorize); ?>;
            var nonce = <?php echo wp_json_encode($nonce); ?>;
            function identity() {
                try { return JSON.parse(localStorage.getItem('mlp_ai_chat_identity') || 'null') || {}; }
                catch (e) { return {}; }
            }
            function esc(value) {
                return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
                    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];
                });
            }
            function fmt(value) { return Number(value || 0).toLocaleString(); }
            function init() {
                if (!document.getElementById('chat-ai-chat-app') || document.getElementById('ptero-ai-referral-launcher')) return;
                var launcher = document.createElement('button');
                launcher.id = 'ptero-ai-referral-launcher';
                launcher.type = 'button';
                launcher.textContent = window.pteroAiReferralT('button');
                var modal = document.createElement('div');
                modal.id = 'ptero-ai-referral-modal';
                modal.hidden = true;
                modal.innerHTML = '<div class="ptero-ai-referral-box" role="dialog" aria-modal="true" aria-labelledby="ptero-ai-referral-title">' +
                    '<div class="ptero-ai-referral-head"><h2 id="ptero-ai-referral-title" data-referral-i18n="title">' + esc(window.pteroAiReferralT('title')) + '</h2><button class="ptero-ai-referral-close" type="button" aria-label="' + esc(window.pteroAiReferralT('close')) + '">&times;</button></div>' +
                     '<p class="ptero-ai-referral-muted" data-referral-i18n="intro">' + esc(window.pteroAiReferralT('intro')) + '</p>' +
                    '<div class="ptero-ai-referral-content"><p class="ptero-ai-referral-muted" data-referral-i18n="loading">' + esc(window.pteroAiReferralT('loading')) + '</p></div></div>';
                document.body.appendChild(launcher);
                document.body.appendChild(modal);
                var content = modal.querySelector('.ptero-ai-referral-content');
                function close() { modal.hidden = true; }
                function open() {
                    modal.hidden = false;
                    load();
                }
                function showGithubLoginPrompt(me) {
                    content.innerHTML = '<div style="padding:14px;border:1px solid #d9dce3;border-radius:10px;background:#f8fafc;"><strong data-referral-i18n="connectTitle" style="display:block;margin-bottom:6px;">' + esc(window.pteroAiReferralT('connectTitle')) + '</strong><p data-referral-i18n="account" style="margin:0 0 12px;color:#6b7280;font-size:12px;line-height:1.5;">' + esc(window.pteroAiReferralT('account')) + '</p><button type="button" data-referral-i18n="continue" class="ptero-ai-referral-github-login" style="border:0;border-radius:8px;background:#24292f;color:#fff;cursor:pointer;font-weight:700;padding:9px 12px;">' + esc(window.pteroAiReferralT('continue')) + '</button></div>';
                    var button = content.querySelector('.ptero-ai-referral-github-login');
                    if (!button) return;
                    button.addEventListener('click', function () {
                        button.disabled = true;
                        button.setAttribute('data-referral-i18n', 'waiting');
                        button.textContent = window.pteroAiReferralT('waiting');
                        var popup = window.open(githubAuthorizeEndpoint + '?purpose=api&guest=' + encodeURIComponent(me.token || ''), 'ptero_referral_github', 'width=640,height=720');
                        var finished = false;
                        function done() {
                            if (finished) return;
                            finished = true;
                            window.removeEventListener('message', onMessage);
                            if (popup && !popup.closed) popup.close();
                        }
                        function onMessage(event) {
                            var data = event && event.data;
                            if (!data || (data.source !== 'ptero-referral-github' && data.source !== 'mlp-github')) return;
                            done();
                            if (data.success || data.mlpGithubVerified) {
                                load();
                            } else {
                                button.disabled = false;
                                button.setAttribute('data-referral-i18n', 'continue');
                                button.textContent = window.pteroAiReferralT('continue');
                            }
                        }
                        window.addEventListener('message', onMessage);
                        var poll = setInterval(function () {
                            if (popup && popup.closed) {
                                clearInterval(poll);
                                done();
                                button.disabled = false;
                                button.setAttribute('data-referral-i18n', 'continue');
                                button.textContent = window.pteroAiReferralT('continue');
                            }
                        }, 700);
                        if (!popup) {
                            clearInterval(poll);
                            done();
                            button.disabled = false;
                            button.setAttribute('data-referral-i18n', 'popup');
                            button.textContent = window.pteroAiReferralT('popup');
                        }
                    });
                }
                function load() {
                    var me = identity();
                    var headers = {'X-WP-Nonce':nonce, 'X-MLP-Guest-Token':me.token || '', 'X-MLP-Guest-Username':me.username || ''};
                    fetch(endpoint, {credentials:'same-origin', headers:headers, cache:'no-store'})
                        .then(function (res) { return res.json().then(function (data) { if (!res.ok) { var error = new Error(window.pteroAiReferralT('loadError')); error.code = data.code || ''; throw error; } return data; }); })
                        .then(function (data) {
                            var referralUsers = Array.isArray(data.referral_users) ? data.referral_users : [];
                            var incomingReferrals = Array.isArray(data.incoming_referrals) ? data.incoming_referrals : [];
                            var referralRows = referralUsers.map(function (referral) {
                                return '<div class="ptero-ai-referral-row"><div class="ptero-ai-referral-row-main"><div class="ptero-ai-referral-row-name">' + esc(referral.label) + '</div><div class="ptero-ai-referral-row-reward">+' + fmt(referral.reward) + ' <span data-referral-i18n="rewardTokens">' + esc(window.pteroAiReferralT('rewardTokens')) + '</span></div></div></div>';
                            }).join('');
                            var incomingRows = incomingReferrals.map(function (referral) {
                                return '<div class="ptero-ai-referral-row"><div class="ptero-ai-referral-row-main"><div class="ptero-ai-referral-row-name">' + esc(referral.label) + '</div><div class="ptero-ai-referral-row-reward">+' + fmt(referral.reward) + ' <span data-referral-i18n="rewardTokens">' + esc(window.pteroAiReferralT('rewardTokens')) + '</span></div></div></div>';
                            }).join('');
                             var referralSection = referralRows
                                ? '<div class="ptero-ai-referral-section-title" data-referral-i18n="users">' + esc(window.pteroAiReferralT('users')) + '</div><div class="ptero-ai-referral-list">' + referralRows + '</div>'
                                : '<p class="ptero-ai-referral-note" data-referral-i18n="platformNote">' + esc(window.pteroAiReferralT('platformNote')) + '</p>';
                            content.innerHTML = '<div class="ptero-ai-referral-link"><input type="text" readonly value="' + esc(data.link) + '"><button type="button" data-referral-i18n="copy" class="ptero-ai-referral-copy">' + esc(window.pteroAiReferralT('copy')) + '</button></div>' +
                                '<div class="ptero-ai-referral-stats"><div class="ptero-ai-referral-stat"><strong>' + fmt(data.referrals) + '</strong><span data-referral-i18n="completed">' + esc(window.pteroAiReferralT('completed')) + '</span></div><div class="ptero-ai-referral-stat"><strong>' + fmt(data.earned_tokens) + '</strong><span data-referral-i18n="tracked">' + esc(window.pteroAiReferralT('tracked')) + '</span></div><div class="ptero-ai-referral-stat"><strong>+' + fmt(data.bonus_tokens) + '</strong><span data-referral-i18n="separate">' + esc(window.pteroAiReferralT('separate')) + '</span></div></div>' +
                                referralSection +
                                (incomingRows ? '<div class="ptero-ai-referral-section-title" data-referral-i18n="incoming">' + esc(window.pteroAiReferralT('incoming')) + '</div><div class="ptero-ai-referral-list">' + incomingRows + '</div>' : '') +
                                '<p class="ptero-ai-referral-note" data-referral-i18n="platformNote">' + esc(window.pteroAiReferralT('platformNote')) + '</p>';
                            content.querySelector('.ptero-ai-referral-copy').addEventListener('click', function () {
                                var input = content.querySelector('input');
                                input.select();
                                try { navigator.clipboard.writeText(input.value); } catch (e) { document.execCommand('copy'); }
                                this.setAttribute('data-referral-i18n', 'copied');
                                this.textContent = window.pteroAiReferralT('copied');
                                setTimeout(function () {
                                    var copyButton = content.querySelector('.ptero-ai-referral-copy');
                                    if (!copyButton) return;
                                    copyButton.setAttribute('data-referral-i18n', 'copy');
                                    copyButton.textContent = window.pteroAiReferralT('copy');
                                }, 1400);
                            });
                            if (window.pteroAiRefreshTranslations) window.pteroAiRefreshTranslations();
                        })
                        .catch(function (error) {
                            if (error && error.code === 'github_login_required') {
                                showGithubLoginPrompt(me);
                                return;
                            }
                            content.innerHTML = '<p class="ptero-ai-referral-error" data-referral-i18n="loadError">' + esc(window.pteroAiReferralT('loadError')) + '</p>';
                        });
                }
                launcher.addEventListener('click', open);
                modal.querySelector('.ptero-ai-referral-close').addEventListener('click', close);
                modal.addEventListener('click', function (event) { if (event.target === modal) close(); });
                document.addEventListener('keydown', function (event) { if (event.key === 'Escape') close(); });
            }
            if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
            else init();
        }());
        </script>
        <?php
    }
}

Ptero_AI_Referral_System::boot();

/*
 * API hardening layer.
 *
 * The compatibility endpoints are public-facing and can be called by clients
 * that do not use the bundled chat UI. Keep this guard independent from the
 * normal chat quota so a burst of API traffic is rejected before the request
 * reaches model selection, tool execution, or provider failover.
 */
if (!class_exists('Ptero_AI_API_Hardening')) {
    final class Ptero_AI_API_Hardening {
        const MAX_BODY_BYTES = 1048576; // 1 MiB, including base64 overhead.
        const REQUESTS_PER_MINUTE = 8;
        const GLOBAL_REQUESTS_PER_MINUTE = 30;
        const WINDOW_SECONDS = 60;

        public static function boot() {
            add_filter('rest_pre_dispatch', array(__CLASS__, 'guard'), 1, 3);
        }

        private static function protected_route($request) {
            if (!$request instanceof WP_REST_Request) {
                return false;
            }

            return (bool) preg_match(
                '#^/mlp/v1/(?:chat/completions|responses)/?$#',
                $request->get_route()
            );
        }

        private static function identity($request) {
            $authorization = strtolower(trim((string) $request->get_header('authorization')));
            if ($authorization !== '') {
                // Never put an API key itself into a transient key.
                return 'auth:' . hash('sha256', $authorization);
            }

            $guest = preg_replace(
                '/[^a-zA-Z0-9]/',
                '',
                (string) $request->get_header('x-mlp-guest-token')
            );
            if ($guest !== '') {
                return 'guest:' . substr($guest, 0, 64);
            }

            $ip = isset($_SERVER['REMOTE_ADDR'])
                ? sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR']))
                : 'unknown';
            return 'ip:' . $ip;
        }

        public static function guard($result, $server, $request) {
            if (!self::protected_route($request)) {
                return $result;
            }

            $content_length = isset($_SERVER['CONTENT_LENGTH'])
                ? absint($_SERVER['CONTENT_LENGTH'])
                : 0;
            if ($content_length > self::MAX_BODY_BYTES) {
                return new WP_Error(
                    'api_request_too_large',
                    'API request is too large. Limit the JSON body to 1 MiB.',
                    array(
                        'status' => 413,
                        'headers' => array('Retry-After' => '0'),
                    )
                );
            }

            $body = $request->get_body();
            if (strlen($body) > self::MAX_BODY_BYTES) {
                return new WP_Error(
                    'api_request_too_large',
                    'API request is too large. Limit the JSON body to 1 MiB.',
                    array(
                        'status' => 413,
                        'headers' => array('Retry-After' => '0'),
                    )
                );
            }

            $now = time();
            $limits = array(
                array(
                    'key' => 'ptero_api_hl_' . md5(self::identity($request)),
                    'limit' => self::REQUESTS_PER_MINUTE,
                ),
                array(
                    'key' => 'ptero_api_global_hl',
                    'limit' => self::GLOBAL_REQUESTS_PER_MINUTE,
                ),
            );
            $blocked_ttl = 0;
            $blocked_limit = self::REQUESTS_PER_MINUTE;
            foreach ($limits as $limit) {
                $state = get_transient($limit['key']);
                if (!is_array($state) || empty($state['reset_at']) || $now >= (int) $state['reset_at']) {
                    $state = array(
                        'count' => 0,
                        'reset_at' => $now + self::WINDOW_SECONDS,
                    );
                }
                $state['count']++;
                $ttl = max(1, (int) $state['reset_at'] - $now);
                set_transient($limit['key'], $state, $ttl);
                if ((int) $state['count'] > (int) $limit['limit']) {
                    $blocked_ttl = max($blocked_ttl, $ttl);
                    $blocked_limit = (int) $limit['limit'];
                }
            }

            if ($blocked_ttl > 0) {
                return new WP_Error(
                    'api_rate_limited',
                    'API rate limit exceeded. Try again in ' . $blocked_ttl . ' seconds.',
                    array(
                        'status' => 429,
                        'headers' => array(
                            'Retry-After' => (string) $blocked_ttl,
                            'X-RateLimit-Limit' => (string) $blocked_limit,
                            'X-RateLimit-Remaining' => '0',
                        ),
                    )
                );
            }

            return $result;
        }
    }

    Ptero_AI_API_Hardening::boot();
}

